// OmniFlow batch 241 - AI execution traces + audit linkage.
//
// Run from the WEBSITE repo root (the bot root - the folder that contains OmniFlow-Control-Plane/):
//     node ai_traces_241.mjs
// Needs batch 240 (analytics_quadrant_240.mjs) applied first. Safe to run twice (second run says "already"). Old copies are kept as *.pre_241.bak.
//
// 1) Configure AI -> AI operations -> new "Traces" tab: every AI answer step by step -
//    customer message -> safety check -> agent (and the version that was live) -> what it read (orders, knowledge base,
//    facts, memory, sales / loyalty context, with results) -> AI model (calls, tokens, latency, cost only when model
//    prices are set) -> decision (confidence, why it handed off) -> the reply that was queued (text + delivery status).
//    Filters: sent / handed off, answer type. Team members only (API keys get 403).
// 2) Activity rows written with an AI answer now show the agent + model and a "trace" link.
// 3) Every new AI answer records its model calls, phase timings, agent name and the LENGTH of the customer message.
//    The message and reply text are never copied into the trace - they are read live from their own tables, so
//    retention and deletes still cover them. No new table, no database migration.
//
// After running: git add -A, commit and push in BOTH repos (website + OmniFlow-Control-Plane).
import fs from "fs";
import { createRequire } from "module";
const require = createRequire(import.meta.url);
const BACKUP_TAG = ".pre_241.bak";
let applied = 0, already = 0, warnings = 0;
if (!fs.existsSync("OmniFlow-Control-Plane") || !fs.statSync("OmniFlow-Control-Plane").isDirectory()) {
  console.log("X Run this from the website repo root (bot root) - the folder that contains OmniFlow-Control-Plane/. Nothing was written.");
  process.exit(1);
}
if (!fs.existsSync("OmniFlow-Control-Plane/app.py")) {
  console.log("X OmniFlow-Control-Plane/ is empty or not the Control Plane repo (no app.py). On a fresh machine the website clone leaves this folder empty: delete it, then clone the Control Plane repo into it (git clone <CP repo url> OmniFlow-Control-Plane) and run this again. Nothing was written.");
  process.exit(1);
}
function compilePython(pathArg) {
  const { spawnSync } = require("child_process");
  for (const py of ["python3", "python", "py"]) {
    const probe = spawnSync(py, ["--version"], { encoding: "utf8" });
    if (probe.status !== 0) continue;
    const check = spawnSync(py, ["-c", "import sys;sys.exit(0 if sys.version_info[0]>=3 else 1)"], { encoding: "utf8" });
    if (check.status !== 0) continue;
    const result = spawnSync(py, ["-c", "import py_compile,sys;py_compile.compile(sys.argv[1],doraise=True);sys.exit(0)", pathArg], { encoding: "utf8" });
    return result.status === 0;
  }
  console.log("  (python not found - skipped compile guard)");
  return true;
}
function writeNewRepair(repoPath, marker, isCp, content) {
  try {
  let existed = false;
  if (fs.existsSync(repoPath)) {
    if (fs.statSync(repoPath).isDirectory()) {
      let target = repoPath + ".dir_conflict.bak";
      let n = 1;
      while (fs.existsSync(target)) { target = repoPath + ".dir_conflict.bak." + n; n++; }
      fs.renameSync(repoPath, target);
      console.log("! " + repoPath + " was a DIRECTORY on this machine - renamed to " + target + "; writing the real file.");
      warnings++;
    } else existed = true;
  }
  if (!existed) {
    const cut = Math.max(repoPath.lastIndexOf("/"), repoPath.lastIndexOf("\\"));
    if (cut > 0) fs.mkdirSync(repoPath.slice(0, cut), { recursive: true });
    fs.writeFileSync(repoPath, content, "utf8");
    if (isCp && repoPath.endsWith(".py") && !compilePython(repoPath)) {
      fs.unlinkSync(repoPath);
      console.log("X " + repoPath + " FAILED to compile - not written");
      warnings++;
      return;
    }
    console.log("+ " + repoPath + " (new file)");
    applied++;
    return;
  }
  const original = fs.readFileSync(repoPath, "utf8").replace(/\r\n/g, "\n");
  if (original.includes(marker)) {
    console.log("= " + repoPath + " (already correct)");
    already++;
    return;
  }
  const backup = repoPath + BACKUP_TAG;
  if (!fs.existsSync(backup)) fs.copyFileSync(repoPath, backup);
  fs.writeFileSync(repoPath, content, "utf8");
  if (isCp && repoPath.endsWith(".py") && !compilePython(repoPath)) {
    fs.copyFileSync(backup, repoPath);
    console.log("X " + repoPath + " FAILED to compile - old copy restored");
    warnings++;
    return;
  }
  console.log("+ " + repoPath + " (REPAIRED - old copy kept as " + BACKUP_TAG + ")");
  applied++;
  } catch (err) {
    console.log("X " + repoPath + " FAILED: " + err.message);
    warnings++;
  }
}
function removeFile(repoPath) {
  try {
    if (!fs.existsSync(repoPath)) {
      console.log("= " + repoPath + " (already removed)");
      already++;
      return;
    }
    const backup = repoPath + BACKUP_TAG;
    if (!fs.existsSync(backup)) fs.copyFileSync(repoPath, backup);
    fs.unlinkSync(repoPath);
    console.log("- " + repoPath + " (removed - old copy kept as " + BACKUP_TAG + ")");
    applied++;
  } catch (err) {
    console.log("X " + repoPath + " FAILED to remove: " + err.message);
    warnings++;
  }
}
if (!fs.existsSync("OmniFlow-Control-Plane/portal_ai_automation.py") || !fs.readFileSync("OmniFlow-Control-Plane/portal_ai_automation.py", "utf8").includes("\"\"\"AI + automation analytics quadrant (\u00a7240, gap analysis row 64).")) {
  console.log("X " + "Batch 240 (analytics_quadrant_240.mjs) is not applied in OmniFlow-Control-Plane - run it first." + " Nothing was written.");
  process.exit(1);
}
if (!fs.existsSync("app/dashboard/(portal)/analytics/AiAutomationCard.tsx") || !fs.readFileSync("app/dashboard/(portal)/analytics/AiAutomationCard.tsx", "utf8").includes("/** AI + automation quadrant; follows the Analytics window (days). */")) {
  console.log("X " + "Batch 240 (analytics_quadrant_240.mjs) is not applied in the website - run it first." + " Nothing was written.");
  process.exit(1);
}
writeNewRepair("omniflow-backend-patch/portal_ai_traces.py", "\"\"\"AI execution traces + audit linkage (\u00a7241, gap analysis rows 27 and 31).", false,
    "\"\"\"AI execution traces + audit linkage (\u00a7241, gap analysis rows 27 and 31).\n\nEvery AI answer already leaves a ``portal_brain_traces`` row (what the\nbrain read, its confidence, why it handed off). This module READS those\nrows and lays each one out as the steps the answer went through:\n\n    customer message -> guard -> agent -> tools -> model -> decision -> reply\n\nNo new table. The links come from the transaction the answer ran in: the\ntrace, the queued reply (``portal_connector_commands``), the audit rows\n(``portal_action_log``) and the inbound message are all written by the same\ntransaction, so they share one ``NOW()``. The message and reply TEXT are\nread from their own tables at request time (never copied into the trace),\nso retention and deletes keep covering them.\n\n  - ``GET /api/v1/portal/ai/traces?days=&kind=&decision=&agent_id=\n    &conversation_id=&limit=`` newest first, one summary per answer.\n  - ``GET /api/v1/portal/ai/traces/<id>`` the steps + linked audit rows.\n  - ``link_audit()`` gives ``GET /ai/audit`` rows a ``trace`` link\n    (trace id, agent, model).\n\nHuman principals of the workspace only (a trace shows customer text); API\nkeys get 403. Tenant-scoped; read-only (the request rolls back). Cost is\nshown only when model prices are configured (never invented). Optional\nreads (agents, messages, replies, audit) are probed with ``to_regclass``\nand run in a savepoint: a missing table blanks only that part.\n\"\"\"\n\nimport json\nimport logging\nfrom typing import Any, Callable, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_ai_automation as quadrant\nimport portal_db\nimport portal_txn\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\n\nbp = Blueprint(\"portal_ai_traces\", __name__, url_prefix=\"/api/v1/portal\")\n\nlogger = logging.getLogger(__name__)\n\nTRACES_TABLE = \"portal_brain_traces\"\nAGENTS_TABLE = \"portal_agents\"\nVERSIONS_TABLE = \"portal_agent_versions\"\nLOG_TABLE = \"portal_action_log\"\n\nKINDS = {\n    \"ingest_answer\": \"Automatic reply\",\n    \"voice_answer\": \"Phone call reply\",\n    \"draft\": \"Draft for the team\",\n}\nDECISIONS = (\"send\", \"handoff\")\nDEFAULT_DAYS = 7\nMAX_DAYS = 90\nDEFAULT_LIMIT = 50\nMAX_LIMIT = 100\nMAX_BODY_CHARS = 1000\nMAX_REFS = 10\nMAX_CITATIONS = 3\nINBOUND_SQL = \"direction IN ('in', 'inbound')\"\n\n\n# ---------------------------------------------------------------------------\n# parsing\n# ---------------------------------------------------------------------------\n\ndef _whole(raw: Any, max_len: int) -> Optional[int]:\n    \"\"\"ASCII digits only (no signs, no non-ASCII digits) -> int, else None.\"\"\"\n    text = str(raw if raw is not None else \"\").strip()\n    if not text or len(text) > max_len or not (text.isascii() and text.isdigit()):\n        return None\n    return int(text)\n\n\ndef parse_filters(args: Any) -> Tuple[Optional[Dict[str, Any]], str]:\n    \"\"\"Query string -> (filters, \"\") or (None, message).\"\"\"\n    def arg(name: str) -> str:\n        return str(args.get(name) or \"\").strip()\n\n    filters: Dict[str, Any] = {\"days\": DEFAULT_DAYS, \"kind\": \"\", \"decision\": \"\",\n                               \"agent_id\": 0, \"conversation_id\": 0,\n                               \"limit\": DEFAULT_LIMIT}\n    if arg(\"days\"):\n        days = _whole(arg(\"days\"), 3)\n        if days is None or not 1 <= days <= MAX_DAYS:\n            return None, \"days must be a whole number from 1 to \" + str(MAX_DAYS) + \".\"\n        filters[\"days\"] = days\n    if arg(\"kind\"):\n        if arg(\"kind\") not in KINDS:\n            return None, \"kind must be one of \" + \", \".join(KINDS) + \".\"\n        filters[\"kind\"] = arg(\"kind\")\n    if arg(\"decision\"):\n        if arg(\"decision\") not in DECISIONS:\n            return None, \"decision must be send or handoff.\"\n        filters[\"decision\"] = arg(\"decision\")\n    for name in (\"agent_id\", \"conversation_id\"):\n        if arg(name):\n            value = _whole(arg(name), 18)\n            if not value:\n                return None, name + \" must be a positive whole number.\"\n            filters[name] = value\n    if arg(\"limit\"):\n        limit = _whole(arg(\"limit\"), 3)\n        if not limit:\n            return None, \"limit must be a whole number from 1 to \" + str(MAX_LIMIT) + \".\"\n        filters[\"limit\"] = min(limit, MAX_LIMIT)\n    return filters, \"\"\n\n\n# ---------------------------------------------------------------------------\n# small helpers\n# ---------------------------------------------------------------------------\n\ndef _grounding(raw: Any) -> Dict[str, Any]:\n    if isinstance(raw, str):\n        try:\n            raw = json.loads(raw)\n        except ValueError:\n            return {}\n    return raw if isinstance(raw, dict) else {}\n\n\ndef _id(value: Any) -> Optional[int]:\n    if isinstance(value, bool):\n        return None\n    if isinstance(value, int):\n        return value if value > 0 else None\n    return _whole(value, 18) or None\n\n\ndef _ids(value: Any) -> List[Any]:\n    return list(value)[:MAX_REFS] if isinstance(value, list) else []\n\n\ndef _count(n: int, noun: str, plural: str = \"\") -> str:\n    return str(n) + \" \" + (noun if n == 1 else plural or noun + \"s\")\n\n\ndef _calls(g: Dict[str, Any]) -> List[Dict[str, Any]]:\n    raw = g.get(\"model_calls\")\n    return [c for c in raw if isinstance(c, dict)] if isinstance(raw, list) else []\n\n\ndef _cost(calls: List[Dict[str, Any]], prices: Dict[str, Any]) -> Optional[float]:\n    \"\"\"USD for the calls, or None when any of them has no price.\"\"\"\n    import portal_ai_usage\n\n    if not calls or not prices:\n        return None\n    total = 0.0\n    for call in calls:\n        cost = portal_ai_usage.estimate_cost(\n            call.get(\"model\"), quadrant._int(call.get(\"prompt_tokens\")),\n            quadrant._int(call.get(\"completion_tokens\")), prices)\n        if cost is None:\n            return None\n        total += cost\n    return round(total, 6)\n\n\ndef _prices() -> Dict[str, Any]:\n    try:\n        import portal_ai_usage\n\n        return portal_ai_usage.prices()\n    except Exception:\n        return {}\n\n\ndef _optional(cur, tables: Tuple[str, ...], fn: Callable[[], Any], default: Any) -> Any:\n    \"\"\"One optional read: probe its tables, run it in a savepoint.\"\"\"\n    try:\n        for table in tables:\n            if not quadrant._exists(cur, table):\n                return default\n        with portal_txn.savepoint(cur, None, \"of_trace_read\"):\n            return fn()\n    except Exception as error:\n        logger.info(\"ai trace read %s skipped: %s\", tables[0], error)\n        return default\n\n\ndef _agent_names(cur, client_id: int, ids: List[int]) -> Dict[int, str]:\n    ids = sorted({i for i in ids if i})\n    if not ids:\n        return {}\n\n    def read() -> Dict[int, str]:\n        cur.execute(\n            \"SELECT id, name FROM \" + portal_db._q(AGENTS_TABLE) +\n            \" WHERE client_id = %s AND id = ANY(%s)\",\n            (client_id, ids),\n        )\n        return {quadrant._int(r.get(\"id\")): str(r.get(\"name\") or \"\")\n                for r in portal_db.rows(cur)}\n\n    return _optional(cur, (AGENTS_TABLE,), read, {})\n\n\ndef _reason(g: Dict[str, Any], decision: str) -> Optional[Dict[str, str]]:\n    raw = str(g.get(\"reason\") or \"\")\n    if not raw and decision == \"send\":\n        return None\n    key = quadrant._reason_key(raw)\n    return {\"key\": key, \"label\": quadrant.BRAIN_REASONS.get(key) or raw,\n            \"detail\": raw.split(\":\", 1)[1] if \":\" in raw else \"\"}\n\n\ndef _confidence(g: Dict[str, Any]) -> Optional[float]:\n    value = g.get(\"confidence\")\n    if isinstance(value, bool) or not isinstance(value, (int, float)):\n        return None\n    return round(float(value), 3)\n\n\ndef _agent(g: Dict[str, Any], names: Dict[int, str]) -> Optional[Dict[str, Any]]:\n    agent_id = _id(g.get(\"agent_id\"))\n    if not agent_id:\n        return None\n    name = names.get(agent_id) or str(g.get(\"agent_name\") or \"\")\n    return {\"id\": agent_id, \"name\": name or \"Agent #\" + str(agent_id)}\n\n\n# ---------------------------------------------------------------------------\n# list\n# ---------------------------------------------------------------------------\n\ndef _summary(row: Dict[str, Any], names: Dict[int, str],\n             prices: Dict[str, Any]) -> Dict[str, Any]:\n    g = _grounding(row.get(\"grounding\"))\n    decision = str(row.get(\"decision\") or \"\")\n    kind = str(row.get(\"kind\") or \"\")\n    calls = _calls(g)\n    return {\n        \"id\": quadrant._int(row.get(\"id\")),\n        \"created_at\": quadrant._iso(row.get(\"created_at\")),\n        \"kind\": kind,\n        \"kind_label\": KINDS.get(kind, kind),\n        \"decision\": decision,\n        \"conversation_id\": _id(row.get(\"conversation_id\")),\n        \"agent\": _agent(g, names),\n        \"model\": str(calls[0].get(\"model\") or \"\") or None if calls else None,\n        \"tokens\": sum(quadrant._int(c.get(\"prompt_tokens\")) +\n                      quadrant._int(c.get(\"completion_tokens\")) for c in calls),\n        \"latency_ms\": (sum(quadrant._int(c.get(\"latency_ms\")) for c in calls)\n                       if calls else None),\n        \"cost_usd\": _cost(calls, prices),\n        \"confidence\": _confidence(g),\n        \"reason\": _reason(g, decision),\n        \"tools\": [quadrant.TOOL_LABELS.get(str(t), str(t))\n                  for t in (g.get(\"tools\") or []) if isinstance(t, str)],\n        \"llm_called\": g.get(\"llm_called\") is True,\n    }\n\n\ndef list_traces(cur, client_id: int, filters: Dict[str, Any]) -> Dict[str, Any]:\n    prices = _prices()\n    out: Dict[str, Any] = {\n        \"days\": filters[\"days\"],\n        \"filters\": {k: filters[k] for k in (\"kind\", \"decision\", \"agent_id\",\n                                            \"conversation_id\")},\n        \"kinds\": [{\"key\": k, \"label\": v} for k, v in KINDS.items()],\n        \"prices_configured\": bool(prices),\n        \"items\": [],\n    }\n    if not quadrant._exists(cur, TRACES_TABLE):\n        return out\n    sql = (\"SELECT id, conversation_id, kind, decision, grounding, created_at\"\n           \" FROM \" + portal_db._q(TRACES_TABLE) +\n           \" WHERE client_id = %s\"\n           \" AND created_at > NOW() - make_interval(days => %s)\")\n    params: List[Any] = [client_id, filters[\"days\"]]\n    for column in (\"kind\", \"decision\", \"conversation_id\"):\n        if filters[column]:\n            sql += \" AND \" + column + \" = %s\"\n            params.append(filters[column])\n    if filters[\"agent_id\"]:\n        sql += \" AND \" + quadrant.AGENT_SQL + \" = %s\"\n        params.append(filters[\"agent_id\"])\n    sql += \" ORDER BY id DESC LIMIT %s\"\n    params.append(filters[\"limit\"])\n    cur.execute(sql, tuple(params))\n    rows = portal_db.rows(cur)\n    names = _agent_names(cur, client_id, [\n        _id(_grounding(r.get(\"grounding\")).get(\"agent_id\")) or 0 for r in rows])\n    out[\"items\"] = [_summary(r, names, prices) for r in rows]\n    return out\n\n\n# ---------------------------------------------------------------------------\n# detail: the steps of one answer\n# ---------------------------------------------------------------------------\n\ndef _tool_items(g: Dict[str, Any], agent: Optional[Dict[str, Any]]) -> List[Dict[str, Any]]:\n    items: List[Dict[str, Any]] = []\n    read = g.get(\"conversation_messages\")\n    if isinstance(read, int) and not isinstance(read, bool):\n        items.append({\"key\": \"conversation\", \"label\": \"Recent conversation\",\n                      \"detail\": _count(read, \"message\") + \" read\", \"refs\": []})\n    for key in g.get(\"tools\") or []:\n        if not isinstance(key, str):\n            continue\n        detail, refs = \"\", []\n        if key == \"customer_orders\":\n            refs = _ids(g.get(\"order_ids\"))\n            detail = _count(len(g.get(\"order_ids\") or []), \"order\")\n        elif key == \"search_kb\":\n            entries = len(g.get(\"kb_ids\") or [])\n            passages = len(g.get(\"knowledge_ids\") or [])\n            detail = _count(entries, \"entry\", \"entries\") + \", \" + \\\n                _count(passages, \"document passage\")\n            refs = [str(c.get(\"section\") or c.get(\"source\") or \"\")\n                    for c in (g.get(\"citations\") or [])[:MAX_CITATIONS]\n                    if isinstance(c, dict)]\n        elif key == \"business_facts\":\n            refs = _ids(g.get(\"fact_ids\"))\n            detail = _count(len(g.get(\"fact_ids\") or []), \"fact\")\n        elif key == \"customer_memory\":\n            refs = _ids(g.get(\"memory_ids\"))\n            detail = _count(len(g.get(\"memory_ids\") or []), \"memory\", \"memories\")\n        elif key == \"agent_persona\":\n            detail = agent[\"name\"] if agent else \"\"\n        elif key == \"customer_profile\":\n            detail = \"Preferred language known\"\n        elif key == \"sales_context\":\n            sales = g.get(\"sales\") if isinstance(g.get(\"sales\"), dict) else {}\n            parts = [\"stage \" + str(sales.get(\"stage\") or \"unknown\")]\n            if sales.get(\"ask_next\"):\n                parts.append(\"asks next: \" + str(sales.get(\"ask_next\")))\n            if sales.get(\"objection\"):\n                parts.append(\"concern: \" + str(sales.get(\"objection\")) +\n                             (\" (approved answer)\" if sales.get(\"approved_answer\") else \"\"))\n            detail = \", \".join(parts)\n        elif key == \"loyalty_context\":\n            loyalty = g.get(\"loyalty\") if isinstance(g.get(\"loyalty\"), dict) else {}\n            detail = \"tier \" + str(loyalty.get(\"tier\") or \"none\") + \", \" + \\\n                _count(quadrant._int(loyalty.get(\"orders\")), \"past order\")\n        items.append({\"key\": key, \"label\": quadrant.TOOL_LABELS.get(key, key),\n                      \"detail\": detail, \"refs\": refs})\n    return items\n\n\ndef _input_message(cur, client_id: int, conversation_id: Optional[int], at: Any,\n                   input_chars: Any) -> Optional[Dict[str, Any]]:\n    \"\"\"The customer message the answer was about: the newest inbound message\n    up to the trace time. ``exact`` = written in the same transaction (and,\n    when the trace knows it, the same length).\"\"\"\n    if not conversation_id or at is None:\n        return None\n\n    def read() -> Optional[Dict[str, Any]]:\n        cur.execute(\n            \"SELECT id, body, created_at FROM \" + portal_db._q(portal_db.MSGS_TABLE) +\n            \" WHERE client_id = %s AND conversation_id = %s AND \" + INBOUND_SQL +\n            \" AND created_at <= %s ORDER BY created_at DESC, id DESC LIMIT 5\",\n            (client_id, conversation_id, at),\n        )\n        rows = portal_db.rows(cur)\n        if not rows:\n            return None\n        same = [r for r in rows if r.get(\"created_at\") == at]\n        sized = [r for r in same if isinstance(input_chars, int)\n                 and len(str(r.get(\"body\") or \"\").strip()) == input_chars]\n        pick = (sized or same or rows)[0]\n        return {\"message_id\": quadrant._int(pick.get(\"id\")),\n                \"body\": str(pick.get(\"body\") or \"\")[:MAX_BODY_CHARS],\n                \"created_at\": quadrant._iso(pick.get(\"created_at\")),\n                \"match\": \"exact\" if (sized or (same and not isinstance(input_chars, int)))\n                else (\"same_time\" if same else \"nearest\")}\n\n    return _optional(cur, (portal_db.MSGS_TABLE,), read, None)\n\n\ndef _queued_reply(cur, client_id: int, conversation_id: Optional[int],\n                  at: Any) -> Optional[Dict[str, Any]]:\n    if not conversation_id or at is None:\n        return None\n\n    def read() -> Optional[Dict[str, Any]]:\n        cur.execute(\n            \"SELECT id, status, payload->>'body' AS body, created_at FROM \" +\n            portal_db._q(portal_db.CMD_TABLE) +\n            \" WHERE client_id = %s AND action = 'send_message'\"\n            \" AND created_at = %s AND payload->>'source' = 'ai_brain'\"\n            \" AND payload->>'conversation_id' = %s ORDER BY id LIMIT 1\",\n            (client_id, at, str(conversation_id)),\n        )\n        rows = portal_db.rows(cur)\n        if not rows:\n            return None\n        row = rows[0]\n        return {\"command_id\": quadrant._int(row.get(\"id\")),\n                \"status\": str(row.get(\"status\") or \"\"),\n                \"body\": str(row.get(\"body\") or \"\")[:MAX_BODY_CHARS]}\n\n    return _optional(cur, (portal_db.CMD_TABLE,), read, None)\n\n\ndef _audit_rows(cur, client_id: int, conversation_id: Optional[int],\n                at: Any) -> List[Dict[str, Any]]:\n    if not conversation_id or at is None:\n        return []\n\n    def read() -> List[Dict[str, Any]]:\n        cur.execute(\n            \"SELECT id, action, actor_kind, note FROM \" + portal_db._q(LOG_TABLE) +\n            \" WHERE client_id = %s AND conversation_id = %s AND created_at = %s\"\n            \" ORDER BY id\",\n            (client_id, conversation_id, at),\n        )\n        return [{\"id\": quadrant._int(r.get(\"id\")), \"action\": str(r.get(\"action\") or \"\"),\n                 \"actor_kind\": str(r.get(\"actor_kind\") or \"\"),\n                 \"note\": str(r.get(\"note\") or \"\")} for r in portal_db.rows(cur)]\n\n    return _optional(cur, (LOG_TABLE,), read, [])\n\n\ndef _agent_version(cur, client_id: int, agent_id: int, at: Any) -> Optional[int]:\n    \"\"\"The persona version that was live when the answer ran.\"\"\"\n    if at is None:\n        return None\n\n    def read() -> Optional[int]:\n        cur.execute(\n            \"SELECT MAX(version) AS version FROM \" + portal_db._q(VERSIONS_TABLE) +\n            \" WHERE client_id = %s AND agent_id = %s AND created_at <= %s\",\n            (client_id, agent_id, at),\n        )\n        rows = portal_db.rows(cur)\n        version = (rows[0] if rows else {}).get(\"version\")\n        return quadrant._int(version) or None\n\n    return _optional(cur, (VERSIONS_TABLE,), read, None)\n\n\ndef _response(kind: str, decision: str, queued: Optional[Dict[str, Any]],\n              audit: List[Dict[str, Any]]) -> Dict[str, Any]:\n    if decision != \"send\":\n        escalated = any(a[\"action\"].startswith(\"escalation.\") for a in audit)\n        return {\"key\": \"response\", \"label\": \"Reply\", \"status\": \"skipped\",\n                \"detail\": {\"type\": \"handoff\", \"escalated\": escalated,\n                           \"note\": \"No reply sent: handed to the team.\"}}\n    if kind == \"draft\":\n        return {\"key\": \"response\", \"label\": \"Reply\", \"status\": \"ok\",\n                \"detail\": {\"type\": \"draft\",\n                           \"note\": \"Shown to the team member as a draft (drafts are not stored).\"}}\n    if kind == \"voice_answer\":\n        return {\"key\": \"response\", \"label\": \"Reply\", \"status\": \"ok\",\n                \"detail\": {\"type\": \"voice\", \"note\": \"Spoken on the phone call.\"}}\n    if queued:\n        return {\"key\": \"response\", \"label\": \"Reply\", \"status\": \"ok\",\n                \"detail\": dict(queued, type=\"message\")}\n    return {\"key\": \"response\", \"label\": \"Reply\", \"status\": \"unknown\",\n            \"detail\": {\"type\": \"message\",\n                       \"note\": \"The queued reply is no longer on record.\"}}\n\n\ndef build_detail(cur, client_id: int, row: Dict[str, Any]) -> Dict[str, Any]:\n    g = _grounding(row.get(\"grounding\"))\n    at = row.get(\"created_at\")\n    kind = str(row.get(\"kind\") or \"\")\n    decision = str(row.get(\"decision\") or \"\")\n    conversation_id = _id(row.get(\"conversation_id\"))\n    prices = _prices()\n    agent_id = _id(g.get(\"agent_id\"))\n    names = _agent_names(cur, client_id, [agent_id or 0])\n    agent = _agent(g, names)\n    reason = _reason(g, decision)\n    blocked = reason is not None and reason[\"key\"] == \"injection_suspected\"\n    calls = _calls(g)\n\n    message = _input_message(cur, client_id, conversation_id, at, g.get(\"input_chars\"))\n    audit = _audit_rows(cur, client_id, conversation_id, at)\n    queued = (_queued_reply(cur, client_id, conversation_id, at)\n              if kind == \"ingest_answer\" and decision == \"send\" else None)\n\n    guard = g.get(\"guard\") if isinstance(g.get(\"guard\"), dict) else None\n    steps: List[Dict[str, Any]] = [\n        {\"key\": \"input\", \"label\": \"Customer message\",\n         \"status\": \"ok\" if message else \"unknown\",\n         \"detail\": message or {\"input_chars\": g.get(\"input_chars\"),\n                               \"note\": \"The message is not on record (deleted, or not a chat message).\"}},\n        {\"key\": \"guard\", \"label\": \"Safety check\",\n         \"status\": \"blocked\" if blocked else (\"ok\" if guard else \"skipped\"),\n         \"detail\": guard or {}},\n    ]\n    if agent:\n        agent_detail = dict(agent, version=_agent_version(cur, client_id, agent[\"id\"], at),\n                            in_hours=g.get(\"agent_in_hours\"),\n                            auto_reply=g.get(\"agent_auto_reply\"))\n        steps.append({\"key\": \"agent\", \"label\": \"Agent\", \"status\": \"ok\",\n                      \"detail\": agent_detail})\n    else:\n        steps.append({\"key\": \"agent\", \"label\": \"Agent\",\n                      \"status\": \"skipped\" if blocked else \"ok\",\n                      \"detail\": {\"name\": \"Default assistant\"}})\n    steps.append({\"key\": \"tools\", \"label\": \"Context it read\",\n                  \"status\": \"skipped\" if blocked else \"ok\",\n                  \"detail\": {\"items\": _tool_items(g, agent)}})\n    steps.append({\n        \"key\": \"model\", \"label\": \"AI model\",\n        \"status\": (\"skipped\" if blocked or not (calls or \"llm_called\" in g)\n                   else \"ok\" if g.get(\"llm_called\") is True else \"failed\"),\n        \"detail\": {\"calls\": [dict(c, cost_usd=_cost([c], prices)) for c in calls],\n                   \"timings_ms\": g.get(\"timings_ms\") if isinstance(g.get(\"timings_ms\"), dict) else None,\n                   \"cost_usd\": _cost(calls, prices),\n                   \"prices_configured\": bool(prices)}})\n    steps.append({\"key\": \"decision\", \"label\": \"Decision\",\n                  \"status\": \"ok\" if decision == \"send\" else (\"blocked\" if blocked else \"warn\"),\n                  \"detail\": {\"decision\": decision, \"confidence\": _confidence(g),\n                             \"reason\": reason,\n                             \"policy_violations\": g.get(\"policy_violations\") or [],\n                             \"output_violations\": g.get(\"output_violations\") or []}})\n    steps.append(_response(kind, decision, queued, audit))\n    return {\n        \"id\": quadrant._int(row.get(\"id\")),\n        \"created_at\": quadrant._iso(at),\n        \"kind\": kind,\n        \"kind_label\": KINDS.get(kind, kind),\n        \"decision\": decision,\n        \"conversation_id\": conversation_id,\n        \"channel\": str(g.get(\"channel\") or \"\") or None,\n        \"steps\": steps,\n        \"audit\": audit,\n    }\n\n\ndef get_trace(cur, client_id: int, trace_id: int) -> Optional[Dict[str, Any]]:\n    if not quadrant._exists(cur, TRACES_TABLE):\n        return None\n    cur.execute(\n        \"SELECT id, conversation_id, kind, decision, grounding, created_at FROM \" +\n        portal_db._q(TRACES_TABLE) + \" WHERE client_id = %s AND id = %s\",\n        (client_id, trace_id),\n    )\n    rows = portal_db.rows(cur)\n    return build_detail(cur, client_id, rows[0]) if rows else None\n\n\n# ---------------------------------------------------------------------------\n# audit linkage (GET /ai/audit)\n# ---------------------------------------------------------------------------\n\ndef link_audit(cur, client_id: int, items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:\n    \"\"\"Give audit rows written with an AI answer a ``trace`` link (trace id,\n    agent, model): same workspace, conversation and transaction time. When\n    one transaction answered several messages, the n-th ``ai.answer`` row\n    pairs with the n-th sent automatic reply; other rows take the first.\"\"\"\n    wanted = [i for i in items if i.get(\"conversation_id\") and i.get(\"created_at\")]\n    if not wanted or not quadrant._exists(cur, TRACES_TABLE):\n        return items\n    cur.execute(\n        \"SELECT id, conversation_id, kind, decision, created_at, grounding FROM \" +\n        portal_db._q(TRACES_TABLE) +\n        \" WHERE client_id = %s AND conversation_id = ANY(%s)\"\n        \" AND created_at = ANY(CAST(%s AS timestamptz[])) ORDER BY id\",\n        (client_id, sorted({int(i[\"conversation_id\"]) for i in wanted}),\n         sorted({str(i[\"created_at\"]) for i in wanted})),\n    )\n    links: Dict[Tuple[int, str], List[Dict[str, Any]]] = {}\n    for row in portal_db.rows(cur):\n        key = (quadrant._int(row.get(\"conversation_id\")),\n               str(quadrant._iso(row.get(\"created_at\"))))\n        links.setdefault(key, []).append(row)\n    if not links:\n        return items\n    names = _agent_names(cur, client_id, [\n        _id(_grounding(r.get(\"grounding\")).get(\"agent_id\")) or 0\n        for rows in links.values() for r in rows])\n    answers: Dict[Tuple[int, str], List[int]] = {}\n    for item in sorted(wanted, key=lambda i: quadrant._int(i.get(\"id\"))):\n        if item.get(\"action\") == \"ai.answer\":\n            answers.setdefault((quadrant._int(item.get(\"conversation_id\")),\n                                str(item.get(\"created_at\"))), []).append(\n                quadrant._int(item.get(\"id\")))\n    out = []\n    for item in items:\n        key = (quadrant._int(item.get(\"conversation_id\")), str(item.get(\"created_at\")))\n        rows = links.get(key)\n        if not rows:\n            out.append(item)\n            continue\n        row = rows[0]\n        if item.get(\"action\") == \"ai.answer\":\n            sent = [r for r in rows if r.get(\"kind\") == \"ingest_answer\"\n                    and r.get(\"decision\") == \"send\"]\n            rank = answers.get(key, []).index(quadrant._int(item.get(\"id\")))\n            row = sent[rank] if rank < len(sent) else row\n        g = _grounding(row.get(\"grounding\"))\n        calls = _calls(g)\n        out.append(dict(item, trace={\n            \"id\": quadrant._int(row.get(\"id\")),\n            \"agent\": _agent(g, names),\n            \"model\": str(calls[0].get(\"model\") or \"\") or None if calls else None,\n        }))\n    return out\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef _human_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}), 401)\n    forbidden = ensure_human_principal(principal)\n    if forbidden:\n        return None, forbidden\n    return principal, None\n\n\ndef _read(fn: Callable[[Any], Any]) -> Any:\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            return fn(cur)\n    finally:\n        try:\n            conn.rollback()\n        finally:\n            conn.close()\n\n\nDOWN = {\"error\": {\"code\": \"portal_unavailable\",\n                  \"message\": \"AI traces are unavailable right now.\"}}\n\n\n@bp.get(\"/ai/traces\")\ndef ai_traces():\n    principal, error = _human_or_error()\n    if error:\n        return error\n    filters, message = parse_filters(request.args)\n    if filters is None:\n        return jsonify({\"error\": {\"code\": \"bad_request\", \"message\": message}}), 400\n    client_id = int(principal[\"client_id\"])\n    try:\n        data = _read(lambda cur: list_traces(cur, client_id, filters))\n    except Exception as error:\n        logger.warning(\"ai traces list failed: %s\", error)\n        return jsonify(DOWN), 503\n    return jsonify(data), 200\n\n\n@bp.get(\"/ai/traces/<trace_id>\")\ndef ai_trace(trace_id: str):\n    principal, error = _human_or_error()\n    if error:\n        return error\n    wanted = _whole(trace_id, 18)\n    if not wanted:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"Trace id must be a positive whole number.\"}}), 400\n    client_id = int(principal[\"client_id\"])\n    try:\n        data = _read(lambda cur: get_trace(cur, client_id, wanted))\n    except Exception as error:\n        logger.warning(\"ai trace detail failed: %s\", error)\n        return jsonify(DOWN), 503\n    if data is None:\n        return jsonify({\"error\": {\"code\": \"not_found\", \"message\": \"Trace not found.\"}}), 404\n    return jsonify(data), 200\n");
writeNewRepair("OmniFlow-Control-Plane/portal_ai_traces.py", "\"\"\"AI execution traces + audit linkage (\u00a7241, gap analysis rows 27 and 31).", true,
    "\"\"\"AI execution traces + audit linkage (\u00a7241, gap analysis rows 27 and 31).\n\nEvery AI answer already leaves a ``portal_brain_traces`` row (what the\nbrain read, its confidence, why it handed off). This module READS those\nrows and lays each one out as the steps the answer went through:\n\n    customer message -> guard -> agent -> tools -> model -> decision -> reply\n\nNo new table. The links come from the transaction the answer ran in: the\ntrace, the queued reply (``portal_connector_commands``), the audit rows\n(``portal_action_log``) and the inbound message are all written by the same\ntransaction, so they share one ``NOW()``. The message and reply TEXT are\nread from their own tables at request time (never copied into the trace),\nso retention and deletes keep covering them.\n\n  - ``GET /api/v1/portal/ai/traces?days=&kind=&decision=&agent_id=\n    &conversation_id=&limit=`` newest first, one summary per answer.\n  - ``GET /api/v1/portal/ai/traces/<id>`` the steps + linked audit rows.\n  - ``link_audit()`` gives ``GET /ai/audit`` rows a ``trace`` link\n    (trace id, agent, model).\n\nHuman principals of the workspace only (a trace shows customer text); API\nkeys get 403. Tenant-scoped; read-only (the request rolls back). Cost is\nshown only when model prices are configured (never invented). Optional\nreads (agents, messages, replies, audit) are probed with ``to_regclass``\nand run in a savepoint: a missing table blanks only that part.\n\"\"\"\n\nimport json\nimport logging\nfrom typing import Any, Callable, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_ai_automation as quadrant\nimport portal_db\nimport portal_txn\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\n\nbp = Blueprint(\"portal_ai_traces\", __name__, url_prefix=\"/api/v1/portal\")\n\nlogger = logging.getLogger(__name__)\n\nTRACES_TABLE = \"portal_brain_traces\"\nAGENTS_TABLE = \"portal_agents\"\nVERSIONS_TABLE = \"portal_agent_versions\"\nLOG_TABLE = \"portal_action_log\"\n\nKINDS = {\n    \"ingest_answer\": \"Automatic reply\",\n    \"voice_answer\": \"Phone call reply\",\n    \"draft\": \"Draft for the team\",\n}\nDECISIONS = (\"send\", \"handoff\")\nDEFAULT_DAYS = 7\nMAX_DAYS = 90\nDEFAULT_LIMIT = 50\nMAX_LIMIT = 100\nMAX_BODY_CHARS = 1000\nMAX_REFS = 10\nMAX_CITATIONS = 3\nINBOUND_SQL = \"direction IN ('in', 'inbound')\"\n\n\n# ---------------------------------------------------------------------------\n# parsing\n# ---------------------------------------------------------------------------\n\ndef _whole(raw: Any, max_len: int) -> Optional[int]:\n    \"\"\"ASCII digits only (no signs, no non-ASCII digits) -> int, else None.\"\"\"\n    text = str(raw if raw is not None else \"\").strip()\n    if not text or len(text) > max_len or not (text.isascii() and text.isdigit()):\n        return None\n    return int(text)\n\n\ndef parse_filters(args: Any) -> Tuple[Optional[Dict[str, Any]], str]:\n    \"\"\"Query string -> (filters, \"\") or (None, message).\"\"\"\n    def arg(name: str) -> str:\n        return str(args.get(name) or \"\").strip()\n\n    filters: Dict[str, Any] = {\"days\": DEFAULT_DAYS, \"kind\": \"\", \"decision\": \"\",\n                               \"agent_id\": 0, \"conversation_id\": 0,\n                               \"limit\": DEFAULT_LIMIT}\n    if arg(\"days\"):\n        days = _whole(arg(\"days\"), 3)\n        if days is None or not 1 <= days <= MAX_DAYS:\n            return None, \"days must be a whole number from 1 to \" + str(MAX_DAYS) + \".\"\n        filters[\"days\"] = days\n    if arg(\"kind\"):\n        if arg(\"kind\") not in KINDS:\n            return None, \"kind must be one of \" + \", \".join(KINDS) + \".\"\n        filters[\"kind\"] = arg(\"kind\")\n    if arg(\"decision\"):\n        if arg(\"decision\") not in DECISIONS:\n            return None, \"decision must be send or handoff.\"\n        filters[\"decision\"] = arg(\"decision\")\n    for name in (\"agent_id\", \"conversation_id\"):\n        if arg(name):\n            value = _whole(arg(name), 18)\n            if not value:\n                return None, name + \" must be a positive whole number.\"\n            filters[name] = value\n    if arg(\"limit\"):\n        limit = _whole(arg(\"limit\"), 3)\n        if not limit:\n            return None, \"limit must be a whole number from 1 to \" + str(MAX_LIMIT) + \".\"\n        filters[\"limit\"] = min(limit, MAX_LIMIT)\n    return filters, \"\"\n\n\n# ---------------------------------------------------------------------------\n# small helpers\n# ---------------------------------------------------------------------------\n\ndef _grounding(raw: Any) -> Dict[str, Any]:\n    if isinstance(raw, str):\n        try:\n            raw = json.loads(raw)\n        except ValueError:\n            return {}\n    return raw if isinstance(raw, dict) else {}\n\n\ndef _id(value: Any) -> Optional[int]:\n    if isinstance(value, bool):\n        return None\n    if isinstance(value, int):\n        return value if value > 0 else None\n    return _whole(value, 18) or None\n\n\ndef _ids(value: Any) -> List[Any]:\n    return list(value)[:MAX_REFS] if isinstance(value, list) else []\n\n\ndef _count(n: int, noun: str, plural: str = \"\") -> str:\n    return str(n) + \" \" + (noun if n == 1 else plural or noun + \"s\")\n\n\ndef _calls(g: Dict[str, Any]) -> List[Dict[str, Any]]:\n    raw = g.get(\"model_calls\")\n    return [c for c in raw if isinstance(c, dict)] if isinstance(raw, list) else []\n\n\ndef _cost(calls: List[Dict[str, Any]], prices: Dict[str, Any]) -> Optional[float]:\n    \"\"\"USD for the calls, or None when any of them has no price.\"\"\"\n    import portal_ai_usage\n\n    if not calls or not prices:\n        return None\n    total = 0.0\n    for call in calls:\n        cost = portal_ai_usage.estimate_cost(\n            call.get(\"model\"), quadrant._int(call.get(\"prompt_tokens\")),\n            quadrant._int(call.get(\"completion_tokens\")), prices)\n        if cost is None:\n            return None\n        total += cost\n    return round(total, 6)\n\n\ndef _prices() -> Dict[str, Any]:\n    try:\n        import portal_ai_usage\n\n        return portal_ai_usage.prices()\n    except Exception:\n        return {}\n\n\ndef _optional(cur, tables: Tuple[str, ...], fn: Callable[[], Any], default: Any) -> Any:\n    \"\"\"One optional read: probe its tables, run it in a savepoint.\"\"\"\n    try:\n        for table in tables:\n            if not quadrant._exists(cur, table):\n                return default\n        with portal_txn.savepoint(cur, None, \"of_trace_read\"):\n            return fn()\n    except Exception as error:\n        logger.info(\"ai trace read %s skipped: %s\", tables[0], error)\n        return default\n\n\ndef _agent_names(cur, client_id: int, ids: List[int]) -> Dict[int, str]:\n    ids = sorted({i for i in ids if i})\n    if not ids:\n        return {}\n\n    def read() -> Dict[int, str]:\n        cur.execute(\n            \"SELECT id, name FROM \" + portal_db._q(AGENTS_TABLE) +\n            \" WHERE client_id = %s AND id = ANY(%s)\",\n            (client_id, ids),\n        )\n        return {quadrant._int(r.get(\"id\")): str(r.get(\"name\") or \"\")\n                for r in portal_db.rows(cur)}\n\n    return _optional(cur, (AGENTS_TABLE,), read, {})\n\n\ndef _reason(g: Dict[str, Any], decision: str) -> Optional[Dict[str, str]]:\n    raw = str(g.get(\"reason\") or \"\")\n    if not raw and decision == \"send\":\n        return None\n    key = quadrant._reason_key(raw)\n    return {\"key\": key, \"label\": quadrant.BRAIN_REASONS.get(key) or raw,\n            \"detail\": raw.split(\":\", 1)[1] if \":\" in raw else \"\"}\n\n\ndef _confidence(g: Dict[str, Any]) -> Optional[float]:\n    value = g.get(\"confidence\")\n    if isinstance(value, bool) or not isinstance(value, (int, float)):\n        return None\n    return round(float(value), 3)\n\n\ndef _agent(g: Dict[str, Any], names: Dict[int, str]) -> Optional[Dict[str, Any]]:\n    agent_id = _id(g.get(\"agent_id\"))\n    if not agent_id:\n        return None\n    name = names.get(agent_id) or str(g.get(\"agent_name\") or \"\")\n    return {\"id\": agent_id, \"name\": name or \"Agent #\" + str(agent_id)}\n\n\n# ---------------------------------------------------------------------------\n# list\n# ---------------------------------------------------------------------------\n\ndef _summary(row: Dict[str, Any], names: Dict[int, str],\n             prices: Dict[str, Any]) -> Dict[str, Any]:\n    g = _grounding(row.get(\"grounding\"))\n    decision = str(row.get(\"decision\") or \"\")\n    kind = str(row.get(\"kind\") or \"\")\n    calls = _calls(g)\n    return {\n        \"id\": quadrant._int(row.get(\"id\")),\n        \"created_at\": quadrant._iso(row.get(\"created_at\")),\n        \"kind\": kind,\n        \"kind_label\": KINDS.get(kind, kind),\n        \"decision\": decision,\n        \"conversation_id\": _id(row.get(\"conversation_id\")),\n        \"agent\": _agent(g, names),\n        \"model\": str(calls[0].get(\"model\") or \"\") or None if calls else None,\n        \"tokens\": sum(quadrant._int(c.get(\"prompt_tokens\")) +\n                      quadrant._int(c.get(\"completion_tokens\")) for c in calls),\n        \"latency_ms\": (sum(quadrant._int(c.get(\"latency_ms\")) for c in calls)\n                       if calls else None),\n        \"cost_usd\": _cost(calls, prices),\n        \"confidence\": _confidence(g),\n        \"reason\": _reason(g, decision),\n        \"tools\": [quadrant.TOOL_LABELS.get(str(t), str(t))\n                  for t in (g.get(\"tools\") or []) if isinstance(t, str)],\n        \"llm_called\": g.get(\"llm_called\") is True,\n    }\n\n\ndef list_traces(cur, client_id: int, filters: Dict[str, Any]) -> Dict[str, Any]:\n    prices = _prices()\n    out: Dict[str, Any] = {\n        \"days\": filters[\"days\"],\n        \"filters\": {k: filters[k] for k in (\"kind\", \"decision\", \"agent_id\",\n                                            \"conversation_id\")},\n        \"kinds\": [{\"key\": k, \"label\": v} for k, v in KINDS.items()],\n        \"prices_configured\": bool(prices),\n        \"items\": [],\n    }\n    if not quadrant._exists(cur, TRACES_TABLE):\n        return out\n    sql = (\"SELECT id, conversation_id, kind, decision, grounding, created_at\"\n           \" FROM \" + portal_db._q(TRACES_TABLE) +\n           \" WHERE client_id = %s\"\n           \" AND created_at > NOW() - make_interval(days => %s)\")\n    params: List[Any] = [client_id, filters[\"days\"]]\n    for column in (\"kind\", \"decision\", \"conversation_id\"):\n        if filters[column]:\n            sql += \" AND \" + column + \" = %s\"\n            params.append(filters[column])\n    if filters[\"agent_id\"]:\n        sql += \" AND \" + quadrant.AGENT_SQL + \" = %s\"\n        params.append(filters[\"agent_id\"])\n    sql += \" ORDER BY id DESC LIMIT %s\"\n    params.append(filters[\"limit\"])\n    cur.execute(sql, tuple(params))\n    rows = portal_db.rows(cur)\n    names = _agent_names(cur, client_id, [\n        _id(_grounding(r.get(\"grounding\")).get(\"agent_id\")) or 0 for r in rows])\n    out[\"items\"] = [_summary(r, names, prices) for r in rows]\n    return out\n\n\n# ---------------------------------------------------------------------------\n# detail: the steps of one answer\n# ---------------------------------------------------------------------------\n\ndef _tool_items(g: Dict[str, Any], agent: Optional[Dict[str, Any]]) -> List[Dict[str, Any]]:\n    items: List[Dict[str, Any]] = []\n    read = g.get(\"conversation_messages\")\n    if isinstance(read, int) and not isinstance(read, bool):\n        items.append({\"key\": \"conversation\", \"label\": \"Recent conversation\",\n                      \"detail\": _count(read, \"message\") + \" read\", \"refs\": []})\n    for key in g.get(\"tools\") or []:\n        if not isinstance(key, str):\n            continue\n        detail, refs = \"\", []\n        if key == \"customer_orders\":\n            refs = _ids(g.get(\"order_ids\"))\n            detail = _count(len(g.get(\"order_ids\") or []), \"order\")\n        elif key == \"search_kb\":\n            entries = len(g.get(\"kb_ids\") or [])\n            passages = len(g.get(\"knowledge_ids\") or [])\n            detail = _count(entries, \"entry\", \"entries\") + \", \" + \\\n                _count(passages, \"document passage\")\n            refs = [str(c.get(\"section\") or c.get(\"source\") or \"\")\n                    for c in (g.get(\"citations\") or [])[:MAX_CITATIONS]\n                    if isinstance(c, dict)]\n        elif key == \"business_facts\":\n            refs = _ids(g.get(\"fact_ids\"))\n            detail = _count(len(g.get(\"fact_ids\") or []), \"fact\")\n        elif key == \"customer_memory\":\n            refs = _ids(g.get(\"memory_ids\"))\n            detail = _count(len(g.get(\"memory_ids\") or []), \"memory\", \"memories\")\n        elif key == \"agent_persona\":\n            detail = agent[\"name\"] if agent else \"\"\n        elif key == \"customer_profile\":\n            detail = \"Preferred language known\"\n        elif key == \"sales_context\":\n            sales = g.get(\"sales\") if isinstance(g.get(\"sales\"), dict) else {}\n            parts = [\"stage \" + str(sales.get(\"stage\") or \"unknown\")]\n            if sales.get(\"ask_next\"):\n                parts.append(\"asks next: \" + str(sales.get(\"ask_next\")))\n            if sales.get(\"objection\"):\n                parts.append(\"concern: \" + str(sales.get(\"objection\")) +\n                             (\" (approved answer)\" if sales.get(\"approved_answer\") else \"\"))\n            detail = \", \".join(parts)\n        elif key == \"loyalty_context\":\n            loyalty = g.get(\"loyalty\") if isinstance(g.get(\"loyalty\"), dict) else {}\n            detail = \"tier \" + str(loyalty.get(\"tier\") or \"none\") + \", \" + \\\n                _count(quadrant._int(loyalty.get(\"orders\")), \"past order\")\n        items.append({\"key\": key, \"label\": quadrant.TOOL_LABELS.get(key, key),\n                      \"detail\": detail, \"refs\": refs})\n    return items\n\n\ndef _input_message(cur, client_id: int, conversation_id: Optional[int], at: Any,\n                   input_chars: Any) -> Optional[Dict[str, Any]]:\n    \"\"\"The customer message the answer was about: the newest inbound message\n    up to the trace time. ``exact`` = written in the same transaction (and,\n    when the trace knows it, the same length).\"\"\"\n    if not conversation_id or at is None:\n        return None\n\n    def read() -> Optional[Dict[str, Any]]:\n        cur.execute(\n            \"SELECT id, body, created_at FROM \" + portal_db._q(portal_db.MSGS_TABLE) +\n            \" WHERE client_id = %s AND conversation_id = %s AND \" + INBOUND_SQL +\n            \" AND created_at <= %s ORDER BY created_at DESC, id DESC LIMIT 5\",\n            (client_id, conversation_id, at),\n        )\n        rows = portal_db.rows(cur)\n        if not rows:\n            return None\n        same = [r for r in rows if r.get(\"created_at\") == at]\n        sized = [r for r in same if isinstance(input_chars, int)\n                 and len(str(r.get(\"body\") or \"\").strip()) == input_chars]\n        pick = (sized or same or rows)[0]\n        return {\"message_id\": quadrant._int(pick.get(\"id\")),\n                \"body\": str(pick.get(\"body\") or \"\")[:MAX_BODY_CHARS],\n                \"created_at\": quadrant._iso(pick.get(\"created_at\")),\n                \"match\": \"exact\" if (sized or (same and not isinstance(input_chars, int)))\n                else (\"same_time\" if same else \"nearest\")}\n\n    return _optional(cur, (portal_db.MSGS_TABLE,), read, None)\n\n\ndef _queued_reply(cur, client_id: int, conversation_id: Optional[int],\n                  at: Any) -> Optional[Dict[str, Any]]:\n    if not conversation_id or at is None:\n        return None\n\n    def read() -> Optional[Dict[str, Any]]:\n        cur.execute(\n            \"SELECT id, status, payload->>'body' AS body, created_at FROM \" +\n            portal_db._q(portal_db.CMD_TABLE) +\n            \" WHERE client_id = %s AND action = 'send_message'\"\n            \" AND created_at = %s AND payload->>'source' = 'ai_brain'\"\n            \" AND payload->>'conversation_id' = %s ORDER BY id LIMIT 1\",\n            (client_id, at, str(conversation_id)),\n        )\n        rows = portal_db.rows(cur)\n        if not rows:\n            return None\n        row = rows[0]\n        return {\"command_id\": quadrant._int(row.get(\"id\")),\n                \"status\": str(row.get(\"status\") or \"\"),\n                \"body\": str(row.get(\"body\") or \"\")[:MAX_BODY_CHARS]}\n\n    return _optional(cur, (portal_db.CMD_TABLE,), read, None)\n\n\ndef _audit_rows(cur, client_id: int, conversation_id: Optional[int],\n                at: Any) -> List[Dict[str, Any]]:\n    if not conversation_id or at is None:\n        return []\n\n    def read() -> List[Dict[str, Any]]:\n        cur.execute(\n            \"SELECT id, action, actor_kind, note FROM \" + portal_db._q(LOG_TABLE) +\n            \" WHERE client_id = %s AND conversation_id = %s AND created_at = %s\"\n            \" ORDER BY id\",\n            (client_id, conversation_id, at),\n        )\n        return [{\"id\": quadrant._int(r.get(\"id\")), \"action\": str(r.get(\"action\") or \"\"),\n                 \"actor_kind\": str(r.get(\"actor_kind\") or \"\"),\n                 \"note\": str(r.get(\"note\") or \"\")} for r in portal_db.rows(cur)]\n\n    return _optional(cur, (LOG_TABLE,), read, [])\n\n\ndef _agent_version(cur, client_id: int, agent_id: int, at: Any) -> Optional[int]:\n    \"\"\"The persona version that was live when the answer ran.\"\"\"\n    if at is None:\n        return None\n\n    def read() -> Optional[int]:\n        cur.execute(\n            \"SELECT MAX(version) AS version FROM \" + portal_db._q(VERSIONS_TABLE) +\n            \" WHERE client_id = %s AND agent_id = %s AND created_at <= %s\",\n            (client_id, agent_id, at),\n        )\n        rows = portal_db.rows(cur)\n        version = (rows[0] if rows else {}).get(\"version\")\n        return quadrant._int(version) or None\n\n    return _optional(cur, (VERSIONS_TABLE,), read, None)\n\n\ndef _response(kind: str, decision: str, queued: Optional[Dict[str, Any]],\n              audit: List[Dict[str, Any]]) -> Dict[str, Any]:\n    if decision != \"send\":\n        escalated = any(a[\"action\"].startswith(\"escalation.\") for a in audit)\n        return {\"key\": \"response\", \"label\": \"Reply\", \"status\": \"skipped\",\n                \"detail\": {\"type\": \"handoff\", \"escalated\": escalated,\n                           \"note\": \"No reply sent: handed to the team.\"}}\n    if kind == \"draft\":\n        return {\"key\": \"response\", \"label\": \"Reply\", \"status\": \"ok\",\n                \"detail\": {\"type\": \"draft\",\n                           \"note\": \"Shown to the team member as a draft (drafts are not stored).\"}}\n    if kind == \"voice_answer\":\n        return {\"key\": \"response\", \"label\": \"Reply\", \"status\": \"ok\",\n                \"detail\": {\"type\": \"voice\", \"note\": \"Spoken on the phone call.\"}}\n    if queued:\n        return {\"key\": \"response\", \"label\": \"Reply\", \"status\": \"ok\",\n                \"detail\": dict(queued, type=\"message\")}\n    return {\"key\": \"response\", \"label\": \"Reply\", \"status\": \"unknown\",\n            \"detail\": {\"type\": \"message\",\n                       \"note\": \"The queued reply is no longer on record.\"}}\n\n\ndef build_detail(cur, client_id: int, row: Dict[str, Any]) -> Dict[str, Any]:\n    g = _grounding(row.get(\"grounding\"))\n    at = row.get(\"created_at\")\n    kind = str(row.get(\"kind\") or \"\")\n    decision = str(row.get(\"decision\") or \"\")\n    conversation_id = _id(row.get(\"conversation_id\"))\n    prices = _prices()\n    agent_id = _id(g.get(\"agent_id\"))\n    names = _agent_names(cur, client_id, [agent_id or 0])\n    agent = _agent(g, names)\n    reason = _reason(g, decision)\n    blocked = reason is not None and reason[\"key\"] == \"injection_suspected\"\n    calls = _calls(g)\n\n    message = _input_message(cur, client_id, conversation_id, at, g.get(\"input_chars\"))\n    audit = _audit_rows(cur, client_id, conversation_id, at)\n    queued = (_queued_reply(cur, client_id, conversation_id, at)\n              if kind == \"ingest_answer\" and decision == \"send\" else None)\n\n    guard = g.get(\"guard\") if isinstance(g.get(\"guard\"), dict) else None\n    steps: List[Dict[str, Any]] = [\n        {\"key\": \"input\", \"label\": \"Customer message\",\n         \"status\": \"ok\" if message else \"unknown\",\n         \"detail\": message or {\"input_chars\": g.get(\"input_chars\"),\n                               \"note\": \"The message is not on record (deleted, or not a chat message).\"}},\n        {\"key\": \"guard\", \"label\": \"Safety check\",\n         \"status\": \"blocked\" if blocked else (\"ok\" if guard else \"skipped\"),\n         \"detail\": guard or {}},\n    ]\n    if agent:\n        agent_detail = dict(agent, version=_agent_version(cur, client_id, agent[\"id\"], at),\n                            in_hours=g.get(\"agent_in_hours\"),\n                            auto_reply=g.get(\"agent_auto_reply\"))\n        steps.append({\"key\": \"agent\", \"label\": \"Agent\", \"status\": \"ok\",\n                      \"detail\": agent_detail})\n    else:\n        steps.append({\"key\": \"agent\", \"label\": \"Agent\",\n                      \"status\": \"skipped\" if blocked else \"ok\",\n                      \"detail\": {\"name\": \"Default assistant\"}})\n    steps.append({\"key\": \"tools\", \"label\": \"Context it read\",\n                  \"status\": \"skipped\" if blocked else \"ok\",\n                  \"detail\": {\"items\": _tool_items(g, agent)}})\n    steps.append({\n        \"key\": \"model\", \"label\": \"AI model\",\n        \"status\": (\"skipped\" if blocked or not (calls or \"llm_called\" in g)\n                   else \"ok\" if g.get(\"llm_called\") is True else \"failed\"),\n        \"detail\": {\"calls\": [dict(c, cost_usd=_cost([c], prices)) for c in calls],\n                   \"timings_ms\": g.get(\"timings_ms\") if isinstance(g.get(\"timings_ms\"), dict) else None,\n                   \"cost_usd\": _cost(calls, prices),\n                   \"prices_configured\": bool(prices)}})\n    steps.append({\"key\": \"decision\", \"label\": \"Decision\",\n                  \"status\": \"ok\" if decision == \"send\" else (\"blocked\" if blocked else \"warn\"),\n                  \"detail\": {\"decision\": decision, \"confidence\": _confidence(g),\n                             \"reason\": reason,\n                             \"policy_violations\": g.get(\"policy_violations\") or [],\n                             \"output_violations\": g.get(\"output_violations\") or []}})\n    steps.append(_response(kind, decision, queued, audit))\n    return {\n        \"id\": quadrant._int(row.get(\"id\")),\n        \"created_at\": quadrant._iso(at),\n        \"kind\": kind,\n        \"kind_label\": KINDS.get(kind, kind),\n        \"decision\": decision,\n        \"conversation_id\": conversation_id,\n        \"channel\": str(g.get(\"channel\") or \"\") or None,\n        \"steps\": steps,\n        \"audit\": audit,\n    }\n\n\ndef get_trace(cur, client_id: int, trace_id: int) -> Optional[Dict[str, Any]]:\n    if not quadrant._exists(cur, TRACES_TABLE):\n        return None\n    cur.execute(\n        \"SELECT id, conversation_id, kind, decision, grounding, created_at FROM \" +\n        portal_db._q(TRACES_TABLE) + \" WHERE client_id = %s AND id = %s\",\n        (client_id, trace_id),\n    )\n    rows = portal_db.rows(cur)\n    return build_detail(cur, client_id, rows[0]) if rows else None\n\n\n# ---------------------------------------------------------------------------\n# audit linkage (GET /ai/audit)\n# ---------------------------------------------------------------------------\n\ndef link_audit(cur, client_id: int, items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:\n    \"\"\"Give audit rows written with an AI answer a ``trace`` link (trace id,\n    agent, model): same workspace, conversation and transaction time. When\n    one transaction answered several messages, the n-th ``ai.answer`` row\n    pairs with the n-th sent automatic reply; other rows take the first.\"\"\"\n    wanted = [i for i in items if i.get(\"conversation_id\") and i.get(\"created_at\")]\n    if not wanted or not quadrant._exists(cur, TRACES_TABLE):\n        return items\n    cur.execute(\n        \"SELECT id, conversation_id, kind, decision, created_at, grounding FROM \" +\n        portal_db._q(TRACES_TABLE) +\n        \" WHERE client_id = %s AND conversation_id = ANY(%s)\"\n        \" AND created_at = ANY(CAST(%s AS timestamptz[])) ORDER BY id\",\n        (client_id, sorted({int(i[\"conversation_id\"]) for i in wanted}),\n         sorted({str(i[\"created_at\"]) for i in wanted})),\n    )\n    links: Dict[Tuple[int, str], List[Dict[str, Any]]] = {}\n    for row in portal_db.rows(cur):\n        key = (quadrant._int(row.get(\"conversation_id\")),\n               str(quadrant._iso(row.get(\"created_at\"))))\n        links.setdefault(key, []).append(row)\n    if not links:\n        return items\n    names = _agent_names(cur, client_id, [\n        _id(_grounding(r.get(\"grounding\")).get(\"agent_id\")) or 0\n        for rows in links.values() for r in rows])\n    answers: Dict[Tuple[int, str], List[int]] = {}\n    for item in sorted(wanted, key=lambda i: quadrant._int(i.get(\"id\"))):\n        if item.get(\"action\") == \"ai.answer\":\n            answers.setdefault((quadrant._int(item.get(\"conversation_id\")),\n                                str(item.get(\"created_at\"))), []).append(\n                quadrant._int(item.get(\"id\")))\n    out = []\n    for item in items:\n        key = (quadrant._int(item.get(\"conversation_id\")), str(item.get(\"created_at\")))\n        rows = links.get(key)\n        if not rows:\n            out.append(item)\n            continue\n        row = rows[0]\n        if item.get(\"action\") == \"ai.answer\":\n            sent = [r for r in rows if r.get(\"kind\") == \"ingest_answer\"\n                    and r.get(\"decision\") == \"send\"]\n            rank = answers.get(key, []).index(quadrant._int(item.get(\"id\")))\n            row = sent[rank] if rank < len(sent) else row\n        g = _grounding(row.get(\"grounding\"))\n        calls = _calls(g)\n        out.append(dict(item, trace={\n            \"id\": quadrant._int(row.get(\"id\")),\n            \"agent\": _agent(g, names),\n            \"model\": str(calls[0].get(\"model\") or \"\") or None if calls else None,\n        }))\n    return out\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef _human_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}), 401)\n    forbidden = ensure_human_principal(principal)\n    if forbidden:\n        return None, forbidden\n    return principal, None\n\n\ndef _read(fn: Callable[[Any], Any]) -> Any:\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            return fn(cur)\n    finally:\n        try:\n            conn.rollback()\n        finally:\n            conn.close()\n\n\nDOWN = {\"error\": {\"code\": \"portal_unavailable\",\n                  \"message\": \"AI traces are unavailable right now.\"}}\n\n\n@bp.get(\"/ai/traces\")\ndef ai_traces():\n    principal, error = _human_or_error()\n    if error:\n        return error\n    filters, message = parse_filters(request.args)\n    if filters is None:\n        return jsonify({\"error\": {\"code\": \"bad_request\", \"message\": message}}), 400\n    client_id = int(principal[\"client_id\"])\n    try:\n        data = _read(lambda cur: list_traces(cur, client_id, filters))\n    except Exception as error:\n        logger.warning(\"ai traces list failed: %s\", error)\n        return jsonify(DOWN), 503\n    return jsonify(data), 200\n\n\n@bp.get(\"/ai/traces/<trace_id>\")\ndef ai_trace(trace_id: str):\n    principal, error = _human_or_error()\n    if error:\n        return error\n    wanted = _whole(trace_id, 18)\n    if not wanted:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"Trace id must be a positive whole number.\"}}), 400\n    client_id = int(principal[\"client_id\"])\n    try:\n        data = _read(lambda cur: get_trace(cur, client_id, wanted))\n    except Exception as error:\n        logger.warning(\"ai trace detail failed: %s\", error)\n        return jsonify(DOWN), 503\n    if data is None:\n        return jsonify({\"error\": {\"code\": \"not_found\", \"message\": \"Trace not found.\"}}), 404\n    return jsonify(data), 200\n");
writeNewRepair("omniflow-backend-patch/portal_llm.py", "\u00a7241: ``scope.calls`` lists what the calls inside the block cost", false,
    "\"\"\"Tiny OpenAI-compatible chat client (standard library only).\n\nThe platform stays lightweight: no SDK, no new infrastructure. Point\n``OF_LLM_BASE_URL`` at any OpenAI-compatible endpoint (OpenAI, Groq,\nOpenRouter, a local Ollama) and put the key in ``OF_LLM_API_KEY``.\n\nContract: every helper is FAIL-SOFT. Callers receive ``None`` instead of an\nexception and must fall back to their non-LLM path, so a missing key, an\noutage or a slow provider never blocks a customer message. The default\nbudget is one attempt with a short timeout \u2014 the ingest loop must not stall.\n\"\"\"\n\nimport json\nimport logging\nimport math\nimport os\nimport threading\nimport time\nimport urllib.error\nimport urllib.request\nfrom typing import Any, Dict, List, Optional, Tuple\n\nlogger = logging.getLogger(\"omniflow.llm\")\n\n_SCOPE = threading.local()\n\n\nclass usage_scope:\n    \"\"\"Tag the LLM calls made inside the block for the AI usage ledger:\n\n        with portal_llm.usage_scope(\"brain\", client_id, cur, agent_id=agent_id):\n            payload = portal_llm.chat_json(...)\n\n    ``cur`` (optional) lets the ledger row ride the caller's transaction\n    (savepoint-guarded); without it the ledger opens its own short\n    connection. ``agent_id`` (optional) attributes the call to an AI\n    persona for per-agent cost split. Scopes nest (innermost wins) and\n    never raise.\n\n    \u00a7241: ``scope.calls`` lists what the calls inside the block cost (model,\n    tokens, latency, ok, route) so a caller can keep it on its own trace.\"\"\"\n\n    def __init__(self, feature: str, client_id: int = 0, cur=None,\n                 agent_id: int = 0):\n        self.entry = (str(feature or \"\")[:40], int(client_id or 0), cur,\n                      int(agent_id or 0))\n        self.calls: List[Dict[str, Any]] = []\n\n    def __enter__(self):\n        stack = getattr(_SCOPE, \"stack\", None)\n        if stack is None:\n            stack = _SCOPE.stack = []\n        stack.append(self.entry)\n        collectors = getattr(_SCOPE, \"collectors\", None)\n        if collectors is None:\n            collectors = _SCOPE.collectors = []\n        collectors.append(self.calls)\n        return self\n\n    def __exit__(self, *exc):\n        stack = getattr(_SCOPE, \"stack\", None)\n        if stack:\n            stack.pop()\n        collectors = getattr(_SCOPE, \"collectors\", None)\n        if collectors:\n            collectors.pop()\n        return False\n\n\ndef current_scope():\n    \"\"\"(feature, client_id, cur, agent_id) of the innermost usage_scope.\"\"\"\n    stack = getattr(_SCOPE, \"stack\", None)\n    return stack[-1] if stack else (\"\", 0, None, 0)\n\n\n#: most calls one scope keeps for its caller's trace (\u00a7241)\nMAX_SCOPE_CALLS = 5\n\n\ndef _collect(call: Dict[str, Any]) -> None:\n    \"\"\"Keep one call on the innermost usage_scope (\u00a7241 execution traces).\"\"\"\n    collectors = getattr(_SCOPE, \"collectors\", None)\n    if collectors and len(collectors[-1]) < MAX_SCOPE_CALLS:\n        collectors[-1].append(call)\n\n\ndef _record_usage(model: str, usage: Any, ok: bool, started: float,\n                  route: str = \"\") -> None:\n    \"\"\"Hand the call to the usage ledger (fail-soft, never raises).\n    ``route`` (\u00a7229) is only passed when the model router changed the\n    target (fast | smart | failover); plain AI-engine calls look as before.\"\"\"\n    try:\n        import portal_ai_usage\n\n        feature, client_id, cur, agent_id = current_scope()\n        usage = usage if isinstance(usage, dict) else {}\n        extra = {\"route\": route} if route else {}\n        prompt_tokens = int(usage.get(\"prompt_tokens\") or 0)\n        completion_tokens = int(usage.get(\"completion_tokens\") or 0)\n        latency_ms = int((time.time() - started) * 1000)\n        _collect({\"model\": str(model or \"\")[:80], \"route\": route,\n                  \"prompt_tokens\": prompt_tokens,\n                  \"completion_tokens\": completion_tokens,\n                  \"latency_ms\": latency_ms, \"ok\": bool(ok)})\n        portal_ai_usage.record(\n            client_id, feature or \"other\", model, prompt_tokens,\n            completion_tokens, latency_ms, ok, cur=cur,\n            agent_id=agent_id, **extra)\n    except Exception:\n        pass\n\n\ndef _record_routed(model: str, usage: Any, ok: bool, started: float,\n                   route: str) -> None:\n    # tests replace _record_usage with a 4-argument stub: keep that shape\n    # for every call the router did not change\n    if route:\n        _record_usage(model, usage, ok, started, route=route)\n    else:\n        _record_usage(model, usage, ok, started)\n\nBASE_URL = os.environ.get(\n    \"OF_LLM_BASE_URL\", \"https://api.openai.com/v1\").rstrip(\"/\")\nAPI_KEY = os.environ.get(\"OF_LLM_API_KEY\", \"\")\nMODEL = os.environ.get(\"OF_LLM_MODEL\", \"gpt-4o-mini\")\nTIMEOUT_SECONDS = float(os.environ.get(\"OF_LLM_TIMEOUT_SECONDS\", \"6\") or 6)\nATTEMPTS = max(1, int(os.environ.get(\"OF_LLM_ATTEMPTS\", \"1\") or 1))\nENABLED = os.environ.get(\n    \"OF_LLM_ENABLED\", \"1\").strip().lower() not in (\"0\", \"false\", \"no\", \"off\")\n\n\ndef _http_post_json(url: str, headers: Dict[str, str],\n                    payload: Dict[str, Any],\n                    timeout: Optional[float] = None) -> Optional[Dict[str, Any]]:\n    \"\"\"POST JSON, return the decoded body; None on any transport error.\"\"\"\n    try:\n        request = urllib.request.Request(\n            url,\n            data=json.dumps(payload).encode(\"utf-8\"),\n            headers=headers,\n            method=\"POST\",\n        )\n        with urllib.request.urlopen(\n                request, timeout=timeout or TIMEOUT_SECONDS) as resp:\n            return json.loads(resp.read().decode(\"utf-8\"))\n    except Exception:\n        return None\n\n\ndef _gated() -> bool:\n    \"\"\"Platform AI gate (admin kill switch / per-workspace daily call cap)\n    for the call being made in the current usage scope; fail-open.\"\"\"\n    try:\n        import portal_ai_usage\n\n        feature, client_id, cur, _agent_id = current_scope()\n        reason = portal_ai_usage.gate(feature, client_id, cur)\n    except Exception:\n        return False\n    if reason:\n        logger.info(\"llm call blocked (%s) client=%s feature=%s\",\n                    reason, client_id, feature)\n        return True\n    return False\n\n\ndef _runtime() -> Dict[str, Any]:\n    \"\"\"Effective config: admin panel first, env fallback (fail-soft).\"\"\"\n    try:\n        import platform_settings\n        config = platform_settings.llm_config()\n        if config.get(\"enabled\") and config.get(\"api_key\"):\n            return config\n        if not ENABLED:\n            return {\"base_url\": BASE_URL, \"api_key\": \"\", \"model\": MODEL,\n                    \"enabled\": False}\n        if config.get(\"api_key\"):\n            return config\n    except Exception:\n        pass\n    return {\"base_url\": BASE_URL, \"api_key\": API_KEY, \"model\": MODEL,\n            \"enabled\": bool(ENABLED and API_KEY)}\n\n\ndef _route_targets(runtime: Dict[str, Any]) -> List[Dict[str, Any]]:\n    \"\"\"Model router (\u00a7229): [chosen target] or [chosen, failover]. Falls\n    back to the AI engine alone when the router is missing or broken.\"\"\"\n    main = {\"provider\": \"primary\",\n            \"base_url\": str(runtime.get(\"base_url\") or BASE_URL).rstrip(\"/\"),\n            \"api_key\": str(runtime.get(\"api_key\") or \"\"),\n            \"model\": str(runtime.get(\"model\") or MODEL), \"route\": \"\"}\n    try:\n        import portal_model_router\n\n        return portal_model_router.plan(current_scope()[0], main) or [main]\n    except Exception:\n        return [main]\n\n\ndef _note_provider(target: Dict[str, Any], ok: bool) -> None:\n    try:\n        import portal_model_router\n\n        portal_model_router.note(target.get(\"provider\", \"\"), ok)\n    except Exception:\n        pass\n\n\ndef chat_json(system: str, user: str, max_tokens: int = 120,\n              timeout: Optional[float] = None) -> Optional[Dict[str, Any]]:\n    \"\"\"One JSON-mode chat call; parsed object or None (never raises).\n    ``timeout`` overrides OF_LLM_TIMEOUT_SECONDS for one long answer\n    (e.g. the website analyzer's extraction). The model router picks the\n    model for the current usage scope and fails over to the secondary\n    provider when the chosen one does not answer.\"\"\"\n    runtime = _runtime()\n    if not runtime.get(\"enabled\") or not runtime.get(\"api_key\"):\n        return None\n    if _gated():\n        return None\n    for target in _route_targets(runtime):\n        payload = {\n            \"model\": target[\"model\"] or MODEL,\n            \"messages\": [\n                {\"role\": \"system\", \"content\": system},\n                {\"role\": \"user\", \"content\": user},\n            ],\n            \"temperature\": 0,\n            \"max_tokens\": max_tokens,\n            \"response_format\": {\"type\": \"json_object\"},\n        }\n        headers = {\n            \"Authorization\": \"Bearer \" + str(target[\"api_key\"]),\n            \"Content-Type\": \"application/json\",\n        }\n        base = str(target[\"base_url\"] or BASE_URL).rstrip(\"/\")\n        model = str(payload[\"model\"])\n        route = str(target.get(\"route\") or \"\")\n        started = time.time()\n        last_usage = None\n        answered = False\n        for _ in range(ATTEMPTS):\n            if timeout:\n                data = _http_post_json(base + \"/chat/completions\", headers,\n                                       payload, timeout=timeout)\n            else:\n                data = _http_post_json(base + \"/chat/completions\", headers,\n                                       payload)\n            if not data:\n                continue\n            answered = True\n            last_usage = data.get(\"usage\") if isinstance(data, dict) else None\n            try:\n                content = data[\"choices\"][0][\"message\"][\"content\"]\n                parsed = json.loads(content)\n            except Exception:\n                continue\n            if isinstance(parsed, dict):\n                _note_provider(target, True)\n                _record_routed(model, last_usage, True, started, route)\n                return parsed\n        _note_provider(target, answered)\n        _record_routed(model, last_usage, False, started, route)\n        if answered:\n            # the provider is up; an unusable answer is not failed over\n            return None\n    return None\n\n\n# ---------------------------------------------------------------------------\n# Embeddings (D1 knowledge semantic index) - same OpenAI-compatible contract\n# ---------------------------------------------------------------------------\n\nEMBED_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_EMBED_TIMEOUT_SECONDS\", \"20\") or 20)\nEMBED_MAX_INPUTS = max(1, min(256, int(\n    os.environ.get(\"OF_EMBED_BATCH\", \"32\") or 32)))\nEMBED_TEXT_CHARS = max(200, int(\n    os.environ.get(\"OF_EMBED_TEXT_CHARS\", \"2000\") or 2000))\n\n\ndef embed_runtime() -> Dict[str, Any]:\n    \"\"\"Effective embedding config (platform_settings.embed_config);\n    inactive on any error.\"\"\"\n    try:\n        import platform_settings\n        return platform_settings.embed_config()\n    except Exception:\n        return {\"active\": False, \"reason\": \"no_key\", \"api_key\": \"\",\n                \"base_url\": BASE_URL, \"model\": \"\", \"dimensions\": 0,\n                \"min_similarity\": 0.3, \"mode\": \"on\", \"key_source\": \"none\"}\n\n\ndef normalize_vector(values: Any) -> Optional[List[float]]:\n    \"\"\"L2-normalise (needed for Matryoshka-truncated vectors, harmless for\n    the rest) so cosine similarity becomes a plain dot product.\"\"\"\n    try:\n        vector = [float(v) for v in values]\n    except Exception:\n        return None\n    if not vector:\n        return None\n    norm = math.sqrt(sum(v * v for v in vector))\n    if not norm or math.isnan(norm):\n        return None\n    return [v / norm for v in vector]\n\n\ndef _post_detail(url: str, headers: Dict[str, str], payload: Dict[str, Any],\n                 timeout: float) -> Tuple[Optional[Dict[str, Any]], str]:\n    \"\"\"POST JSON -> (body, \"\") or (None, short error) - never raises.\"\"\"\n    try:\n        request = urllib.request.Request(\n            url, data=json.dumps(payload).encode(\"utf-8\"), headers=headers,\n            method=\"POST\")\n        with urllib.request.urlopen(request, timeout=timeout) as resp:\n            return json.loads(resp.read().decode(\"utf-8\")), \"\"\n    except urllib.error.HTTPError as error:\n        detail = \"\"\n        try:\n            body = json.loads(error.read().decode(\"utf-8\") or \"{}\")\n            err = body.get(\"error\") if isinstance(body, dict) else None\n            if isinstance(err, dict):\n                detail = str(err.get(\"message\") or \"\")\n            elif isinstance(body, list) and body and isinstance(body[0], dict):\n                detail = str((body[0].get(\"error\") or {}).get(\"message\") or \"\")\n        except Exception:\n            detail = \"\"\n        return None, (\"HTTP \" + str(error.code)\n                      + (\": \" + detail[:160] if detail else \"\"))\n    except Exception as error:\n        return None, type(error).__name__ + \": \" + str(error)[:120]\n\n\ndef embed_texts(texts: List[str], timeout: Optional[float] = None,\n                runtime: Optional[Dict[str, Any]] = None\n                ) -> Tuple[Optional[List[List[float]]], str]:\n    \"\"\"Embed up to EMBED_MAX_INPUTS texts in one call.\n\n    Returns (normalised vectors in input order, \"\") or (None, reason).\n    Honours the platform AI gate (kill switch / daily cap) and writes one\n    usage-ledger row under the caller's usage_scope. Never raises.\"\"\"\n    items = [str(t or \"\")[:EMBED_TEXT_CHARS] for t in (texts or [])]\n    if not items:\n        return [], \"\"\n    if len(items) > EMBED_MAX_INPUTS:\n        return None, \"too many inputs for one call\"\n    config = runtime or embed_runtime()\n    if not config.get(\"active\") or not config.get(\"api_key\"):\n        return None, \"embeddings not configured (\" + str(\n            config.get(\"reason\") or \"no_key\") + \")\"\n    if _gated():\n        return None, \"blocked by the platform AI controls\"\n    model = str(config.get(\"model\") or \"\")\n    payload: Dict[str, Any] = {\"model\": model, \"input\": items}\n    dims = int(config.get(\"dimensions\") or 0)\n    if dims > 0:\n        payload[\"dimensions\"] = dims\n    headers = {\n        \"Authorization\": \"Bearer \" + str(config[\"api_key\"]),\n        \"Content-Type\": \"application/json\",\n    }\n    base = str(config.get(\"base_url\") or BASE_URL).rstrip(\"/\")\n    started = time.time()\n    data, error = _post_detail(base + \"/embeddings\", headers, payload,\n                               float(timeout or EMBED_TIMEOUT_SECONDS))\n    usage = data.get(\"usage\") if isinstance(data, dict) else None\n    if not isinstance(data, dict):\n        _record_usage(model, usage, False, started)\n        return None, error or \"no response\"\n    rows = data.get(\"data\")\n    if not isinstance(rows, list) or len(rows) != len(items):\n        _record_usage(model, usage, False, started)\n        return None, \"unexpected embeddings response\"\n    try:\n        ordered = sorted(rows, key=lambda r: int(r.get(\"index\", 0)))\n    except Exception:\n        ordered = rows\n    vectors: List[List[float]] = []\n    for row in ordered:\n        vector = normalize_vector((row or {}).get(\"embedding\") or [])\n        if vector is None:\n            _record_usage(model, usage, False, started)\n            return None, \"empty embedding in response\"\n        vectors.append(vector)\n    if len({len(v) for v in vectors}) != 1:\n        _record_usage(model, usage, False, started)\n        return None, \"inconsistent embedding sizes\"\n    _record_usage(model, usage, True, started)\n    return vectors, \"\"\n\n\n# ---------------------------------------------------------------------------\n# D5 media understanding: speech-to-text + image understanding. Same\n# contract as chat/embeddings: gated (kill switch / daily cap), one ledger\n# row per call under the caller's usage_scope, (result, error), never raises.\n# ---------------------------------------------------------------------------\n\nSTT_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_STT_TIMEOUT_SECONDS\", \"20\") or 20)\nVISION_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_VISION_TIMEOUT_SECONDS\", \"15\") or 15)\nVISION_MAX_TOKENS = max(64, min(1024, int(\n    os.environ.get(\"OF_VISION_MAX_TOKENS\", \"300\") or 300)))\n\n\ndef stt_runtime() -> Optional[Dict[str, str]]:\n    \"\"\"Resolved speech-to-text endpoint (portal_media owns the defaults:\n    admin panel -> env -> OpenAI whisper). None when no key is saved.\"\"\"\n    try:\n        import portal_media\n\n        resolved = portal_media._stt_config()\n    except Exception:\n        resolved = None\n    if not resolved:\n        return None\n    base, key, model = resolved\n    return {\"base_url\": base, \"api_key\": key, \"model\": model}\n\n\ndef vision_runtime() -> Dict[str, Any]:\n    try:\n        import platform_settings\n\n        return platform_settings.vision_config()\n    except Exception:\n        return {\"active\": False, \"reason\": \"no_key\", \"api_key\": \"\"}\n\n\ndef transcribe_audio(data: bytes, mime: str, filename: str = \"voice-note\",\n                     language: str = \"\", timeout: Optional[float] = None,\n                     runtime: Optional[Dict[str, str]] = None\n                     ) -> Tuple[Optional[str], str]:\n    \"\"\"Speech-to-text via the OpenAI-compatible /audio/transcriptions\n    endpoint (Whisper, Groq, ...). Returns (text, \"\") or (None, reason).\"\"\"\n    if not data:\n        return None, \"empty audio\"\n    config = runtime or stt_runtime()\n    if not config or not config.get(\"api_key\"):\n        return None, \"speech-to-text not configured\"\n    if _gated():\n        return None, \"blocked by the platform AI controls\"\n    try:\n        import portal_media\n\n        fields = {\"model\": str(config.get(\"model\") or \"\")}\n        if language:\n            fields[\"language\"] = str(language)[:8]\n        body, boundary = portal_media._multipart_body(\n            fields, \"file\", str(filename or \"voice-note\")[:80],\n            str(mime or \"audio/ogg\")[:80], data)\n    except Exception as error:\n        return None, \"could not build the upload: \" + str(error)[:80]\n    model = str(config.get(\"model\") or \"\")\n    started = time.time()\n    try:\n        request = urllib.request.Request(\n            str(config[\"base_url\"]).rstrip(\"/\") + \"/audio/transcriptions\",\n            data=body, method=\"POST\")\n        request.add_header(\"Content-Type\",\n                           \"multipart/form-data; boundary=\" + boundary)\n        request.add_header(\"Authorization\", \"Bearer \" + str(config[\"api_key\"]))\n        with urllib.request.urlopen(\n                request, timeout=float(timeout or STT_TIMEOUT_SECONDS)) as resp:\n            parsed = json.loads(resp.read().decode(\"utf-8\", \"replace\"))\n    except urllib.error.HTTPError as error:\n        _record_usage(model, None, False, started)\n        return None, \"HTTP \" + str(error.code)\n    except Exception as error:\n        _record_usage(model, None, False, started)\n        return None, type(error).__name__ + \": \" + str(error)[:100]\n    text = str((parsed or {}).get(\"text\") or \"\").strip() \\\n        if isinstance(parsed, dict) else \"\"\n    _record_usage(model, None, bool(text), started)\n    if not text:\n        return None, \"no speech recognised\"\n    return text, \"\"\n\n\ndef describe_image(data: bytes, mime: str, system: str, prompt: str,\n                   timeout: Optional[float] = None,\n                   runtime: Optional[Dict[str, Any]] = None,\n                   max_tokens: int = 0\n                   ) -> Tuple[Optional[Dict[str, Any]], str]:\n    \"\"\"One JSON-mode multimodal chat call with an inline image (data URI,\n    the OpenAI-compatible shape Gemini and OpenAI both accept).\n    Returns (parsed object, \"\") or (None, reason).\"\"\"\n    if not data:\n        return None, \"empty image\"\n    config = runtime or vision_runtime()\n    if not config.get(\"active\") or not config.get(\"api_key\"):\n        return None, \"image understanding not configured (\" + str(\n            config.get(\"reason\") or \"no_key\") + \")\"\n    if _gated():\n        return None, \"blocked by the platform AI controls\"\n    import base64 as _b64\n\n    data_uri = (\"data:\" + (str(mime or \"image/jpeg\")[:40]) + \";base64,\"\n                + _b64.b64encode(data).decode(\"ascii\"))\n    model = str(config.get(\"model\") or MODEL)\n    payload = {\n        \"model\": model,\n        \"messages\": [\n            {\"role\": \"system\", \"content\": system},\n            {\"role\": \"user\", \"content\": [\n                {\"type\": \"text\", \"text\": prompt},\n                {\"type\": \"image_url\", \"image_url\": {\"url\": data_uri}},\n            ]},\n        ],\n        \"temperature\": 0,\n        \"max_tokens\": int(max_tokens or VISION_MAX_TOKENS),\n        \"response_format\": {\"type\": \"json_object\"},\n    }\n    headers = {\"Authorization\": \"Bearer \" + str(config[\"api_key\"]),\n               \"Content-Type\": \"application/json\"}\n    base = str(config.get(\"base_url\") or BASE_URL).rstrip(\"/\")\n    started = time.time()\n    body, error = _post_detail(base + \"/chat/completions\", headers, payload,\n                               float(timeout or VISION_TIMEOUT_SECONDS))\n    usage = body.get(\"usage\") if isinstance(body, dict) else None\n    if not isinstance(body, dict):\n        _record_usage(model, usage, False, started)\n        return None, error or \"no response\"\n    try:\n        content = body[\"choices\"][0][\"message\"][\"content\"]\n        parsed = json.loads(content)\n    except Exception:\n        _record_usage(model, usage, False, started)\n        return None, \"unexpected vision response\"\n    if not isinstance(parsed, dict):\n        _record_usage(model, usage, False, started)\n        return None, \"unexpected vision response\"\n    _record_usage(model, usage, True, started)\n    return parsed, \"\"\n\n\n# ---------------------------------------------------------------------------\n# Ask OmniFlow AI (\u00a7227) - the owner's assistant: own key group, multi-turn\n# ---------------------------------------------------------------------------\n\nASSISTANT_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_ASSISTANT_TIMEOUT\", \"20\") or 20)\n\n\ndef assistant_runtime() -> Dict[str, Any]:\n    try:\n        import platform_settings\n\n        return platform_settings.assistant_config()\n    except Exception:\n        return {\"active\": False, \"reason\": \"no_key\", \"api_key\": \"\"}\n\n\ndef chat_messages_json(messages: List[Dict[str, str]],\n                       runtime: Optional[Dict[str, Any]] = None,\n                       max_tokens: int = 700,\n                       timeout: Optional[float] = None\n                       ) -> Tuple[Optional[Dict[str, Any]], str]:\n    \"\"\"One JSON-mode chat call over a whole message list (system + history\n    + tool results). Returns (parsed object, \"\") or (None, reason) where\n    reason is not_configured | blocked | a short provider error. Gated by\n    the platform AI controls and recorded in the usage ledger.\"\"\"\n    config = runtime or assistant_runtime()\n    if not config.get(\"active\") or not config.get(\"api_key\"):\n        return None, \"not_configured\"\n    if _gated():\n        return None, \"blocked\"\n    model = str(config.get(\"model\") or MODEL)\n    targets = [{\"provider\": \"\", \"route\": \"\", \"model\": model,\n                \"api_key\": str(config[\"api_key\"]),\n                \"base_url\": str(config.get(\"base_url\") or BASE_URL).rstrip(\"/\")}]\n    # \u00a7229: the router's secondary provider covers an assistant outage\n    try:\n        import portal_model_router\n\n        backup = portal_model_router.failover_for(model)\n    except Exception:\n        backup = None\n    if backup and backup[\"api_key\"] != targets[0][\"api_key\"]:\n        targets.append(backup)\n    error = \"\"\n    for target in targets:\n        payload = {\n            \"model\": target[\"model\"],\n            \"messages\": messages,\n            \"temperature\": 0.2,\n            \"max_tokens\": int(max_tokens or 700),\n            \"response_format\": {\"type\": \"json_object\"},\n        }\n        headers = {\"Authorization\": \"Bearer \" + target[\"api_key\"],\n                   \"Content-Type\": \"application/json\"}\n        started = time.time()\n        body, error = _post_detail(target[\"base_url\"] + \"/chat/completions\",\n                                   headers, payload,\n                                   float(timeout or ASSISTANT_TIMEOUT_SECONDS))\n        usage = body.get(\"usage\") if isinstance(body, dict) else None\n        try:\n            parsed = json.loads(body[\"choices\"][0][\"message\"][\"content\"])\n        except Exception:\n            parsed = None\n        if isinstance(parsed, dict):\n            _record_routed(target[\"model\"], usage, True, started, target[\"route\"])\n            return parsed, \"\"\n        _record_routed(target[\"model\"], usage, False, started, target[\"route\"])\n        if isinstance(body, dict):\n            break  # the provider answered; not an outage\n    return None, error or \"unexpected response\"\n");
writeNewRepair("OmniFlow-Control-Plane/portal_llm.py", "\u00a7241: ``scope.calls`` lists what the calls inside the block cost", true,
    "\"\"\"Tiny OpenAI-compatible chat client (standard library only).\n\nThe platform stays lightweight: no SDK, no new infrastructure. Point\n``OF_LLM_BASE_URL`` at any OpenAI-compatible endpoint (OpenAI, Groq,\nOpenRouter, a local Ollama) and put the key in ``OF_LLM_API_KEY``.\n\nContract: every helper is FAIL-SOFT. Callers receive ``None`` instead of an\nexception and must fall back to their non-LLM path, so a missing key, an\noutage or a slow provider never blocks a customer message. The default\nbudget is one attempt with a short timeout \u2014 the ingest loop must not stall.\n\"\"\"\n\nimport json\nimport logging\nimport math\nimport os\nimport threading\nimport time\nimport urllib.error\nimport urllib.request\nfrom typing import Any, Dict, List, Optional, Tuple\n\nlogger = logging.getLogger(\"omniflow.llm\")\n\n_SCOPE = threading.local()\n\n\nclass usage_scope:\n    \"\"\"Tag the LLM calls made inside the block for the AI usage ledger:\n\n        with portal_llm.usage_scope(\"brain\", client_id, cur, agent_id=agent_id):\n            payload = portal_llm.chat_json(...)\n\n    ``cur`` (optional) lets the ledger row ride the caller's transaction\n    (savepoint-guarded); without it the ledger opens its own short\n    connection. ``agent_id`` (optional) attributes the call to an AI\n    persona for per-agent cost split. Scopes nest (innermost wins) and\n    never raise.\n\n    \u00a7241: ``scope.calls`` lists what the calls inside the block cost (model,\n    tokens, latency, ok, route) so a caller can keep it on its own trace.\"\"\"\n\n    def __init__(self, feature: str, client_id: int = 0, cur=None,\n                 agent_id: int = 0):\n        self.entry = (str(feature or \"\")[:40], int(client_id or 0), cur,\n                      int(agent_id or 0))\n        self.calls: List[Dict[str, Any]] = []\n\n    def __enter__(self):\n        stack = getattr(_SCOPE, \"stack\", None)\n        if stack is None:\n            stack = _SCOPE.stack = []\n        stack.append(self.entry)\n        collectors = getattr(_SCOPE, \"collectors\", None)\n        if collectors is None:\n            collectors = _SCOPE.collectors = []\n        collectors.append(self.calls)\n        return self\n\n    def __exit__(self, *exc):\n        stack = getattr(_SCOPE, \"stack\", None)\n        if stack:\n            stack.pop()\n        collectors = getattr(_SCOPE, \"collectors\", None)\n        if collectors:\n            collectors.pop()\n        return False\n\n\ndef current_scope():\n    \"\"\"(feature, client_id, cur, agent_id) of the innermost usage_scope.\"\"\"\n    stack = getattr(_SCOPE, \"stack\", None)\n    return stack[-1] if stack else (\"\", 0, None, 0)\n\n\n#: most calls one scope keeps for its caller's trace (\u00a7241)\nMAX_SCOPE_CALLS = 5\n\n\ndef _collect(call: Dict[str, Any]) -> None:\n    \"\"\"Keep one call on the innermost usage_scope (\u00a7241 execution traces).\"\"\"\n    collectors = getattr(_SCOPE, \"collectors\", None)\n    if collectors and len(collectors[-1]) < MAX_SCOPE_CALLS:\n        collectors[-1].append(call)\n\n\ndef _record_usage(model: str, usage: Any, ok: bool, started: float,\n                  route: str = \"\") -> None:\n    \"\"\"Hand the call to the usage ledger (fail-soft, never raises).\n    ``route`` (\u00a7229) is only passed when the model router changed the\n    target (fast | smart | failover); plain AI-engine calls look as before.\"\"\"\n    try:\n        import portal_ai_usage\n\n        feature, client_id, cur, agent_id = current_scope()\n        usage = usage if isinstance(usage, dict) else {}\n        extra = {\"route\": route} if route else {}\n        prompt_tokens = int(usage.get(\"prompt_tokens\") or 0)\n        completion_tokens = int(usage.get(\"completion_tokens\") or 0)\n        latency_ms = int((time.time() - started) * 1000)\n        _collect({\"model\": str(model or \"\")[:80], \"route\": route,\n                  \"prompt_tokens\": prompt_tokens,\n                  \"completion_tokens\": completion_tokens,\n                  \"latency_ms\": latency_ms, \"ok\": bool(ok)})\n        portal_ai_usage.record(\n            client_id, feature or \"other\", model, prompt_tokens,\n            completion_tokens, latency_ms, ok, cur=cur,\n            agent_id=agent_id, **extra)\n    except Exception:\n        pass\n\n\ndef _record_routed(model: str, usage: Any, ok: bool, started: float,\n                   route: str) -> None:\n    # tests replace _record_usage with a 4-argument stub: keep that shape\n    # for every call the router did not change\n    if route:\n        _record_usage(model, usage, ok, started, route=route)\n    else:\n        _record_usage(model, usage, ok, started)\n\nBASE_URL = os.environ.get(\n    \"OF_LLM_BASE_URL\", \"https://api.openai.com/v1\").rstrip(\"/\")\nAPI_KEY = os.environ.get(\"OF_LLM_API_KEY\", \"\")\nMODEL = os.environ.get(\"OF_LLM_MODEL\", \"gpt-4o-mini\")\nTIMEOUT_SECONDS = float(os.environ.get(\"OF_LLM_TIMEOUT_SECONDS\", \"6\") or 6)\nATTEMPTS = max(1, int(os.environ.get(\"OF_LLM_ATTEMPTS\", \"1\") or 1))\nENABLED = os.environ.get(\n    \"OF_LLM_ENABLED\", \"1\").strip().lower() not in (\"0\", \"false\", \"no\", \"off\")\n\n\ndef _http_post_json(url: str, headers: Dict[str, str],\n                    payload: Dict[str, Any],\n                    timeout: Optional[float] = None) -> Optional[Dict[str, Any]]:\n    \"\"\"POST JSON, return the decoded body; None on any transport error.\"\"\"\n    try:\n        request = urllib.request.Request(\n            url,\n            data=json.dumps(payload).encode(\"utf-8\"),\n            headers=headers,\n            method=\"POST\",\n        )\n        with urllib.request.urlopen(\n                request, timeout=timeout or TIMEOUT_SECONDS) as resp:\n            return json.loads(resp.read().decode(\"utf-8\"))\n    except Exception:\n        return None\n\n\ndef _gated() -> bool:\n    \"\"\"Platform AI gate (admin kill switch / per-workspace daily call cap)\n    for the call being made in the current usage scope; fail-open.\"\"\"\n    try:\n        import portal_ai_usage\n\n        feature, client_id, cur, _agent_id = current_scope()\n        reason = portal_ai_usage.gate(feature, client_id, cur)\n    except Exception:\n        return False\n    if reason:\n        logger.info(\"llm call blocked (%s) client=%s feature=%s\",\n                    reason, client_id, feature)\n        return True\n    return False\n\n\ndef _runtime() -> Dict[str, Any]:\n    \"\"\"Effective config: admin panel first, env fallback (fail-soft).\"\"\"\n    try:\n        import platform_settings\n        config = platform_settings.llm_config()\n        if config.get(\"enabled\") and config.get(\"api_key\"):\n            return config\n        if not ENABLED:\n            return {\"base_url\": BASE_URL, \"api_key\": \"\", \"model\": MODEL,\n                    \"enabled\": False}\n        if config.get(\"api_key\"):\n            return config\n    except Exception:\n        pass\n    return {\"base_url\": BASE_URL, \"api_key\": API_KEY, \"model\": MODEL,\n            \"enabled\": bool(ENABLED and API_KEY)}\n\n\ndef _route_targets(runtime: Dict[str, Any]) -> List[Dict[str, Any]]:\n    \"\"\"Model router (\u00a7229): [chosen target] or [chosen, failover]. Falls\n    back to the AI engine alone when the router is missing or broken.\"\"\"\n    main = {\"provider\": \"primary\",\n            \"base_url\": str(runtime.get(\"base_url\") or BASE_URL).rstrip(\"/\"),\n            \"api_key\": str(runtime.get(\"api_key\") or \"\"),\n            \"model\": str(runtime.get(\"model\") or MODEL), \"route\": \"\"}\n    try:\n        import portal_model_router\n\n        return portal_model_router.plan(current_scope()[0], main) or [main]\n    except Exception:\n        return [main]\n\n\ndef _note_provider(target: Dict[str, Any], ok: bool) -> None:\n    try:\n        import portal_model_router\n\n        portal_model_router.note(target.get(\"provider\", \"\"), ok)\n    except Exception:\n        pass\n\n\ndef chat_json(system: str, user: str, max_tokens: int = 120,\n              timeout: Optional[float] = None) -> Optional[Dict[str, Any]]:\n    \"\"\"One JSON-mode chat call; parsed object or None (never raises).\n    ``timeout`` overrides OF_LLM_TIMEOUT_SECONDS for one long answer\n    (e.g. the website analyzer's extraction). The model router picks the\n    model for the current usage scope and fails over to the secondary\n    provider when the chosen one does not answer.\"\"\"\n    runtime = _runtime()\n    if not runtime.get(\"enabled\") or not runtime.get(\"api_key\"):\n        return None\n    if _gated():\n        return None\n    for target in _route_targets(runtime):\n        payload = {\n            \"model\": target[\"model\"] or MODEL,\n            \"messages\": [\n                {\"role\": \"system\", \"content\": system},\n                {\"role\": \"user\", \"content\": user},\n            ],\n            \"temperature\": 0,\n            \"max_tokens\": max_tokens,\n            \"response_format\": {\"type\": \"json_object\"},\n        }\n        headers = {\n            \"Authorization\": \"Bearer \" + str(target[\"api_key\"]),\n            \"Content-Type\": \"application/json\",\n        }\n        base = str(target[\"base_url\"] or BASE_URL).rstrip(\"/\")\n        model = str(payload[\"model\"])\n        route = str(target.get(\"route\") or \"\")\n        started = time.time()\n        last_usage = None\n        answered = False\n        for _ in range(ATTEMPTS):\n            if timeout:\n                data = _http_post_json(base + \"/chat/completions\", headers,\n                                       payload, timeout=timeout)\n            else:\n                data = _http_post_json(base + \"/chat/completions\", headers,\n                                       payload)\n            if not data:\n                continue\n            answered = True\n            last_usage = data.get(\"usage\") if isinstance(data, dict) else None\n            try:\n                content = data[\"choices\"][0][\"message\"][\"content\"]\n                parsed = json.loads(content)\n            except Exception:\n                continue\n            if isinstance(parsed, dict):\n                _note_provider(target, True)\n                _record_routed(model, last_usage, True, started, route)\n                return parsed\n        _note_provider(target, answered)\n        _record_routed(model, last_usage, False, started, route)\n        if answered:\n            # the provider is up; an unusable answer is not failed over\n            return None\n    return None\n\n\n# ---------------------------------------------------------------------------\n# Embeddings (D1 knowledge semantic index) - same OpenAI-compatible contract\n# ---------------------------------------------------------------------------\n\nEMBED_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_EMBED_TIMEOUT_SECONDS\", \"20\") or 20)\nEMBED_MAX_INPUTS = max(1, min(256, int(\n    os.environ.get(\"OF_EMBED_BATCH\", \"32\") or 32)))\nEMBED_TEXT_CHARS = max(200, int(\n    os.environ.get(\"OF_EMBED_TEXT_CHARS\", \"2000\") or 2000))\n\n\ndef embed_runtime() -> Dict[str, Any]:\n    \"\"\"Effective embedding config (platform_settings.embed_config);\n    inactive on any error.\"\"\"\n    try:\n        import platform_settings\n        return platform_settings.embed_config()\n    except Exception:\n        return {\"active\": False, \"reason\": \"no_key\", \"api_key\": \"\",\n                \"base_url\": BASE_URL, \"model\": \"\", \"dimensions\": 0,\n                \"min_similarity\": 0.3, \"mode\": \"on\", \"key_source\": \"none\"}\n\n\ndef normalize_vector(values: Any) -> Optional[List[float]]:\n    \"\"\"L2-normalise (needed for Matryoshka-truncated vectors, harmless for\n    the rest) so cosine similarity becomes a plain dot product.\"\"\"\n    try:\n        vector = [float(v) for v in values]\n    except Exception:\n        return None\n    if not vector:\n        return None\n    norm = math.sqrt(sum(v * v for v in vector))\n    if not norm or math.isnan(norm):\n        return None\n    return [v / norm for v in vector]\n\n\ndef _post_detail(url: str, headers: Dict[str, str], payload: Dict[str, Any],\n                 timeout: float) -> Tuple[Optional[Dict[str, Any]], str]:\n    \"\"\"POST JSON -> (body, \"\") or (None, short error) - never raises.\"\"\"\n    try:\n        request = urllib.request.Request(\n            url, data=json.dumps(payload).encode(\"utf-8\"), headers=headers,\n            method=\"POST\")\n        with urllib.request.urlopen(request, timeout=timeout) as resp:\n            return json.loads(resp.read().decode(\"utf-8\")), \"\"\n    except urllib.error.HTTPError as error:\n        detail = \"\"\n        try:\n            body = json.loads(error.read().decode(\"utf-8\") or \"{}\")\n            err = body.get(\"error\") if isinstance(body, dict) else None\n            if isinstance(err, dict):\n                detail = str(err.get(\"message\") or \"\")\n            elif isinstance(body, list) and body and isinstance(body[0], dict):\n                detail = str((body[0].get(\"error\") or {}).get(\"message\") or \"\")\n        except Exception:\n            detail = \"\"\n        return None, (\"HTTP \" + str(error.code)\n                      + (\": \" + detail[:160] if detail else \"\"))\n    except Exception as error:\n        return None, type(error).__name__ + \": \" + str(error)[:120]\n\n\ndef embed_texts(texts: List[str], timeout: Optional[float] = None,\n                runtime: Optional[Dict[str, Any]] = None\n                ) -> Tuple[Optional[List[List[float]]], str]:\n    \"\"\"Embed up to EMBED_MAX_INPUTS texts in one call.\n\n    Returns (normalised vectors in input order, \"\") or (None, reason).\n    Honours the platform AI gate (kill switch / daily cap) and writes one\n    usage-ledger row under the caller's usage_scope. Never raises.\"\"\"\n    items = [str(t or \"\")[:EMBED_TEXT_CHARS] for t in (texts or [])]\n    if not items:\n        return [], \"\"\n    if len(items) > EMBED_MAX_INPUTS:\n        return None, \"too many inputs for one call\"\n    config = runtime or embed_runtime()\n    if not config.get(\"active\") or not config.get(\"api_key\"):\n        return None, \"embeddings not configured (\" + str(\n            config.get(\"reason\") or \"no_key\") + \")\"\n    if _gated():\n        return None, \"blocked by the platform AI controls\"\n    model = str(config.get(\"model\") or \"\")\n    payload: Dict[str, Any] = {\"model\": model, \"input\": items}\n    dims = int(config.get(\"dimensions\") or 0)\n    if dims > 0:\n        payload[\"dimensions\"] = dims\n    headers = {\n        \"Authorization\": \"Bearer \" + str(config[\"api_key\"]),\n        \"Content-Type\": \"application/json\",\n    }\n    base = str(config.get(\"base_url\") or BASE_URL).rstrip(\"/\")\n    started = time.time()\n    data, error = _post_detail(base + \"/embeddings\", headers, payload,\n                               float(timeout or EMBED_TIMEOUT_SECONDS))\n    usage = data.get(\"usage\") if isinstance(data, dict) else None\n    if not isinstance(data, dict):\n        _record_usage(model, usage, False, started)\n        return None, error or \"no response\"\n    rows = data.get(\"data\")\n    if not isinstance(rows, list) or len(rows) != len(items):\n        _record_usage(model, usage, False, started)\n        return None, \"unexpected embeddings response\"\n    try:\n        ordered = sorted(rows, key=lambda r: int(r.get(\"index\", 0)))\n    except Exception:\n        ordered = rows\n    vectors: List[List[float]] = []\n    for row in ordered:\n        vector = normalize_vector((row or {}).get(\"embedding\") or [])\n        if vector is None:\n            _record_usage(model, usage, False, started)\n            return None, \"empty embedding in response\"\n        vectors.append(vector)\n    if len({len(v) for v in vectors}) != 1:\n        _record_usage(model, usage, False, started)\n        return None, \"inconsistent embedding sizes\"\n    _record_usage(model, usage, True, started)\n    return vectors, \"\"\n\n\n# ---------------------------------------------------------------------------\n# D5 media understanding: speech-to-text + image understanding. Same\n# contract as chat/embeddings: gated (kill switch / daily cap), one ledger\n# row per call under the caller's usage_scope, (result, error), never raises.\n# ---------------------------------------------------------------------------\n\nSTT_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_STT_TIMEOUT_SECONDS\", \"20\") or 20)\nVISION_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_VISION_TIMEOUT_SECONDS\", \"15\") or 15)\nVISION_MAX_TOKENS = max(64, min(1024, int(\n    os.environ.get(\"OF_VISION_MAX_TOKENS\", \"300\") or 300)))\n\n\ndef stt_runtime() -> Optional[Dict[str, str]]:\n    \"\"\"Resolved speech-to-text endpoint (portal_media owns the defaults:\n    admin panel -> env -> OpenAI whisper). None when no key is saved.\"\"\"\n    try:\n        import portal_media\n\n        resolved = portal_media._stt_config()\n    except Exception:\n        resolved = None\n    if not resolved:\n        return None\n    base, key, model = resolved\n    return {\"base_url\": base, \"api_key\": key, \"model\": model}\n\n\ndef vision_runtime() -> Dict[str, Any]:\n    try:\n        import platform_settings\n\n        return platform_settings.vision_config()\n    except Exception:\n        return {\"active\": False, \"reason\": \"no_key\", \"api_key\": \"\"}\n\n\ndef transcribe_audio(data: bytes, mime: str, filename: str = \"voice-note\",\n                     language: str = \"\", timeout: Optional[float] = None,\n                     runtime: Optional[Dict[str, str]] = None\n                     ) -> Tuple[Optional[str], str]:\n    \"\"\"Speech-to-text via the OpenAI-compatible /audio/transcriptions\n    endpoint (Whisper, Groq, ...). Returns (text, \"\") or (None, reason).\"\"\"\n    if not data:\n        return None, \"empty audio\"\n    config = runtime or stt_runtime()\n    if not config or not config.get(\"api_key\"):\n        return None, \"speech-to-text not configured\"\n    if _gated():\n        return None, \"blocked by the platform AI controls\"\n    try:\n        import portal_media\n\n        fields = {\"model\": str(config.get(\"model\") or \"\")}\n        if language:\n            fields[\"language\"] = str(language)[:8]\n        body, boundary = portal_media._multipart_body(\n            fields, \"file\", str(filename or \"voice-note\")[:80],\n            str(mime or \"audio/ogg\")[:80], data)\n    except Exception as error:\n        return None, \"could not build the upload: \" + str(error)[:80]\n    model = str(config.get(\"model\") or \"\")\n    started = time.time()\n    try:\n        request = urllib.request.Request(\n            str(config[\"base_url\"]).rstrip(\"/\") + \"/audio/transcriptions\",\n            data=body, method=\"POST\")\n        request.add_header(\"Content-Type\",\n                           \"multipart/form-data; boundary=\" + boundary)\n        request.add_header(\"Authorization\", \"Bearer \" + str(config[\"api_key\"]))\n        with urllib.request.urlopen(\n                request, timeout=float(timeout or STT_TIMEOUT_SECONDS)) as resp:\n            parsed = json.loads(resp.read().decode(\"utf-8\", \"replace\"))\n    except urllib.error.HTTPError as error:\n        _record_usage(model, None, False, started)\n        return None, \"HTTP \" + str(error.code)\n    except Exception as error:\n        _record_usage(model, None, False, started)\n        return None, type(error).__name__ + \": \" + str(error)[:100]\n    text = str((parsed or {}).get(\"text\") or \"\").strip() \\\n        if isinstance(parsed, dict) else \"\"\n    _record_usage(model, None, bool(text), started)\n    if not text:\n        return None, \"no speech recognised\"\n    return text, \"\"\n\n\ndef describe_image(data: bytes, mime: str, system: str, prompt: str,\n                   timeout: Optional[float] = None,\n                   runtime: Optional[Dict[str, Any]] = None,\n                   max_tokens: int = 0\n                   ) -> Tuple[Optional[Dict[str, Any]], str]:\n    \"\"\"One JSON-mode multimodal chat call with an inline image (data URI,\n    the OpenAI-compatible shape Gemini and OpenAI both accept).\n    Returns (parsed object, \"\") or (None, reason).\"\"\"\n    if not data:\n        return None, \"empty image\"\n    config = runtime or vision_runtime()\n    if not config.get(\"active\") or not config.get(\"api_key\"):\n        return None, \"image understanding not configured (\" + str(\n            config.get(\"reason\") or \"no_key\") + \")\"\n    if _gated():\n        return None, \"blocked by the platform AI controls\"\n    import base64 as _b64\n\n    data_uri = (\"data:\" + (str(mime or \"image/jpeg\")[:40]) + \";base64,\"\n                + _b64.b64encode(data).decode(\"ascii\"))\n    model = str(config.get(\"model\") or MODEL)\n    payload = {\n        \"model\": model,\n        \"messages\": [\n            {\"role\": \"system\", \"content\": system},\n            {\"role\": \"user\", \"content\": [\n                {\"type\": \"text\", \"text\": prompt},\n                {\"type\": \"image_url\", \"image_url\": {\"url\": data_uri}},\n            ]},\n        ],\n        \"temperature\": 0,\n        \"max_tokens\": int(max_tokens or VISION_MAX_TOKENS),\n        \"response_format\": {\"type\": \"json_object\"},\n    }\n    headers = {\"Authorization\": \"Bearer \" + str(config[\"api_key\"]),\n               \"Content-Type\": \"application/json\"}\n    base = str(config.get(\"base_url\") or BASE_URL).rstrip(\"/\")\n    started = time.time()\n    body, error = _post_detail(base + \"/chat/completions\", headers, payload,\n                               float(timeout or VISION_TIMEOUT_SECONDS))\n    usage = body.get(\"usage\") if isinstance(body, dict) else None\n    if not isinstance(body, dict):\n        _record_usage(model, usage, False, started)\n        return None, error or \"no response\"\n    try:\n        content = body[\"choices\"][0][\"message\"][\"content\"]\n        parsed = json.loads(content)\n    except Exception:\n        _record_usage(model, usage, False, started)\n        return None, \"unexpected vision response\"\n    if not isinstance(parsed, dict):\n        _record_usage(model, usage, False, started)\n        return None, \"unexpected vision response\"\n    _record_usage(model, usage, True, started)\n    return parsed, \"\"\n\n\n# ---------------------------------------------------------------------------\n# Ask OmniFlow AI (\u00a7227) - the owner's assistant: own key group, multi-turn\n# ---------------------------------------------------------------------------\n\nASSISTANT_TIMEOUT_SECONDS = float(\n    os.environ.get(\"OF_ASSISTANT_TIMEOUT\", \"20\") or 20)\n\n\ndef assistant_runtime() -> Dict[str, Any]:\n    try:\n        import platform_settings\n\n        return platform_settings.assistant_config()\n    except Exception:\n        return {\"active\": False, \"reason\": \"no_key\", \"api_key\": \"\"}\n\n\ndef chat_messages_json(messages: List[Dict[str, str]],\n                       runtime: Optional[Dict[str, Any]] = None,\n                       max_tokens: int = 700,\n                       timeout: Optional[float] = None\n                       ) -> Tuple[Optional[Dict[str, Any]], str]:\n    \"\"\"One JSON-mode chat call over a whole message list (system + history\n    + tool results). Returns (parsed object, \"\") or (None, reason) where\n    reason is not_configured | blocked | a short provider error. Gated by\n    the platform AI controls and recorded in the usage ledger.\"\"\"\n    config = runtime or assistant_runtime()\n    if not config.get(\"active\") or not config.get(\"api_key\"):\n        return None, \"not_configured\"\n    if _gated():\n        return None, \"blocked\"\n    model = str(config.get(\"model\") or MODEL)\n    targets = [{\"provider\": \"\", \"route\": \"\", \"model\": model,\n                \"api_key\": str(config[\"api_key\"]),\n                \"base_url\": str(config.get(\"base_url\") or BASE_URL).rstrip(\"/\")}]\n    # \u00a7229: the router's secondary provider covers an assistant outage\n    try:\n        import portal_model_router\n\n        backup = portal_model_router.failover_for(model)\n    except Exception:\n        backup = None\n    if backup and backup[\"api_key\"] != targets[0][\"api_key\"]:\n        targets.append(backup)\n    error = \"\"\n    for target in targets:\n        payload = {\n            \"model\": target[\"model\"],\n            \"messages\": messages,\n            \"temperature\": 0.2,\n            \"max_tokens\": int(max_tokens or 700),\n            \"response_format\": {\"type\": \"json_object\"},\n        }\n        headers = {\"Authorization\": \"Bearer \" + target[\"api_key\"],\n                   \"Content-Type\": \"application/json\"}\n        started = time.time()\n        body, error = _post_detail(target[\"base_url\"] + \"/chat/completions\",\n                                   headers, payload,\n                                   float(timeout or ASSISTANT_TIMEOUT_SECONDS))\n        usage = body.get(\"usage\") if isinstance(body, dict) else None\n        try:\n            parsed = json.loads(body[\"choices\"][0][\"message\"][\"content\"])\n        except Exception:\n            parsed = None\n        if isinstance(parsed, dict):\n            _record_routed(target[\"model\"], usage, True, started, target[\"route\"])\n            return parsed, \"\"\n        _record_routed(target[\"model\"], usage, False, started, target[\"route\"])\n        if isinstance(body, dict):\n            break  # the provider answered; not an outage\n    return None, error or \"unexpected response\"\n");
writeNewRepair("omniflow-backend-patch/portal_brain.py", "# \u00a7241 execution trace: the input's length only", false,
    "\"\"\"AI Brain v1 (V2 B6): tools, policy, grounding - with provenance.\n\nThe brain is the platform's first intent-driven agent layer. It sits in the\none-reply chain (B2) ahead of the KB gate and can answer inbound customer\nmessages by REASONING OVER TOOLS - all read-only in v1:\n\n  * recent_messages  - the last messages of this conversation;\n  * customer_orders  - the contact's recent checkout links (status/total);\n  * search_kb        - ranked knowledge: owner Q&A entries + published\n                     document sections (portal_knowledge.retrieve);\n  * customer_profile - stored language (tone matching).\n\nEvery decision is bounded (OF_BRAIN_MAX_TOOL_CALLS), grounded (the prompt\nmay only use tool output), policy-checked (no refund/discount/date\npromises, no internal jargon, length caps; violations force a handoff) and\naudited (a portal_brain_traces row + an ai.* portal_action_log entry).\n\nAutonomy per tenant (portal_brain_settings.autonomy):\n  off     - brain never runs (the rollback switch);\n  suggest - DEFAULT: the owner can ask for drafts via POST\n            /portal/brain/draft; the ingest path never fires;\n  auto    - the ingest hook may queue a reply itself when confidence >=\n            OF_BRAIN_MIN_CONFIDENCE and policy passes.\n\nv2 adds the STRUCTURED BUSINESS CONTEXT layer (the giant-prompt killer):\nthe owner stores policies / SOPs / pricing / refund + escalation rules as\nqueryable rows (portal_brain_facts) instead of pasting essays into the\nprompt. The reasoner queries them per message (tool_business_facts) and\ngrounds on them like any other tool; owners manage them via\nGET/POST/DELETE /portal/brain/facts and the Business facts card on\nConfigure AI.\n\nFail-soft everywhere: a missing LLM key, an outage or any db error makes\nthe brain step aside (None) and the B3 keyword path handles the message.\n\"\"\"\n\nimport json\nimport logging\nimport os\nimport sys\nimport time\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n)\n\nlogger = logging.getLogger(\"omniflow.portal-brain\")\n\nbp = Blueprint(\"portal_brain\", __name__, url_prefix=\"/api/v1/portal\")\n\nSETTINGS_TABLE = \"portal_brain_settings\"\nTRACES_TABLE = \"portal_brain_traces\"\n\nAUTONOMY_LEVELS = (\"off\", \"suggest\", \"auto\")\nMAX_TOOL_CALLS = int(os.environ.get(\"OF_BRAIN_MAX_TOOL_CALLS\", \"3\") or 3)\nMIN_CONFIDENCE = float(\n    os.environ.get(\"OF_BRAIN_MIN_CONFIDENCE\", \"0.6\") or 0.6)\nMAX_DRAFT_CHARS = int(os.environ.get(\"OF_BRAIN_MAX_DRAFT_CHARS\", \"700\") or 700)\nFACTS_TABLE = \"portal_brain_facts\"\nFACTS_LIMIT = int(os.environ.get(\"OF_BRAIN_FACTS_LIMIT\", \"100\") or 100)\nFACT_KINDS = (\"policy\", \"sop\", \"pricing\", \"refund\", \"escalation\", \"hours\")\n\n_DDL_READY = False\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_brain_settings (\n  client_id BIGINT PRIMARY KEY,\n  autonomy TEXT NOT NULL DEFAULT 'suggest',\n  tone TEXT NOT NULL DEFAULT '',\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE TABLE IF NOT EXISTS portal_brain_traces (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  conversation_id BIGINT,\n  kind TEXT NOT NULL DEFAULT 'draft',\n  decision TEXT NOT NULL DEFAULT 'handoff',\n  grounding JSONB NOT NULL DEFAULT '{}'::jsonb,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_brain_traces\n  ON portal_brain_traces (client_id, conversation_id, id DESC);\nCREATE TABLE IF NOT EXISTS portal_brain_facts (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  kind TEXT NOT NULL DEFAULT 'policy',\n  label TEXT NOT NULL DEFAULT '',\n  content TEXT NOT NULL DEFAULT '',\n  keywords TEXT NOT NULL DEFAULT '',\n  is_active BOOLEAN NOT NULL DEFAULT TRUE,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_brain_facts\n  ON portal_brain_facts (client_id, is_active, id DESC);\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    \"\"\"Create the brain tables once per process (lazy DDL). The knowledge\n    tables ride along so search_kb can join document chunks on a fresh\n    install before the owner ever opens the Knowledge page.\"\"\"\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    try:\n        import portal_knowledge\n\n        portal_knowledge._ensure_ddl(cur)\n    except Exception as error:  # pragma: no cover - fail-soft\n        logger.warning(\"knowledge DDL skipped: %s\", error)\n    try:\n        import portal_escalation\n\n        portal_escalation._ensure_ddl(cur)\n    except Exception as error:  # pragma: no cover - fail-soft\n        logger.warning(\"escalation DDL skipped: %s\", error)\n    try:\n        import portal_agents\n\n        portal_agents._ensure_ddl(cur)\n    except Exception as error:  # pragma: no cover - fail-soft\n        logger.warning(\"agents DDL skipped: %s\", error)\n    _DDL_READY = True\n\n\ndef _principal_or_error():\n    \"\"\"Owner/staff session required (API keys cannot touch the brain).\"\"\"\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    if principal.get(\"via_api_key\"):\n        return None, (jsonify({\"error\": {\"code\": \"forbidden\",\n                                         \"message\": \"Owner sign-in required.\"}}),\n                      403)\n    return principal, None\n\n\ndef _load_settings(cur, client_id: int) -> Dict[str, Any]:\n    cur.execute(\n        \"SELECT autonomy, tone FROM \" + portal_db._q(SETTINGS_TABLE) +\n        \" WHERE client_id = %s\",\n        (client_id,),\n    )\n    rows = portal_db.rows(cur)\n    if not rows:\n        return {\"autonomy\": \"suggest\", \"tone\": \"\"}\n    return {\"autonomy\": str(rows[0].get(\"autonomy\") or \"suggest\"),\n            \"tone\": str(rows[0].get(\"tone\") or \"\")}\n\n\nAUTONOMY_ORDER = {\"off\": 0, \"suggest\": 1, \"auto\": 2}\n\n\ndef platform_controls() -> Dict[str, Any]:\n    \"\"\"Platform AI controls (admin AI Control Center) - fail-soft copy of\n    platform_settings.ai_controls(): {kill_switch, autonomy_cap,\n    daily_call_cap, source}. Defaults never restrict anything.\"\"\"\n    try:\n        import platform_settings\n\n        controls = platform_settings.ai_controls()\n        if isinstance(controls, dict):\n            return controls\n    except Exception:\n        pass\n    return {\"kill_switch\": False, \"autonomy_cap\": \"auto\",\n            \"daily_call_cap\": 0, \"guard_mode\": \"standard\",\n            \"source\": \"default\"}\n\n\ndef effective_autonomy(own: str,\n                       controls: Optional[Dict[str, Any]] = None) -> str:\n    \"\"\"The autonomy the brain actually runs at: the workspace's own level\n    capped by the platform (kill switch = off; autonomy_cap = ceiling).\"\"\"\n    controls = controls if isinstance(controls, dict) else platform_controls()\n    own = own if own in AUTONOMY_ORDER else \"suggest\"\n    sandbox = sys.modules.get(\"portal_sandbox\")\n    if sandbox is not None:\n        # \u00a7230 \"Pretend AI is on Auto\": suggest -> auto only; caps still apply\n        own = sandbox.autonomy_override(own)\n    if controls.get(\"kill_switch\"):\n        return \"off\"\n    cap = str(controls.get(\"autonomy_cap\") or \"auto\")\n    if cap not in AUTONOMY_ORDER:\n        cap = \"auto\"\n    return own if AUTONOMY_ORDER[own] <= AUTONOMY_ORDER[cap] else cap\n\n\n# ---------------------------------------------------------------------------\n# Tools (read-only, tenant-scoped, budgeted)\n# ---------------------------------------------------------------------------\n\ndef tool_recent_messages(cur, client_id: int, conversation_id: int,\n                         n: int = 10) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT direction, body, created_at FROM \" +\n        portal_db._q(portal_db.MSGS_TABLE) +\n        \" WHERE client_id = %s AND conversation_id = %s\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (client_id, conversation_id, max(1, min(20, n))),\n    )\n    rows = portal_db.rows(cur)\n    return [{\"direction\": str(r.get(\"direction\") or \"\"),\n             \"body\": str(r.get(\"body\") or \"\")[:300],\n             \"created_at\": str(r.get(\"created_at\") or \"\")}\n            for r in reversed(rows)]\n\n\ndef tool_customer_orders(cur, client_id: int, contact_id: str,\n                         n: int = 3) -> List[Dict[str, Any]]:\n    if not str(contact_id or \"\").strip():\n        return []\n    cur.execute(\n        \"SELECT id, total, status, paid_amount, updated_at FROM \" +\n        portal_db._q(\"portal_checkout_links\") +\n        \" WHERE client_id = %s AND contact_id = %s\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (client_id, str(contact_id), max(1, min(10, n))),\n    )\n    rows = portal_db.rows(cur)\n    return [{\"id\": int(r.get(\"id\") or 0),\n             \"total\": float(r.get(\"total\") or 0),\n             \"status\": str(r.get(\"status\") or \"\"),\n             \"paid_amount\": float(r.get(\"paid_amount\") or 0),\n             \"updated_at\": str(r.get(\"updated_at\") or \"\")}\n            for r in rows]\n\n\ndef tool_search_kb(cur, client_id: int, query: str,\n                   n: int = 3) -> List[Dict[str, Any]]:\n    \"\"\"Knowledge for the answer: owner Q&A entries AND published document\n    sections (portal_knowledge.retrieve - one tenant-scoped query, ranked\n    by token relevance). Each hit carries kind/source/score so the trace\n    can cite where the answer came from.\"\"\"\n    text = str(query or \"\").strip()[:200]\n    if not text:\n        return []\n    try:\n        import portal_knowledge\n    except Exception:  # pragma: no cover - older deploy without the module\n        portal_knowledge = None\n    if portal_knowledge is None:\n        cur.execute(\n            \"SELECT id, title, content FROM \" + portal_db._q(\"portal_kb_entries\") +\n            \" WHERE client_id = %s AND is_active = TRUE\"\n            \" AND (title ILIKE %s OR content ILIKE %s OR keywords ILIKE %s)\"\n            \" ORDER BY id DESC LIMIT %s\",\n            (client_id, \"%\" + text + \"%\", \"%\" + text + \"%\", \"%\" + text + \"%\",\n             max(1, min(5, n))),\n        )\n        return [{\"id\": int(r.get(\"id\") or 0), \"kind\": \"entry\",\n                 \"title\": str(r.get(\"title\") or \"\"),\n                 \"content\": str(r.get(\"content\") or \"\")[:400],\n                 \"source\": \"\", \"score\": 0}\n                for r in portal_db.rows(cur)]\n    hits = portal_knowledge.retrieve(cur, client_id, text, max(1, min(5, n)))\n    return [{\"id\": h[\"id\"], \"kind\": h[\"kind\"], \"title\": h[\"title\"],\n             \"content\": h[\"content\"][:400], \"source\": h[\"source\"],\n             \"score\": h[\"score\"]}\n            for h in hits]\n\n\ndef tool_customer_profile(cur, client_id: int,\n                          contact_id: str) -> Dict[str, Any]:\n    language = None\n    try:\n        import portal_contacts\n\n        language = portal_contacts.stored_language(cur, client_id, contact_id)\n    except Exception:\n        language = None\n    return {\"language\": language}\n\n\ndef tool_business_facts(cur, client_id: int, query: str,\n                        n: int = 3) -> List[Dict[str, Any]]:\n    \"\"\"v2: query the tenant's structured business context (policies,\n    SOPs, pricing, refund/escalation rules, hours). Active rows only,\n    tenant-scoped, matched over label + content + keywords.\"\"\"\n    text = str(query or \"\").strip()[:120]\n    if not text:\n        return []\n    cur.execute(\n        \"SELECT id, kind, label, content FROM \" +\n        portal_db._q(FACTS_TABLE) +\n        \" WHERE client_id = %s AND is_active = TRUE\"\n        \" AND (label ILIKE %s OR content ILIKE %s OR keywords ILIKE %s)\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (client_id, \"%\" + text + \"%\", \"%\" + text + \"%\", \"%\" + text + \"%\",\n         max(1, min(5, n))),\n    )\n    rows = portal_db.rows(cur)\n    return [{\"id\": int(r.get(\"id\") or 0),\n             \"kind\": str(r.get(\"kind\") or \"policy\"),\n             \"label\": str(r.get(\"label\") or \"\"),\n             \"content\": str(r.get(\"content\") or \"\")[:400]}\n            for r in rows]\n\n\ndef tool_customer_memory(cur, client_id: int, contact_id: str,\n                         n: int = 3) -> List[Dict[str, Any]]:\n    \"\"\"Memory upgrade: read the customer's own memory rows (preferences,\n    notes, facts, journey position) - non-expired only, tenant-scoped,\n    read-only. Fail-soft: any problem means [] (the reply just loses\n    personalization, never breaks).\"\"\"\n    contact = str(contact_id or \"\").strip()\n    if not contact:\n        return []\n    try:\n        import portal_memory\n\n        cur.execute(\n            \"SELECT id, kind, mtype, content FROM \" +\n            portal_db._q(portal_memory.MEMORY_TABLE) +\n            \" WHERE client_id = %s AND contact_id = %s\"\n            \" AND (expires_at IS NULL OR expires_at > NOW())\"\n            \" ORDER BY id DESC LIMIT %s\",\n            (client_id, contact, max(1, min(5, n))),\n        )\n        rows = portal_db.rows(cur)\n        return [{\"id\": int(r.get(\"id\") or 0),\n                 \"kind\": str(r.get(\"kind\") or \"note\"),\n                 \"mtype\": str(r.get(\"mtype\") or \"long\"),\n                 \"content\": str(r.get(\"content\") or \"\")[:200]}\n                for r in rows]\n    except Exception:\n        return []\n\n\n# ---------------------------------------------------------------------------\n# Policy engine (deterministic post-checks)\n# ---------------------------------------------------------------------------\n\n_POLICY_FORBIDDEN = (\n    # refund / money promises\n    \"refund will\", \"will refund\", \"paise wapas\", \"money back\",\n    \"full refund\", \"100% refund\",\n    # discount promises\n    \"discount de\", \"extra discount\", \"special discount for you\",\n    \"i can give you a discount\", \"50% off\",\n    # delivery-date promises\n    \"guaranteed delivery\", \"pakka kal\", \"definitely tomorrow\",\n    # internal jargon / meta\n    \"system prompt\", \"as an ai\", \"language model\", \"database\",\n)\n\n_POLICY_MAX_NEWLINES = 8\n\n\ndef policy_check(text: str) -> List[str]:\n    \"\"\"Return the list of policy violations ([] = passes).\"\"\"\n    violations: List[str] = []\n    low = \" \" + \" \".join(str(text or \"\").lower().split()) + \" \"\n    for phrase in _POLICY_FORBIDDEN:\n        if phrase in low:\n            violations.append(\"forbidden:\" + phrase)\n    if len(str(text or \"\")) > MAX_DRAFT_CHARS:\n        violations.append(\"too_long\")\n    if str(text or \"\").count(\"\\n\") > _POLICY_MAX_NEWLINES:\n        violations.append(\"too_many_lines\")\n    return violations\n\n\n# ---------------------------------------------------------------------------\n# Reasoner: grounding + LLM + decision\n# ---------------------------------------------------------------------------\n\ndef _system_prompt(tone: str) -> str:\n    tone_line = (\"Write in this tone: \" + tone + \".\") if tone.strip() else \"\"\n    return (\n        \"You are the WhatsApp support agent of a Pakistani retail business. \"\n        \"Customers often write in Roman Urdu; reply in the customer's \"\n        \"language, short and friendly. You may ONLY use facts from the \"\n        \"provided CONTEXT - never invent orders, prices, dates or policies. \"\n        \"CONTEXT may include BUSINESS facts (policies, pricing, SOPs, \"\n        \"hours, refund and escalation rules); treat them as the owner's \"\n        \"own rules and follow them exactly. CONTEXT may include KB items: \"\n        \"owner-written answers (kind entry) and excerpts from the \"\n        \"business's own documents (kind chunk, with source); answer from \"\n        \"them and never go beyond what they say. CONTEXT may also include \"\n        \"MEMORY notes about THIS customer (preferences, past issues, \"\n        \"journey position); personalize using them. CONTEXT may include \"\n        \"an AGENT persona (name + instructions); when present, answer AS \"\n        \"that agent and follow its instructions. \"\n        \"NEVER promise refunds, discounts or delivery dates; NEVER mention \"\n        \"internal systems. If the context is insufficient or the customer \"\n        \"needs a human, set needs_human=true. \" + tone_line +\n        ' Reply ONLY with JSON: {\"reply\": \"...\", \"needs_human\": false, '\n        '\"confidence\": 0.0}' + _security_rules()\n    )\n\n\n#: D5 phone-call rules appended to the brain prompt for voice turns: the\n#: reply is read aloud by text-to-speech, so it must be short plain speech.\nVOICE_RULES = (\n    \" This is a LIVE PHONE CALL: your reply is read aloud by text-to-speech.\"\n    \" Use at most two short sentences of plain spoken words - no lists, no\"\n    \" links, no emoji, no symbols, no order codes read character by\"\n    \" character. CONTEXT may include call_transcript (earlier turns of this\"\n    \" call); stay consistent with it. If the caller wants a person, is\"\n    \" upset, or asks for anything you cannot answer from CONTEXT, set\"\n    \" needs_human=true.\"\n)\n\n\ndef _security_rules() -> str:\n    \"\"\"The override-proof trust-boundary block (portal_guard) appended to\n    every brain prompt. Fail-soft: an import problem never silences the\n    assistant, it only loses the extra block.\"\"\"\n    try:\n        import portal_guard\n\n        return portal_guard.SECURITY_RULES\n    except Exception:\n        return \"\"\n\n\ndef _reason(cur, client_id: int, conversation_id: int, contact_id: str,\n            contact_name: str, message_text: str,\n            tone: str, *, channel: str = \"\",\n            extra_context: Optional[Dict[str, Any]] = None,\n            usage_feature: str = \"brain\"\n            ) -> Tuple[Optional[Dict[str, Any]], Dict[str, Any]]:\n    \"\"\"Run the budgeted tools, then one LLM call.\n\n    Returns (llm_payload_or_None, grounding_dict). Never raises beyond\n    what the callers already guard. D5: ``channel=\"voice\"`` adds the\n    spoken-reply rules, ``extra_context`` (e.g. the live call transcript)\n    rides the same sanitised CONTEXT, ``usage_feature`` tags the ledger.\n    \"\"\"\n    started = time.time()\n    # \u00a7241 execution trace: the input's length only (the text stays in the\n    # messages table, so retention and deletes keep covering it)\n    grounding: Dict[str, Any] = {\"tools\": [],\n                                 \"input_chars\": len(str(message_text or \"\").strip())}\n    context: Dict[str, Any] = {}\n    calls = 0\n\n    # Trust boundary first (portal_guard): a message that tries to rewrite\n    # the assistant's instructions never reaches the tools or the model.\n    guard_mode = \"standard\"\n    try:\n        import portal_guard\n\n        guard = portal_guard.inspect(message_text)\n        guard_mode = portal_guard.mode()\n        grounding[\"guard\"] = dict(portal_guard.summary(guard),\n                                  mode=guard_mode)\n        if portal_guard.blocks(guard, guard_mode):\n            grounding[\"reason\"] = \"injection_suspected\"\n            grounding[\"llm_called\"] = False\n            return None, grounding\n    except Exception as error:\n        logger.warning(\"brain guard inspect failed: %s\", error)\n\n    def budget_left() -> bool:\n        return calls < MAX_TOOL_CALLS\n\n    context[\"conversation\"] = tool_recent_messages(cur, client_id,\n                                                   conversation_id, 10)\n    calls += 1\n    orders = tool_customer_orders(cur, client_id, contact_id, 3)\n    calls += 1\n    if orders:\n        context[\"orders\"] = orders\n        grounding[\"tools\"].append(\"customer_orders\")\n    kb = tool_search_kb(cur, client_id, message_text, 3)\n    calls += 1\n    if kb:\n        context[\"kb\"] = kb\n        grounding[\"tools\"].append(\"search_kb\")\n    facts = tool_business_facts(cur, client_id, message_text, 3)\n    calls += 1\n    if facts:\n        context[\"business\"] = facts\n        grounding[\"tools\"].append(\"business_facts\")\n    memories = tool_customer_memory(cur, client_id, contact_id, 3)\n    calls += 1\n    if memories:\n        context[\"memory\"] = memories\n        grounding[\"tools\"].append(\"customer_memory\")\n    agent = None\n    try:\n        import portal_agents\n\n        agent = portal_agents.agent_for_conversation(cur, client_id,\n                                                     conversation_id)\n    except Exception:\n        agent = None\n    calls += 1\n    if agent:\n        context[\"agent\"] = {\"name\": agent.get(\"name\"),\n                            \"instructions\":\n                            str(agent.get(\"instructions\") or \"\")[:400]}\n        grounding[\"tools\"].append(\"agent_persona\")\n        grounding[\"agent_id\"] = agent.get(\"id\")\n        grounding[\"agent_name\"] = str(agent.get(\"name\") or \"\")[:80]\n        in_hours = True\n        try:\n            import portal_agents as _agents_hours\n            in_hours = _agents_hours.agent_in_hours(agent) is not False\n        except Exception:\n            in_hours = True\n        grounding[\"agent_in_hours\"] = in_hours\n        grounding[\"agent_auto_reply\"] = (\n            agent.get(\"can_auto_reply\", True) is not False and in_hours\n        )\n        if str(agent.get(\"tone\") or \"\").strip():\n            tone = str(agent.get(\"tone\"))\n    profile = tool_customer_profile(cur, client_id, contact_id)\n    if profile.get(\"language\"):\n        context[\"language\"] = profile[\"language\"]\n        grounding[\"tools\"].append(\"customer_profile\")\n    sales = None\n    try:\n        import portal_sales\n        import portal_txn\n\n        # \u00a7237: qualifiers / concern + the owner's approved answer\n        with portal_txn.savepoint(cur, None, \"of_sales_ctx\"):\n            sales = portal_sales.context_for(cur, client_id, conversation_id,\n                                             contact_id, message_text)\n    except Exception as error:\n        logger.info(\"brain sales context skipped: %s\", error)\n        sales = None\n    if sales:\n        context[\"sales\"] = sales\n        grounding[\"tools\"].append(\"sales_context\")\n        grounding[\"sales\"] = {\n            \"stage\": sales.get(\"stage\"),\n            \"ask_next\": sales.get(\"ask_next\") or \"\",\n            \"objection\": (sales.get(\"objection\") or {}).get(\"kind\") or \"\",\n            \"approved_answer\": bool((sales.get(\"objection\") or {})\n                                    .get(\"approved_answer\")),\n        }\n    loyalty = None\n    try:\n        import portal_retention\n        import portal_txn\n\n        # \u00a7238: tier / past orders / favourite item (no offers, no codes)\n        with portal_txn.savepoint(cur, None, \"of_loyalty_ctx\"):\n            loyalty = portal_retention.context_for(cur, client_id, contact_id)\n    except Exception as error:\n        logger.info(\"brain loyalty context skipped: %s\", error)\n        loyalty = None\n    if loyalty:\n        context[\"loyalty\"] = loyalty\n        grounding[\"tools\"].append(\"loyalty_context\")\n        grounding[\"loyalty\"] = {\"tier\": loyalty.get(\"tier\") or \"\",\n                                \"orders\": loyalty.get(\"orders\") or 0}\n    grounding[\"conversation_messages\"] = len(context[\"conversation\"])\n    grounding[\"kb_ids\"] = [e[\"id\"] for e in kb if e.get(\"kind\", \"entry\") == \"entry\"]\n    grounding[\"knowledge_ids\"] = [e[\"id\"] for e in kb if e.get(\"kind\") == \"chunk\"]\n    grounding[\"citations\"] = [\n        {\"source\": e.get(\"source\") or \"\", \"section\": e.get(\"title\") or \"\",\n         \"score\": e.get(\"score\") or 0}\n        for e in kb if e.get(\"kind\") == \"chunk\"]\n    grounding[\"fact_ids\"] = [f[\"id\"] for f in facts]\n    grounding[\"memory_ids\"] = [m[\"id\"] for m in memories]\n    grounding[\"order_ids\"] = [o[\"id\"] for o in orders]\n    del budget_left\n\n    context[\"customer_name\"] = str(contact_name or \"\")\n    context[\"customer_message\"] = str(message_text or \"\")\n    if channel:\n        context[\"channel\"] = str(channel)[:20]\n        grounding[\"channel\"] = str(channel)[:20]\n    if isinstance(extra_context, dict):\n        for key, value in extra_context.items():\n            if key not in context:\n                context[str(key)[:40]] = value\n    try:\n        import portal_guard\n\n        context = portal_guard.sanitize_context(context)\n    except Exception:\n        pass\n\n    import portal_llm\n\n    _agent_id = 0\n    try:\n        if agent and agent.get(\"id\"):\n            _agent_id = int(agent.get(\"id\") or 0)\n    except Exception:\n        _agent_id = 0\n    system_prompt = _system_prompt(tone)\n    if channel == \"voice\":\n        system_prompt += VOICE_RULES\n    if \"sales\" in context:\n        try:\n            import portal_sales\n\n            system_prompt += portal_sales.SALES_RULES\n        except Exception:\n            pass\n    if \"loyalty\" in context:\n        try:\n            import portal_retention\n\n            system_prompt += portal_retention.LOYALTY_RULES\n        except Exception:\n            pass\n    model_started = time.time()\n    with portal_llm.usage_scope(usage_feature or \"brain\", client_id, cur,\n                                agent_id=_agent_id) as scope:\n        payload = portal_llm.chat_json(\n            system_prompt,\n            json.dumps(context, ensure_ascii=False, default=str),\n            max_tokens=300,\n        )\n    grounding[\"llm_called\"] = payload is not None\n    grounding[\"timings_ms\"] = {\n        \"tools\": int((model_started - started) * 1000),\n        \"model\": int((time.time() - model_started) * 1000)}\n    grounding[\"model_calls\"] = _scope_calls(scope)\n    if agent and str(agent.get(\"instructions\") or \"\").strip():\n        grounding[\"_private\"] = [str(agent.get(\"instructions\"))[:400]]\n    return payload, grounding\n\n\ndef _scope_calls(scope: Any) -> List[Dict[str, Any]]:\n    \"\"\"The LLM calls a usage_scope saw (model, tokens, latency, ok, route).\"\"\"\n    calls = getattr(scope, \"calls\", None)\n    return [dict(call) for call in calls if isinstance(call, dict)] \\\n        if isinstance(calls, list) else []\n\n\ndef _decide(payload: Optional[Dict[str, Any]],\n            grounding: Dict[str, Any]) -> Tuple[str, str, Dict[str, Any]]:\n    \"\"\"Map the LLM payload + policy to (decision, reply, grounding).\"\"\"\n    private = grounding.pop(\"_private\", None) or []\n    if grounding.get(\"reason\") == \"injection_suspected\":\n        return \"handoff\", \"\", grounding\n    if not isinstance(payload, dict):\n        grounding[\"reason\"] = \"llm_unavailable\"\n        return \"handoff\", \"\", grounding\n    try:\n        confidence = float(payload.get(\"confidence\") or 0)\n    except Exception:\n        confidence = 0\n    reply = str(payload.get(\"reply\") or \"\").strip()\n    needs_human = bool(payload.get(\"needs_human\"))\n    grounding[\"confidence\"] = confidence\n    if needs_human:\n        grounding[\"reason\"] = \"needs_human\"\n        return \"handoff\", \"\", grounding\n    if confidence < MIN_CONFIDENCE:\n        grounding[\"reason\"] = \"low_confidence\"\n        return \"handoff\", \"\", grounding\n    violations = policy_check(reply)\n    grounding[\"policy_violations\"] = violations\n    if violations:\n        grounding[\"reason\"] = \"policy:\" + violations[0]\n        return \"handoff\", \"\", grounding\n    leaks = _output_guard(reply, private)\n    if leaks:\n        grounding[\"output_violations\"] = leaks\n        grounding[\"reason\"] = \"output_guard:\" + leaks[0]\n        return \"handoff\", \"\", grounding\n    if not reply:\n        grounding[\"reason\"] = \"empty_reply\"\n        return \"handoff\", \"\", grounding\n    return \"send\", reply[:MAX_DRAFT_CHARS], grounding\n\n\ndef _output_guard(reply: str, private) -> List[str]:\n    \"\"\"Reply-side leak check (portal_guard.check_output); fail-open.\"\"\"\n    try:\n        import portal_guard\n\n        return portal_guard.check_output(reply, private)\n    except Exception:\n        return []\n\n\ndef _write_trace(cur, client_id: int, conversation_id: int, kind: str,\n                 decision: str, grounding: Dict[str, Any]) -> None:\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(TRACES_TABLE) +\n        \" (client_id, conversation_id, kind, decision, grounding)\"\n        \" VALUES (%s, %s, %s, %s, CAST(%s AS JSONB))\",\n        (client_id, conversation_id, kind, decision,\n         json.dumps(grounding, ensure_ascii=False, default=str)),\n    )\n\n\n# ---------------------------------------------------------------------------\n# Ingest hook (autonomy == auto only) + owner draft API\n# ---------------------------------------------------------------------------\n\ndef _record_guard_block(cur, client_id: int, conversation_id: int,\n                        grounding: Dict[str, Any], source: str) -> None:\n    \"\"\"Audit a blocked input/output without leaking its contents.\"\"\"\n    try:\n        import portal_guard\n\n        reason = str(grounding.get(\"reason\") or \"\")\n        result = grounding.get(\"guard\") or {}\n        if reason.startswith(\"output_guard:\"):\n            result = {\"score\": 0, \"level\": \"high\",\n                      \"signals\": [reason.split(\":\", 1)[1]]}\n        portal_guard.record_block(cur, client_id, conversation_id, result,\n                                  source, db=portal_db)\n    except Exception as error:\n        logger.warning(\"brain guard audit failed: %s\", error)\n\n\ndef _handoff(cur, client_id: int, conversation_id: int,\n             grounding: Dict[str, Any]) -> None:\n    \"\"\"A handoff decision under 'auto' autonomy is a real event, not a\n    silent trace: needs_human / low_confidence / policy blocks / suspected\n    prompt injection / output leaks open ONE escalation per conversation\n    (portal_escalation: assignee + bell + optional email). Platform problems\n    (llm_unavailable, empty_reply) are not customer situations and never page\n    the team. Never raises.\"\"\"\n    reason = str(grounding.get(\"reason\") or \"\")\n    if reason == \"injection_suspected\" or reason.startswith(\"output_guard:\"):\n        _record_guard_block(cur, client_id, conversation_id, grounding,\n                            \"brain\")\n    if not (reason in (\"needs_human\", \"low_confidence\", \"injection_suspected\")\n            or reason.startswith(\"policy:\")\n            or reason.startswith(\"output_guard:\")):\n        return\n    try:\n        import portal_escalation\n\n        confidence = grounding.get(\"confidence\")\n        note = \"AI handoff: \" + reason\n        if isinstance(confidence, (int, float)) and reason == \"low_confidence\":\n            note += \" (confidence \" + str(round(float(confidence), 2)) + \")\"\n        if reason == \"injection_suspected\":\n            note = (\"Suspicious message: the customer text tried to change \"\n                    \"the assistant's instructions (\" +\n                    \", \".join((grounding.get(\"guard\") or {}).get(\"signals\")\n                              or [])[:120] + \"). Please review and reply.\")\n        elif reason.startswith(\"output_guard:\"):\n            note = (\"The AI reply was withheld by the output guard (\" +\n                    reason.split(\":\", 1)[1] + \"). Please review and reply.\")\n        portal_escalation.escalate(cur, client_id, conversation_id, reason,\n                                   \"ai\", note=note)\n    except Exception as error:\n        logger.warning(\"brain handoff escalation failed: %s\", error)\n\n\ndef maybe_answer(client_id, conversation_id, contact_id, contact_name,\n                 body, conn) -> Optional[bool]:\n    \"\"\"Ingest hook: answer under 'auto' autonomy; return True when the\n    brain queued the reply (the one-reply law claims it as 'brain').\"\"\"\n    text = str(body or \"\").strip()\n    if not text:\n        return None\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            settings = _load_settings(cur, client_id)\n            if effective_autonomy(str(settings.get(\"autonomy\") or \"\")) \\\n                    != \"auto\":\n                return None\n            if str(contact_id or \"\").startswith((\"igc:\", \"fbc:\")):\n                # \u00a7228: a comment answer is PUBLIC - only when the owner\n                # turned on comment auto-reply (else it waits in the inbox)\n                import portal_instagram\n\n                if not portal_instagram.comment_auto_reply(cur, client_id):\n                    return None\n            payload, grounding = _reason(\n                cur, client_id, int(conversation_id or 0),\n                str(contact_id or \"\"), str(contact_name or \"\"), text,\n                str(settings.get(\"tone\") or \"\"))\n            decision, reply, grounding = _decide(payload, grounding)\n            if decision == \"send\" and grounding.get(\"agent_auto_reply\") \\\n                    is False:\n                # Persona permission: drafts only - the owner sends.\n                decision = \"handoff\"\n                grounding[\"reason\"] = \"agent_draft_only\"\n            _write_trace(cur, client_id, int(conversation_id or 0),\n                         \"ingest_answer\", decision, grounding)\n            if decision != \"send\":\n                _handoff(cur, client_id, int(conversation_id or 0), grounding)\n                return None\n            payload_out = {\n                \"external_user_id\": str(contact_id or \"\"),\n                \"body\": reply,\n                \"conversation_id\": conversation_id,\n                \"source\": \"ai_brain\",\n            }\n            if str(contact_name or \"\").strip():\n                payload_out[\"target_display_name\"] = str(contact_name)\n            import portal_channels\n\n            channel = portal_channels.channel_for_contact(contact_id)\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(portal_db.CMD_TABLE) +\n                \" (client_id, channel, action, payload, status,\"\n                \" requested_by, created_at, updated_at) \"\n                \"VALUES (%s, %s, 'send_message',\"\n                \" CAST(%s AS JSONB), 'pending', NULL, NOW(), NOW()) \"\n                \"RETURNING id\",\n                (client_id, channel, json.dumps(payload_out)),\n            )\n            portal_db.log_action(\n                cur, client_id, \"ai.answer\", \"automation\",\n                None, conversation_id,\n                \"Brain answered (tools: \" +\n                \",\".join(grounding.get(\"tools\") or [\"none\"]) + \").\",\n            )\n            return True\n    except Exception as error:\n        logger.warning(\"brain maybe_answer failed: %s\", error)\n        return None\n\n\ndef voice_answer(cur, client_id: int, conversation_id: int, contact_id: str,\n                 contact_name: str, utterance: str,\n                 transcript: Optional[List[Dict[str, str]]] = None\n                 ) -> Tuple[str, str, Dict[str, Any]]:\n    \"\"\"D5 phone AI turn: the same guard -> tools -> one LLM call ->\n    policy/output-guard pipeline as a chat answer, with spoken-reply rules.\n\n    Returns (decision \"send\"|\"handoff\", reply, grounding). The caller\n    (portal_voice) owns the TwiML; this writes the trace and, on a real\n    handoff, opens the usual escalation. Voice never runs below 'auto'\n    autonomy or for a draft-only persona. Never raises.\n    \"\"\"\n    grounding: Dict[str, Any] = {\"channel\": \"voice\"}\n    try:\n        _ensure_ddl(cur)\n        settings = _load_settings(cur, client_id)\n        if effective_autonomy(str(settings.get(\"autonomy\") or \"\")) != \"auto\":\n            grounding[\"reason\"] = \"autonomy_not_auto\"\n            return \"handoff\", \"\", grounding\n        extra = {}\n        if transcript:\n            extra[\"call_transcript\"] = [\n                {\"role\": str(turn.get(\"role\") or \"\")[:10],\n                 \"text\": str(turn.get(\"text\") or \"\")[:300]}\n                for turn in transcript[-8:] if isinstance(turn, dict)]\n        payload, grounding = _reason(\n            cur, client_id, int(conversation_id or 0), str(contact_id or \"\"),\n            str(contact_name or \"\"), str(utterance or \"\"),\n            str(settings.get(\"tone\") or \"\"), channel=\"voice\",\n            extra_context=extra, usage_feature=\"voice_call\")\n        decision, reply, grounding = _decide(payload, grounding)\n        if decision == \"send\" and grounding.get(\"agent_auto_reply\") is False:\n            decision = \"handoff\"\n            grounding[\"reason\"] = \"agent_draft_only\"\n        _write_trace(cur, client_id, int(conversation_id or 0),\n                     \"voice_answer\", decision, grounding)\n        if decision != \"send\":\n            if int(conversation_id or 0) > 0:\n                _handoff(cur, client_id, int(conversation_id), grounding)\n            elif str(grounding.get(\"reason\") or \"\") == \"injection_suspected\":\n                _record_guard_block(cur, client_id, 0, grounding, \"voice\")\n            return \"handoff\", \"\", grounding\n        return \"send\", reply, grounding\n    except Exception as error:\n        logger.warning(\"brain voice_answer failed: %s\", error)\n        grounding[\"reason\"] = \"error\"\n        return \"handoff\", \"\", grounding\n\n\ndef draft_reply(cur, client_id: int, conversation_id: int,\n                message_text: str = \"\") -> Dict[str, Any]:\n    \"\"\"Owner-facing draft (autonomy 'suggest'): never queues a send.\"\"\"\n    _ensure_ddl(cur)\n    settings = _load_settings(cur, client_id)\n    payload, grounding = _reason(\n        cur, client_id, conversation_id, \"\", \"\", message_text,\n        str(settings.get(\"tone\") or \"\"))\n    decision, reply, grounding = _decide(payload, grounding)\n    if (str(grounding.get(\"reason\") or \"\") == \"injection_suspected\"\n            or str(grounding.get(\"reason\") or \"\").startswith(\"output_guard:\")):\n        _record_guard_block(cur, client_id, conversation_id, grounding,\n                            \"brain_draft\")\n    _write_trace(cur, client_id, conversation_id, \"draft\", decision,\n                 grounding)\n    portal_db.log_action(\n        cur, client_id, \"ai.draft\", \"human\",\n        None, conversation_id,\n        \"Brain draft requested (\" + decision + \").\",\n    )\n    result = {\"decision\": decision,\n              \"draft\": reply,\n              \"grounding\": grounding,\n              \"autonomy\": settings.get(\"autonomy\")}\n    # KB auto-draft (owner decision, admin panel): when on, a draft also\n    # ships a saveable knowledge-base entry so good answers stop being\n    # one-offs. Fail-soft: the plain draft is always there.\n    try:\n        import platform_settings\n        if platform_settings.flag(\"kb_autodraft\") and reply:\n            result[\"kb_entry\"] = {\n                \"title\": (message_text or \"\").strip()[:120]\n                         or \"Saved answer\",\n                \"content\": str(reply),\n            }\n    except Exception:\n        pass\n    return result\n\n\n# ---------------------------------------------------------------------------\n# Owner API: settings / draft / trace\n# ---------------------------------------------------------------------------\n\n@bp.get(\"/brain/settings\")\ndef get_brain_settings():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            settings = _load_settings(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    controls = platform_controls()\n    settings[\"platform\"] = {\n        \"paused\": bool(controls.get(\"kill_switch\")),\n        \"autonomy_cap\": str(controls.get(\"autonomy_cap\") or \"auto\"),\n        \"daily_call_cap\": int(controls.get(\"daily_call_cap\") or 0),\n        \"guard_mode\": str(controls.get(\"guard_mode\") or \"standard\"),\n        \"effective_autonomy\": effective_autonomy(\n            str(settings.get(\"autonomy\") or \"\"), controls),\n    }\n    return jsonify({\"settings\": settings}), 200\n\n\n@bp.put(\"/brain/settings\")\ndef put_brain_settings():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    autonomy = payload.get(\"autonomy\")\n    tone = payload.get(\"tone\")\n    if autonomy not in AUTONOMY_LEVELS:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"autonomy must be one of off|suggest|auto.\",\n        }}), 400\n    if tone is not None and not isinstance(tone, str):\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"tone must be a string.\",\n        }}), 400\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            try:\n                import portal_snapshots\n\n                portal_snapshots.before_change(\n                    cur, client_id, \"brain\",\n                    str(principal.get(\"email\") or principal.get(\"user_id\") or \"\"))\n            except Exception:\n                pass\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(SETTINGS_TABLE) +\n                \" (client_id, autonomy, tone, updated_at)\"\n                \" VALUES (%s, %s, %s, NOW())\"\n                \" ON CONFLICT (client_id) DO UPDATE SET\"\n                \" autonomy = EXCLUDED.autonomy,\"\n                \" tone = EXCLUDED.tone, updated_at = NOW()\",\n                (client_id, autonomy, str(tone or \"\")[:200]),\n            )\n            portal_db.log_action(\n                cur, client_id, \"ai.settings\", \"human\",\n                None, None,\n                \"Brain autonomy set to \" + str(autonomy) + \".\",\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"settings\": {\"autonomy\": autonomy,\n                                 \"tone\": str(tone or \"\")}}), 200\n\n\n@bp.post(\"/brain/draft\")\ndef draft_brain_reply():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    try:\n        conversation_id = int(payload.get(\"conversation_id\") or 0)\n    except Exception:\n        conversation_id = 0\n    if conversation_id <= 0:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"conversation_id (positive integer) is required.\",\n        }}), 400\n    message_text = str(payload.get(\"message\") or \"\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"SELECT 1 FROM \" + portal_db._q(portal_db.CONV_TABLE) +\n                \" WHERE id = %s AND client_id = %s LIMIT 1\",\n                (conversation_id, client_id),\n            )\n            if not portal_db.rows(cur):\n                conn.rollback()\n                return jsonify({\"error\": {\n                    \"code\": \"not_found\",\n                    \"message\": \"No such conversation in this workspace.\",\n                }}), 404\n            result = draft_reply(cur, client_id, conversation_id,\n                                 message_text)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify(result), 200\n\n\n@bp.get(\"/brain/trace\")\ndef list_brain_traces():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    try:\n        conversation_id = int(request.args.get(\"conversation_id\") or 0)\n    except Exception:\n        conversation_id = 0\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            sql = (\"SELECT id, conversation_id, kind, decision, grounding,\"\n                   \" created_at FROM \" + portal_db._q(TRACES_TABLE) +\n                   \" WHERE client_id = %s\")\n            params: Tuple[Any, ...] = (client_id,)\n            if conversation_id > 0:\n                sql += \" AND conversation_id = %s\"\n                params = (client_id, conversation_id)\n            sql += \" ORDER BY id DESC LIMIT 10\"\n            cur.execute(sql, params)\n            rows = portal_db.rows(cur)\n        conn.commit()\n    finally:\n        conn.close()\n    out = [{\"id\": int(r.get(\"id\") or 0),\n            \"conversation_id\": r.get(\"conversation_id\"),\n            \"kind\": str(r.get(\"kind\") or \"\"),\n            \"decision\": str(r.get(\"decision\") or \"\"),\n            \"grounding\": r.get(\"grounding\"),\n            \"created_at\": str(r.get(\"created_at\") or \"\")}\n           for r in rows]\n    return jsonify({\"traces\": out}), 200\n\n\n# ---------------------------------------------------------------------------\n# v2: structured business context (facts) - owner CRUD\n# ---------------------------------------------------------------------------\n\ndef _shape_fact(row: Dict[str, Any]) -> Dict[str, Any]:\n    return {\"id\": int(row.get(\"id\") or 0),\n            \"kind\": str(row.get(\"kind\") or \"policy\"),\n            \"label\": str(row.get(\"label\") or \"\"),\n            \"content\": str(row.get(\"content\") or \"\"),\n            \"keywords\": str(row.get(\"keywords\") or \"\"),\n            \"is_active\": bool(row.get(\"is_active\")),\n            \"updated_at\": str(row.get(\"updated_at\") or \"\")}\n\n\n@bp.get(\"/brain/facts\")\ndef list_brain_facts():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"SELECT id, kind, label, content, keywords, is_active,\"\n                \" updated_at FROM \" + portal_db._q(FACTS_TABLE) +\n                \" WHERE client_id = %s\"\n                \" ORDER BY is_active DESC, id DESC LIMIT %s\",\n                (client_id, max(1, min(500, FACTS_LIMIT))),\n            )\n            rows = portal_db.rows(cur)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"facts\": [_shape_fact(r) for r in rows]}), 200\n\n\n@bp.post(\"/brain/facts\")\ndef save_brain_fact():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    fact_id = 0\n    try:\n        fact_id = int(payload.get(\"id\") or 0)\n    except Exception:\n        fact_id = 0\n    kind = str(payload.get(\"kind\") or \"policy\")\n    label = str(payload.get(\"label\") or \"\").strip()\n    content = str(payload.get(\"content\") or \"\").strip()\n    keywords = str(payload.get(\"keywords\") or \"\").strip()\n    is_active = payload.get(\"is_active\", True)\n    if not isinstance(is_active, bool):\n        is_active = bool(is_active)\n    if kind not in FACT_KINDS:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"kind must be one of \" + \"|\".join(FACT_KINDS) + \".\",\n        }}), 400\n    if not label or len(label) > 120:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"label is required (max 120 characters).\",\n        }}), 400\n    if not content or len(content) > 2000:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"content is required (max 2000 characters).\",\n        }}), 400\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            try:\n                import portal_snapshots\n\n                portal_snapshots.before_change(\n                    cur, client_id, \"brain_facts\",\n                    str(principal.get(\"email\") or principal.get(\"user_id\") or \"\"))\n            except Exception:\n                pass\n            if fact_id > 0:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(FACTS_TABLE) +\n                    \" SET kind = %s, label = %s, content = %s,\"\n                    \" keywords = %s, is_active = %s, updated_at = NOW()\"\n                    \" WHERE id = %s AND client_id = %s RETURNING id\",\n                    (kind, label[:120], content[:2000], keywords[:200],\n                     is_active, fact_id, client_id),\n                )\n                rows = portal_db.rows(cur)\n                if not rows:\n                    conn.rollback()\n                    return jsonify({\"error\": {\n                        \"code\": \"not_found\",\n                        \"message\": \"No such fact in this workspace.\",\n                    }}), 404\n                action = \"updated\"\n            else:\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(FACTS_TABLE) +\n                    \" (client_id, kind, label, content, keywords,\"\n                    \" is_active, updated_at)\"\n                    \" VALUES (%s, %s, %s, %s, %s, %s, NOW())\"\n                    \" RETURNING id\",\n                    (client_id, kind, label[:120], content[:2000],\n                     keywords[:200], is_active),\n                )\n                rows = portal_db.rows(cur)\n                action = \"created\"\n            portal_db.log_action(\n                cur, client_id, \"brain.facts\", \"human\",\n                None, None,\n                \"Business fact \" + action + \": \" + label[:80] + \".\",\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"fact\": {\"id\": int(rows[0].get(\"id\") or 0),\n                             \"kind\": kind, \"label\": label,\n                             \"content\": content, \"keywords\": keywords,\n                             \"is_active\": is_active}}), 200\n\n\n@bp.delete(\"/brain/facts\")\ndef delete_brain_fact():\n    \"\"\"Soft delete (data-preserving): the row just goes inactive and the\n    owner can re-activate it from the same card.\"\"\"\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    try:\n        fact_id = int(request.args.get(\"id\") or 0)\n    except Exception:\n        fact_id = 0\n    if fact_id <= 0:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"id (positive integer) is required.\",\n        }}), 400\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            try:\n                import portal_snapshots\n\n                portal_snapshots.before_change(\n                    cur, client_id, \"brain_facts\",\n                    str(principal.get(\"email\") or principal.get(\"user_id\") or \"\"))\n            except Exception:\n                pass\n            cur.execute(\n                \"UPDATE \" + portal_db._q(FACTS_TABLE) +\n                \" SET is_active = FALSE, updated_at = NOW()\"\n                \" WHERE id = %s AND client_id = %s RETURNING id\",\n                (fact_id, client_id),\n            )\n            rows = portal_db.rows(cur)\n            if not rows:\n                conn.rollback()\n                return jsonify({\"error\": {\n                    \"code\": \"not_found\",\n                    \"message\": \"No such fact in this workspace.\",\n                }}), 404\n            portal_db.log_action(\n                cur, client_id, \"brain.facts\", \"human\",\n                None, None,\n                \"Business fact archived (id \" + str(fact_id) + \").\",\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True}), 200\n");
writeNewRepair("OmniFlow-Control-Plane/portal_brain.py", "# \u00a7241 execution trace: the input's length only", true,
    "\"\"\"AI Brain v1 (V2 B6): tools, policy, grounding - with provenance.\n\nThe brain is the platform's first intent-driven agent layer. It sits in the\none-reply chain (B2) ahead of the KB gate and can answer inbound customer\nmessages by REASONING OVER TOOLS - all read-only in v1:\n\n  * recent_messages  - the last messages of this conversation;\n  * customer_orders  - the contact's recent checkout links (status/total);\n  * search_kb        - ranked knowledge: owner Q&A entries + published\n                     document sections (portal_knowledge.retrieve);\n  * customer_profile - stored language (tone matching).\n\nEvery decision is bounded (OF_BRAIN_MAX_TOOL_CALLS), grounded (the prompt\nmay only use tool output), policy-checked (no refund/discount/date\npromises, no internal jargon, length caps; violations force a handoff) and\naudited (a portal_brain_traces row + an ai.* portal_action_log entry).\n\nAutonomy per tenant (portal_brain_settings.autonomy):\n  off     - brain never runs (the rollback switch);\n  suggest - DEFAULT: the owner can ask for drafts via POST\n            /portal/brain/draft; the ingest path never fires;\n  auto    - the ingest hook may queue a reply itself when confidence >=\n            OF_BRAIN_MIN_CONFIDENCE and policy passes.\n\nv2 adds the STRUCTURED BUSINESS CONTEXT layer (the giant-prompt killer):\nthe owner stores policies / SOPs / pricing / refund + escalation rules as\nqueryable rows (portal_brain_facts) instead of pasting essays into the\nprompt. The reasoner queries them per message (tool_business_facts) and\ngrounds on them like any other tool; owners manage them via\nGET/POST/DELETE /portal/brain/facts and the Business facts card on\nConfigure AI.\n\nFail-soft everywhere: a missing LLM key, an outage or any db error makes\nthe brain step aside (None) and the B3 keyword path handles the message.\n\"\"\"\n\nimport json\nimport logging\nimport os\nimport sys\nimport time\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n)\n\nlogger = logging.getLogger(\"omniflow.portal-brain\")\n\nbp = Blueprint(\"portal_brain\", __name__, url_prefix=\"/api/v1/portal\")\n\nSETTINGS_TABLE = \"portal_brain_settings\"\nTRACES_TABLE = \"portal_brain_traces\"\n\nAUTONOMY_LEVELS = (\"off\", \"suggest\", \"auto\")\nMAX_TOOL_CALLS = int(os.environ.get(\"OF_BRAIN_MAX_TOOL_CALLS\", \"3\") or 3)\nMIN_CONFIDENCE = float(\n    os.environ.get(\"OF_BRAIN_MIN_CONFIDENCE\", \"0.6\") or 0.6)\nMAX_DRAFT_CHARS = int(os.environ.get(\"OF_BRAIN_MAX_DRAFT_CHARS\", \"700\") or 700)\nFACTS_TABLE = \"portal_brain_facts\"\nFACTS_LIMIT = int(os.environ.get(\"OF_BRAIN_FACTS_LIMIT\", \"100\") or 100)\nFACT_KINDS = (\"policy\", \"sop\", \"pricing\", \"refund\", \"escalation\", \"hours\")\n\n_DDL_READY = False\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_brain_settings (\n  client_id BIGINT PRIMARY KEY,\n  autonomy TEXT NOT NULL DEFAULT 'suggest',\n  tone TEXT NOT NULL DEFAULT '',\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE TABLE IF NOT EXISTS portal_brain_traces (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  conversation_id BIGINT,\n  kind TEXT NOT NULL DEFAULT 'draft',\n  decision TEXT NOT NULL DEFAULT 'handoff',\n  grounding JSONB NOT NULL DEFAULT '{}'::jsonb,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_brain_traces\n  ON portal_brain_traces (client_id, conversation_id, id DESC);\nCREATE TABLE IF NOT EXISTS portal_brain_facts (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  kind TEXT NOT NULL DEFAULT 'policy',\n  label TEXT NOT NULL DEFAULT '',\n  content TEXT NOT NULL DEFAULT '',\n  keywords TEXT NOT NULL DEFAULT '',\n  is_active BOOLEAN NOT NULL DEFAULT TRUE,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_brain_facts\n  ON portal_brain_facts (client_id, is_active, id DESC);\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    \"\"\"Create the brain tables once per process (lazy DDL). The knowledge\n    tables ride along so search_kb can join document chunks on a fresh\n    install before the owner ever opens the Knowledge page.\"\"\"\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    try:\n        import portal_knowledge\n\n        portal_knowledge._ensure_ddl(cur)\n    except Exception as error:  # pragma: no cover - fail-soft\n        logger.warning(\"knowledge DDL skipped: %s\", error)\n    try:\n        import portal_escalation\n\n        portal_escalation._ensure_ddl(cur)\n    except Exception as error:  # pragma: no cover - fail-soft\n        logger.warning(\"escalation DDL skipped: %s\", error)\n    try:\n        import portal_agents\n\n        portal_agents._ensure_ddl(cur)\n    except Exception as error:  # pragma: no cover - fail-soft\n        logger.warning(\"agents DDL skipped: %s\", error)\n    _DDL_READY = True\n\n\ndef _principal_or_error():\n    \"\"\"Owner/staff session required (API keys cannot touch the brain).\"\"\"\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    if principal.get(\"via_api_key\"):\n        return None, (jsonify({\"error\": {\"code\": \"forbidden\",\n                                         \"message\": \"Owner sign-in required.\"}}),\n                      403)\n    return principal, None\n\n\ndef _load_settings(cur, client_id: int) -> Dict[str, Any]:\n    cur.execute(\n        \"SELECT autonomy, tone FROM \" + portal_db._q(SETTINGS_TABLE) +\n        \" WHERE client_id = %s\",\n        (client_id,),\n    )\n    rows = portal_db.rows(cur)\n    if not rows:\n        return {\"autonomy\": \"suggest\", \"tone\": \"\"}\n    return {\"autonomy\": str(rows[0].get(\"autonomy\") or \"suggest\"),\n            \"tone\": str(rows[0].get(\"tone\") or \"\")}\n\n\nAUTONOMY_ORDER = {\"off\": 0, \"suggest\": 1, \"auto\": 2}\n\n\ndef platform_controls() -> Dict[str, Any]:\n    \"\"\"Platform AI controls (admin AI Control Center) - fail-soft copy of\n    platform_settings.ai_controls(): {kill_switch, autonomy_cap,\n    daily_call_cap, source}. Defaults never restrict anything.\"\"\"\n    try:\n        import platform_settings\n\n        controls = platform_settings.ai_controls()\n        if isinstance(controls, dict):\n            return controls\n    except Exception:\n        pass\n    return {\"kill_switch\": False, \"autonomy_cap\": \"auto\",\n            \"daily_call_cap\": 0, \"guard_mode\": \"standard\",\n            \"source\": \"default\"}\n\n\ndef effective_autonomy(own: str,\n                       controls: Optional[Dict[str, Any]] = None) -> str:\n    \"\"\"The autonomy the brain actually runs at: the workspace's own level\n    capped by the platform (kill switch = off; autonomy_cap = ceiling).\"\"\"\n    controls = controls if isinstance(controls, dict) else platform_controls()\n    own = own if own in AUTONOMY_ORDER else \"suggest\"\n    sandbox = sys.modules.get(\"portal_sandbox\")\n    if sandbox is not None:\n        # \u00a7230 \"Pretend AI is on Auto\": suggest -> auto only; caps still apply\n        own = sandbox.autonomy_override(own)\n    if controls.get(\"kill_switch\"):\n        return \"off\"\n    cap = str(controls.get(\"autonomy_cap\") or \"auto\")\n    if cap not in AUTONOMY_ORDER:\n        cap = \"auto\"\n    return own if AUTONOMY_ORDER[own] <= AUTONOMY_ORDER[cap] else cap\n\n\n# ---------------------------------------------------------------------------\n# Tools (read-only, tenant-scoped, budgeted)\n# ---------------------------------------------------------------------------\n\ndef tool_recent_messages(cur, client_id: int, conversation_id: int,\n                         n: int = 10) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT direction, body, created_at FROM \" +\n        portal_db._q(portal_db.MSGS_TABLE) +\n        \" WHERE client_id = %s AND conversation_id = %s\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (client_id, conversation_id, max(1, min(20, n))),\n    )\n    rows = portal_db.rows(cur)\n    return [{\"direction\": str(r.get(\"direction\") or \"\"),\n             \"body\": str(r.get(\"body\") or \"\")[:300],\n             \"created_at\": str(r.get(\"created_at\") or \"\")}\n            for r in reversed(rows)]\n\n\ndef tool_customer_orders(cur, client_id: int, contact_id: str,\n                         n: int = 3) -> List[Dict[str, Any]]:\n    if not str(contact_id or \"\").strip():\n        return []\n    cur.execute(\n        \"SELECT id, total, status, paid_amount, updated_at FROM \" +\n        portal_db._q(\"portal_checkout_links\") +\n        \" WHERE client_id = %s AND contact_id = %s\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (client_id, str(contact_id), max(1, min(10, n))),\n    )\n    rows = portal_db.rows(cur)\n    return [{\"id\": int(r.get(\"id\") or 0),\n             \"total\": float(r.get(\"total\") or 0),\n             \"status\": str(r.get(\"status\") or \"\"),\n             \"paid_amount\": float(r.get(\"paid_amount\") or 0),\n             \"updated_at\": str(r.get(\"updated_at\") or \"\")}\n            for r in rows]\n\n\ndef tool_search_kb(cur, client_id: int, query: str,\n                   n: int = 3) -> List[Dict[str, Any]]:\n    \"\"\"Knowledge for the answer: owner Q&A entries AND published document\n    sections (portal_knowledge.retrieve - one tenant-scoped query, ranked\n    by token relevance). Each hit carries kind/source/score so the trace\n    can cite where the answer came from.\"\"\"\n    text = str(query or \"\").strip()[:200]\n    if not text:\n        return []\n    try:\n        import portal_knowledge\n    except Exception:  # pragma: no cover - older deploy without the module\n        portal_knowledge = None\n    if portal_knowledge is None:\n        cur.execute(\n            \"SELECT id, title, content FROM \" + portal_db._q(\"portal_kb_entries\") +\n            \" WHERE client_id = %s AND is_active = TRUE\"\n            \" AND (title ILIKE %s OR content ILIKE %s OR keywords ILIKE %s)\"\n            \" ORDER BY id DESC LIMIT %s\",\n            (client_id, \"%\" + text + \"%\", \"%\" + text + \"%\", \"%\" + text + \"%\",\n             max(1, min(5, n))),\n        )\n        return [{\"id\": int(r.get(\"id\") or 0), \"kind\": \"entry\",\n                 \"title\": str(r.get(\"title\") or \"\"),\n                 \"content\": str(r.get(\"content\") or \"\")[:400],\n                 \"source\": \"\", \"score\": 0}\n                for r in portal_db.rows(cur)]\n    hits = portal_knowledge.retrieve(cur, client_id, text, max(1, min(5, n)))\n    return [{\"id\": h[\"id\"], \"kind\": h[\"kind\"], \"title\": h[\"title\"],\n             \"content\": h[\"content\"][:400], \"source\": h[\"source\"],\n             \"score\": h[\"score\"]}\n            for h in hits]\n\n\ndef tool_customer_profile(cur, client_id: int,\n                          contact_id: str) -> Dict[str, Any]:\n    language = None\n    try:\n        import portal_contacts\n\n        language = portal_contacts.stored_language(cur, client_id, contact_id)\n    except Exception:\n        language = None\n    return {\"language\": language}\n\n\ndef tool_business_facts(cur, client_id: int, query: str,\n                        n: int = 3) -> List[Dict[str, Any]]:\n    \"\"\"v2: query the tenant's structured business context (policies,\n    SOPs, pricing, refund/escalation rules, hours). Active rows only,\n    tenant-scoped, matched over label + content + keywords.\"\"\"\n    text = str(query or \"\").strip()[:120]\n    if not text:\n        return []\n    cur.execute(\n        \"SELECT id, kind, label, content FROM \" +\n        portal_db._q(FACTS_TABLE) +\n        \" WHERE client_id = %s AND is_active = TRUE\"\n        \" AND (label ILIKE %s OR content ILIKE %s OR keywords ILIKE %s)\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (client_id, \"%\" + text + \"%\", \"%\" + text + \"%\", \"%\" + text + \"%\",\n         max(1, min(5, n))),\n    )\n    rows = portal_db.rows(cur)\n    return [{\"id\": int(r.get(\"id\") or 0),\n             \"kind\": str(r.get(\"kind\") or \"policy\"),\n             \"label\": str(r.get(\"label\") or \"\"),\n             \"content\": str(r.get(\"content\") or \"\")[:400]}\n            for r in rows]\n\n\ndef tool_customer_memory(cur, client_id: int, contact_id: str,\n                         n: int = 3) -> List[Dict[str, Any]]:\n    \"\"\"Memory upgrade: read the customer's own memory rows (preferences,\n    notes, facts, journey position) - non-expired only, tenant-scoped,\n    read-only. Fail-soft: any problem means [] (the reply just loses\n    personalization, never breaks).\"\"\"\n    contact = str(contact_id or \"\").strip()\n    if not contact:\n        return []\n    try:\n        import portal_memory\n\n        cur.execute(\n            \"SELECT id, kind, mtype, content FROM \" +\n            portal_db._q(portal_memory.MEMORY_TABLE) +\n            \" WHERE client_id = %s AND contact_id = %s\"\n            \" AND (expires_at IS NULL OR expires_at > NOW())\"\n            \" ORDER BY id DESC LIMIT %s\",\n            (client_id, contact, max(1, min(5, n))),\n        )\n        rows = portal_db.rows(cur)\n        return [{\"id\": int(r.get(\"id\") or 0),\n                 \"kind\": str(r.get(\"kind\") or \"note\"),\n                 \"mtype\": str(r.get(\"mtype\") or \"long\"),\n                 \"content\": str(r.get(\"content\") or \"\")[:200]}\n                for r in rows]\n    except Exception:\n        return []\n\n\n# ---------------------------------------------------------------------------\n# Policy engine (deterministic post-checks)\n# ---------------------------------------------------------------------------\n\n_POLICY_FORBIDDEN = (\n    # refund / money promises\n    \"refund will\", \"will refund\", \"paise wapas\", \"money back\",\n    \"full refund\", \"100% refund\",\n    # discount promises\n    \"discount de\", \"extra discount\", \"special discount for you\",\n    \"i can give you a discount\", \"50% off\",\n    # delivery-date promises\n    \"guaranteed delivery\", \"pakka kal\", \"definitely tomorrow\",\n    # internal jargon / meta\n    \"system prompt\", \"as an ai\", \"language model\", \"database\",\n)\n\n_POLICY_MAX_NEWLINES = 8\n\n\ndef policy_check(text: str) -> List[str]:\n    \"\"\"Return the list of policy violations ([] = passes).\"\"\"\n    violations: List[str] = []\n    low = \" \" + \" \".join(str(text or \"\").lower().split()) + \" \"\n    for phrase in _POLICY_FORBIDDEN:\n        if phrase in low:\n            violations.append(\"forbidden:\" + phrase)\n    if len(str(text or \"\")) > MAX_DRAFT_CHARS:\n        violations.append(\"too_long\")\n    if str(text or \"\").count(\"\\n\") > _POLICY_MAX_NEWLINES:\n        violations.append(\"too_many_lines\")\n    return violations\n\n\n# ---------------------------------------------------------------------------\n# Reasoner: grounding + LLM + decision\n# ---------------------------------------------------------------------------\n\ndef _system_prompt(tone: str) -> str:\n    tone_line = (\"Write in this tone: \" + tone + \".\") if tone.strip() else \"\"\n    return (\n        \"You are the WhatsApp support agent of a Pakistani retail business. \"\n        \"Customers often write in Roman Urdu; reply in the customer's \"\n        \"language, short and friendly. You may ONLY use facts from the \"\n        \"provided CONTEXT - never invent orders, prices, dates or policies. \"\n        \"CONTEXT may include BUSINESS facts (policies, pricing, SOPs, \"\n        \"hours, refund and escalation rules); treat them as the owner's \"\n        \"own rules and follow them exactly. CONTEXT may include KB items: \"\n        \"owner-written answers (kind entry) and excerpts from the \"\n        \"business's own documents (kind chunk, with source); answer from \"\n        \"them and never go beyond what they say. CONTEXT may also include \"\n        \"MEMORY notes about THIS customer (preferences, past issues, \"\n        \"journey position); personalize using them. CONTEXT may include \"\n        \"an AGENT persona (name + instructions); when present, answer AS \"\n        \"that agent and follow its instructions. \"\n        \"NEVER promise refunds, discounts or delivery dates; NEVER mention \"\n        \"internal systems. If the context is insufficient or the customer \"\n        \"needs a human, set needs_human=true. \" + tone_line +\n        ' Reply ONLY with JSON: {\"reply\": \"...\", \"needs_human\": false, '\n        '\"confidence\": 0.0}' + _security_rules()\n    )\n\n\n#: D5 phone-call rules appended to the brain prompt for voice turns: the\n#: reply is read aloud by text-to-speech, so it must be short plain speech.\nVOICE_RULES = (\n    \" This is a LIVE PHONE CALL: your reply is read aloud by text-to-speech.\"\n    \" Use at most two short sentences of plain spoken words - no lists, no\"\n    \" links, no emoji, no symbols, no order codes read character by\"\n    \" character. CONTEXT may include call_transcript (earlier turns of this\"\n    \" call); stay consistent with it. If the caller wants a person, is\"\n    \" upset, or asks for anything you cannot answer from CONTEXT, set\"\n    \" needs_human=true.\"\n)\n\n\ndef _security_rules() -> str:\n    \"\"\"The override-proof trust-boundary block (portal_guard) appended to\n    every brain prompt. Fail-soft: an import problem never silences the\n    assistant, it only loses the extra block.\"\"\"\n    try:\n        import portal_guard\n\n        return portal_guard.SECURITY_RULES\n    except Exception:\n        return \"\"\n\n\ndef _reason(cur, client_id: int, conversation_id: int, contact_id: str,\n            contact_name: str, message_text: str,\n            tone: str, *, channel: str = \"\",\n            extra_context: Optional[Dict[str, Any]] = None,\n            usage_feature: str = \"brain\"\n            ) -> Tuple[Optional[Dict[str, Any]], Dict[str, Any]]:\n    \"\"\"Run the budgeted tools, then one LLM call.\n\n    Returns (llm_payload_or_None, grounding_dict). Never raises beyond\n    what the callers already guard. D5: ``channel=\"voice\"`` adds the\n    spoken-reply rules, ``extra_context`` (e.g. the live call transcript)\n    rides the same sanitised CONTEXT, ``usage_feature`` tags the ledger.\n    \"\"\"\n    started = time.time()\n    # \u00a7241 execution trace: the input's length only (the text stays in the\n    # messages table, so retention and deletes keep covering it)\n    grounding: Dict[str, Any] = {\"tools\": [],\n                                 \"input_chars\": len(str(message_text or \"\").strip())}\n    context: Dict[str, Any] = {}\n    calls = 0\n\n    # Trust boundary first (portal_guard): a message that tries to rewrite\n    # the assistant's instructions never reaches the tools or the model.\n    guard_mode = \"standard\"\n    try:\n        import portal_guard\n\n        guard = portal_guard.inspect(message_text)\n        guard_mode = portal_guard.mode()\n        grounding[\"guard\"] = dict(portal_guard.summary(guard),\n                                  mode=guard_mode)\n        if portal_guard.blocks(guard, guard_mode):\n            grounding[\"reason\"] = \"injection_suspected\"\n            grounding[\"llm_called\"] = False\n            return None, grounding\n    except Exception as error:\n        logger.warning(\"brain guard inspect failed: %s\", error)\n\n    def budget_left() -> bool:\n        return calls < MAX_TOOL_CALLS\n\n    context[\"conversation\"] = tool_recent_messages(cur, client_id,\n                                                   conversation_id, 10)\n    calls += 1\n    orders = tool_customer_orders(cur, client_id, contact_id, 3)\n    calls += 1\n    if orders:\n        context[\"orders\"] = orders\n        grounding[\"tools\"].append(\"customer_orders\")\n    kb = tool_search_kb(cur, client_id, message_text, 3)\n    calls += 1\n    if kb:\n        context[\"kb\"] = kb\n        grounding[\"tools\"].append(\"search_kb\")\n    facts = tool_business_facts(cur, client_id, message_text, 3)\n    calls += 1\n    if facts:\n        context[\"business\"] = facts\n        grounding[\"tools\"].append(\"business_facts\")\n    memories = tool_customer_memory(cur, client_id, contact_id, 3)\n    calls += 1\n    if memories:\n        context[\"memory\"] = memories\n        grounding[\"tools\"].append(\"customer_memory\")\n    agent = None\n    try:\n        import portal_agents\n\n        agent = portal_agents.agent_for_conversation(cur, client_id,\n                                                     conversation_id)\n    except Exception:\n        agent = None\n    calls += 1\n    if agent:\n        context[\"agent\"] = {\"name\": agent.get(\"name\"),\n                            \"instructions\":\n                            str(agent.get(\"instructions\") or \"\")[:400]}\n        grounding[\"tools\"].append(\"agent_persona\")\n        grounding[\"agent_id\"] = agent.get(\"id\")\n        grounding[\"agent_name\"] = str(agent.get(\"name\") or \"\")[:80]\n        in_hours = True\n        try:\n            import portal_agents as _agents_hours\n            in_hours = _agents_hours.agent_in_hours(agent) is not False\n        except Exception:\n            in_hours = True\n        grounding[\"agent_in_hours\"] = in_hours\n        grounding[\"agent_auto_reply\"] = (\n            agent.get(\"can_auto_reply\", True) is not False and in_hours\n        )\n        if str(agent.get(\"tone\") or \"\").strip():\n            tone = str(agent.get(\"tone\"))\n    profile = tool_customer_profile(cur, client_id, contact_id)\n    if profile.get(\"language\"):\n        context[\"language\"] = profile[\"language\"]\n        grounding[\"tools\"].append(\"customer_profile\")\n    sales = None\n    try:\n        import portal_sales\n        import portal_txn\n\n        # \u00a7237: qualifiers / concern + the owner's approved answer\n        with portal_txn.savepoint(cur, None, \"of_sales_ctx\"):\n            sales = portal_sales.context_for(cur, client_id, conversation_id,\n                                             contact_id, message_text)\n    except Exception as error:\n        logger.info(\"brain sales context skipped: %s\", error)\n        sales = None\n    if sales:\n        context[\"sales\"] = sales\n        grounding[\"tools\"].append(\"sales_context\")\n        grounding[\"sales\"] = {\n            \"stage\": sales.get(\"stage\"),\n            \"ask_next\": sales.get(\"ask_next\") or \"\",\n            \"objection\": (sales.get(\"objection\") or {}).get(\"kind\") or \"\",\n            \"approved_answer\": bool((sales.get(\"objection\") or {})\n                                    .get(\"approved_answer\")),\n        }\n    loyalty = None\n    try:\n        import portal_retention\n        import portal_txn\n\n        # \u00a7238: tier / past orders / favourite item (no offers, no codes)\n        with portal_txn.savepoint(cur, None, \"of_loyalty_ctx\"):\n            loyalty = portal_retention.context_for(cur, client_id, contact_id)\n    except Exception as error:\n        logger.info(\"brain loyalty context skipped: %s\", error)\n        loyalty = None\n    if loyalty:\n        context[\"loyalty\"] = loyalty\n        grounding[\"tools\"].append(\"loyalty_context\")\n        grounding[\"loyalty\"] = {\"tier\": loyalty.get(\"tier\") or \"\",\n                                \"orders\": loyalty.get(\"orders\") or 0}\n    grounding[\"conversation_messages\"] = len(context[\"conversation\"])\n    grounding[\"kb_ids\"] = [e[\"id\"] for e in kb if e.get(\"kind\", \"entry\") == \"entry\"]\n    grounding[\"knowledge_ids\"] = [e[\"id\"] for e in kb if e.get(\"kind\") == \"chunk\"]\n    grounding[\"citations\"] = [\n        {\"source\": e.get(\"source\") or \"\", \"section\": e.get(\"title\") or \"\",\n         \"score\": e.get(\"score\") or 0}\n        for e in kb if e.get(\"kind\") == \"chunk\"]\n    grounding[\"fact_ids\"] = [f[\"id\"] for f in facts]\n    grounding[\"memory_ids\"] = [m[\"id\"] for m in memories]\n    grounding[\"order_ids\"] = [o[\"id\"] for o in orders]\n    del budget_left\n\n    context[\"customer_name\"] = str(contact_name or \"\")\n    context[\"customer_message\"] = str(message_text or \"\")\n    if channel:\n        context[\"channel\"] = str(channel)[:20]\n        grounding[\"channel\"] = str(channel)[:20]\n    if isinstance(extra_context, dict):\n        for key, value in extra_context.items():\n            if key not in context:\n                context[str(key)[:40]] = value\n    try:\n        import portal_guard\n\n        context = portal_guard.sanitize_context(context)\n    except Exception:\n        pass\n\n    import portal_llm\n\n    _agent_id = 0\n    try:\n        if agent and agent.get(\"id\"):\n            _agent_id = int(agent.get(\"id\") or 0)\n    except Exception:\n        _agent_id = 0\n    system_prompt = _system_prompt(tone)\n    if channel == \"voice\":\n        system_prompt += VOICE_RULES\n    if \"sales\" in context:\n        try:\n            import portal_sales\n\n            system_prompt += portal_sales.SALES_RULES\n        except Exception:\n            pass\n    if \"loyalty\" in context:\n        try:\n            import portal_retention\n\n            system_prompt += portal_retention.LOYALTY_RULES\n        except Exception:\n            pass\n    model_started = time.time()\n    with portal_llm.usage_scope(usage_feature or \"brain\", client_id, cur,\n                                agent_id=_agent_id) as scope:\n        payload = portal_llm.chat_json(\n            system_prompt,\n            json.dumps(context, ensure_ascii=False, default=str),\n            max_tokens=300,\n        )\n    grounding[\"llm_called\"] = payload is not None\n    grounding[\"timings_ms\"] = {\n        \"tools\": int((model_started - started) * 1000),\n        \"model\": int((time.time() - model_started) * 1000)}\n    grounding[\"model_calls\"] = _scope_calls(scope)\n    if agent and str(agent.get(\"instructions\") or \"\").strip():\n        grounding[\"_private\"] = [str(agent.get(\"instructions\"))[:400]]\n    return payload, grounding\n\n\ndef _scope_calls(scope: Any) -> List[Dict[str, Any]]:\n    \"\"\"The LLM calls a usage_scope saw (model, tokens, latency, ok, route).\"\"\"\n    calls = getattr(scope, \"calls\", None)\n    return [dict(call) for call in calls if isinstance(call, dict)] \\\n        if isinstance(calls, list) else []\n\n\ndef _decide(payload: Optional[Dict[str, Any]],\n            grounding: Dict[str, Any]) -> Tuple[str, str, Dict[str, Any]]:\n    \"\"\"Map the LLM payload + policy to (decision, reply, grounding).\"\"\"\n    private = grounding.pop(\"_private\", None) or []\n    if grounding.get(\"reason\") == \"injection_suspected\":\n        return \"handoff\", \"\", grounding\n    if not isinstance(payload, dict):\n        grounding[\"reason\"] = \"llm_unavailable\"\n        return \"handoff\", \"\", grounding\n    try:\n        confidence = float(payload.get(\"confidence\") or 0)\n    except Exception:\n        confidence = 0\n    reply = str(payload.get(\"reply\") or \"\").strip()\n    needs_human = bool(payload.get(\"needs_human\"))\n    grounding[\"confidence\"] = confidence\n    if needs_human:\n        grounding[\"reason\"] = \"needs_human\"\n        return \"handoff\", \"\", grounding\n    if confidence < MIN_CONFIDENCE:\n        grounding[\"reason\"] = \"low_confidence\"\n        return \"handoff\", \"\", grounding\n    violations = policy_check(reply)\n    grounding[\"policy_violations\"] = violations\n    if violations:\n        grounding[\"reason\"] = \"policy:\" + violations[0]\n        return \"handoff\", \"\", grounding\n    leaks = _output_guard(reply, private)\n    if leaks:\n        grounding[\"output_violations\"] = leaks\n        grounding[\"reason\"] = \"output_guard:\" + leaks[0]\n        return \"handoff\", \"\", grounding\n    if not reply:\n        grounding[\"reason\"] = \"empty_reply\"\n        return \"handoff\", \"\", grounding\n    return \"send\", reply[:MAX_DRAFT_CHARS], grounding\n\n\ndef _output_guard(reply: str, private) -> List[str]:\n    \"\"\"Reply-side leak check (portal_guard.check_output); fail-open.\"\"\"\n    try:\n        import portal_guard\n\n        return portal_guard.check_output(reply, private)\n    except Exception:\n        return []\n\n\ndef _write_trace(cur, client_id: int, conversation_id: int, kind: str,\n                 decision: str, grounding: Dict[str, Any]) -> None:\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(TRACES_TABLE) +\n        \" (client_id, conversation_id, kind, decision, grounding)\"\n        \" VALUES (%s, %s, %s, %s, CAST(%s AS JSONB))\",\n        (client_id, conversation_id, kind, decision,\n         json.dumps(grounding, ensure_ascii=False, default=str)),\n    )\n\n\n# ---------------------------------------------------------------------------\n# Ingest hook (autonomy == auto only) + owner draft API\n# ---------------------------------------------------------------------------\n\ndef _record_guard_block(cur, client_id: int, conversation_id: int,\n                        grounding: Dict[str, Any], source: str) -> None:\n    \"\"\"Audit a blocked input/output without leaking its contents.\"\"\"\n    try:\n        import portal_guard\n\n        reason = str(grounding.get(\"reason\") or \"\")\n        result = grounding.get(\"guard\") or {}\n        if reason.startswith(\"output_guard:\"):\n            result = {\"score\": 0, \"level\": \"high\",\n                      \"signals\": [reason.split(\":\", 1)[1]]}\n        portal_guard.record_block(cur, client_id, conversation_id, result,\n                                  source, db=portal_db)\n    except Exception as error:\n        logger.warning(\"brain guard audit failed: %s\", error)\n\n\ndef _handoff(cur, client_id: int, conversation_id: int,\n             grounding: Dict[str, Any]) -> None:\n    \"\"\"A handoff decision under 'auto' autonomy is a real event, not a\n    silent trace: needs_human / low_confidence / policy blocks / suspected\n    prompt injection / output leaks open ONE escalation per conversation\n    (portal_escalation: assignee + bell + optional email). Platform problems\n    (llm_unavailable, empty_reply) are not customer situations and never page\n    the team. Never raises.\"\"\"\n    reason = str(grounding.get(\"reason\") or \"\")\n    if reason == \"injection_suspected\" or reason.startswith(\"output_guard:\"):\n        _record_guard_block(cur, client_id, conversation_id, grounding,\n                            \"brain\")\n    if not (reason in (\"needs_human\", \"low_confidence\", \"injection_suspected\")\n            or reason.startswith(\"policy:\")\n            or reason.startswith(\"output_guard:\")):\n        return\n    try:\n        import portal_escalation\n\n        confidence = grounding.get(\"confidence\")\n        note = \"AI handoff: \" + reason\n        if isinstance(confidence, (int, float)) and reason == \"low_confidence\":\n            note += \" (confidence \" + str(round(float(confidence), 2)) + \")\"\n        if reason == \"injection_suspected\":\n            note = (\"Suspicious message: the customer text tried to change \"\n                    \"the assistant's instructions (\" +\n                    \", \".join((grounding.get(\"guard\") or {}).get(\"signals\")\n                              or [])[:120] + \"). Please review and reply.\")\n        elif reason.startswith(\"output_guard:\"):\n            note = (\"The AI reply was withheld by the output guard (\" +\n                    reason.split(\":\", 1)[1] + \"). Please review and reply.\")\n        portal_escalation.escalate(cur, client_id, conversation_id, reason,\n                                   \"ai\", note=note)\n    except Exception as error:\n        logger.warning(\"brain handoff escalation failed: %s\", error)\n\n\ndef maybe_answer(client_id, conversation_id, contact_id, contact_name,\n                 body, conn) -> Optional[bool]:\n    \"\"\"Ingest hook: answer under 'auto' autonomy; return True when the\n    brain queued the reply (the one-reply law claims it as 'brain').\"\"\"\n    text = str(body or \"\").strip()\n    if not text:\n        return None\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            settings = _load_settings(cur, client_id)\n            if effective_autonomy(str(settings.get(\"autonomy\") or \"\")) \\\n                    != \"auto\":\n                return None\n            if str(contact_id or \"\").startswith((\"igc:\", \"fbc:\")):\n                # \u00a7228: a comment answer is PUBLIC - only when the owner\n                # turned on comment auto-reply (else it waits in the inbox)\n                import portal_instagram\n\n                if not portal_instagram.comment_auto_reply(cur, client_id):\n                    return None\n            payload, grounding = _reason(\n                cur, client_id, int(conversation_id or 0),\n                str(contact_id or \"\"), str(contact_name or \"\"), text,\n                str(settings.get(\"tone\") or \"\"))\n            decision, reply, grounding = _decide(payload, grounding)\n            if decision == \"send\" and grounding.get(\"agent_auto_reply\") \\\n                    is False:\n                # Persona permission: drafts only - the owner sends.\n                decision = \"handoff\"\n                grounding[\"reason\"] = \"agent_draft_only\"\n            _write_trace(cur, client_id, int(conversation_id or 0),\n                         \"ingest_answer\", decision, grounding)\n            if decision != \"send\":\n                _handoff(cur, client_id, int(conversation_id or 0), grounding)\n                return None\n            payload_out = {\n                \"external_user_id\": str(contact_id or \"\"),\n                \"body\": reply,\n                \"conversation_id\": conversation_id,\n                \"source\": \"ai_brain\",\n            }\n            if str(contact_name or \"\").strip():\n                payload_out[\"target_display_name\"] = str(contact_name)\n            import portal_channels\n\n            channel = portal_channels.channel_for_contact(contact_id)\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(portal_db.CMD_TABLE) +\n                \" (client_id, channel, action, payload, status,\"\n                \" requested_by, created_at, updated_at) \"\n                \"VALUES (%s, %s, 'send_message',\"\n                \" CAST(%s AS JSONB), 'pending', NULL, NOW(), NOW()) \"\n                \"RETURNING id\",\n                (client_id, channel, json.dumps(payload_out)),\n            )\n            portal_db.log_action(\n                cur, client_id, \"ai.answer\", \"automation\",\n                None, conversation_id,\n                \"Brain answered (tools: \" +\n                \",\".join(grounding.get(\"tools\") or [\"none\"]) + \").\",\n            )\n            return True\n    except Exception as error:\n        logger.warning(\"brain maybe_answer failed: %s\", error)\n        return None\n\n\ndef voice_answer(cur, client_id: int, conversation_id: int, contact_id: str,\n                 contact_name: str, utterance: str,\n                 transcript: Optional[List[Dict[str, str]]] = None\n                 ) -> Tuple[str, str, Dict[str, Any]]:\n    \"\"\"D5 phone AI turn: the same guard -> tools -> one LLM call ->\n    policy/output-guard pipeline as a chat answer, with spoken-reply rules.\n\n    Returns (decision \"send\"|\"handoff\", reply, grounding). The caller\n    (portal_voice) owns the TwiML; this writes the trace and, on a real\n    handoff, opens the usual escalation. Voice never runs below 'auto'\n    autonomy or for a draft-only persona. Never raises.\n    \"\"\"\n    grounding: Dict[str, Any] = {\"channel\": \"voice\"}\n    try:\n        _ensure_ddl(cur)\n        settings = _load_settings(cur, client_id)\n        if effective_autonomy(str(settings.get(\"autonomy\") or \"\")) != \"auto\":\n            grounding[\"reason\"] = \"autonomy_not_auto\"\n            return \"handoff\", \"\", grounding\n        extra = {}\n        if transcript:\n            extra[\"call_transcript\"] = [\n                {\"role\": str(turn.get(\"role\") or \"\")[:10],\n                 \"text\": str(turn.get(\"text\") or \"\")[:300]}\n                for turn in transcript[-8:] if isinstance(turn, dict)]\n        payload, grounding = _reason(\n            cur, client_id, int(conversation_id or 0), str(contact_id or \"\"),\n            str(contact_name or \"\"), str(utterance or \"\"),\n            str(settings.get(\"tone\") or \"\"), channel=\"voice\",\n            extra_context=extra, usage_feature=\"voice_call\")\n        decision, reply, grounding = _decide(payload, grounding)\n        if decision == \"send\" and grounding.get(\"agent_auto_reply\") is False:\n            decision = \"handoff\"\n            grounding[\"reason\"] = \"agent_draft_only\"\n        _write_trace(cur, client_id, int(conversation_id or 0),\n                     \"voice_answer\", decision, grounding)\n        if decision != \"send\":\n            if int(conversation_id or 0) > 0:\n                _handoff(cur, client_id, int(conversation_id), grounding)\n            elif str(grounding.get(\"reason\") or \"\") == \"injection_suspected\":\n                _record_guard_block(cur, client_id, 0, grounding, \"voice\")\n            return \"handoff\", \"\", grounding\n        return \"send\", reply, grounding\n    except Exception as error:\n        logger.warning(\"brain voice_answer failed: %s\", error)\n        grounding[\"reason\"] = \"error\"\n        return \"handoff\", \"\", grounding\n\n\ndef draft_reply(cur, client_id: int, conversation_id: int,\n                message_text: str = \"\") -> Dict[str, Any]:\n    \"\"\"Owner-facing draft (autonomy 'suggest'): never queues a send.\"\"\"\n    _ensure_ddl(cur)\n    settings = _load_settings(cur, client_id)\n    payload, grounding = _reason(\n        cur, client_id, conversation_id, \"\", \"\", message_text,\n        str(settings.get(\"tone\") or \"\"))\n    decision, reply, grounding = _decide(payload, grounding)\n    if (str(grounding.get(\"reason\") or \"\") == \"injection_suspected\"\n            or str(grounding.get(\"reason\") or \"\").startswith(\"output_guard:\")):\n        _record_guard_block(cur, client_id, conversation_id, grounding,\n                            \"brain_draft\")\n    _write_trace(cur, client_id, conversation_id, \"draft\", decision,\n                 grounding)\n    portal_db.log_action(\n        cur, client_id, \"ai.draft\", \"human\",\n        None, conversation_id,\n        \"Brain draft requested (\" + decision + \").\",\n    )\n    result = {\"decision\": decision,\n              \"draft\": reply,\n              \"grounding\": grounding,\n              \"autonomy\": settings.get(\"autonomy\")}\n    # KB auto-draft (owner decision, admin panel): when on, a draft also\n    # ships a saveable knowledge-base entry so good answers stop being\n    # one-offs. Fail-soft: the plain draft is always there.\n    try:\n        import platform_settings\n        if platform_settings.flag(\"kb_autodraft\") and reply:\n            result[\"kb_entry\"] = {\n                \"title\": (message_text or \"\").strip()[:120]\n                         or \"Saved answer\",\n                \"content\": str(reply),\n            }\n    except Exception:\n        pass\n    return result\n\n\n# ---------------------------------------------------------------------------\n# Owner API: settings / draft / trace\n# ---------------------------------------------------------------------------\n\n@bp.get(\"/brain/settings\")\ndef get_brain_settings():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            settings = _load_settings(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    controls = platform_controls()\n    settings[\"platform\"] = {\n        \"paused\": bool(controls.get(\"kill_switch\")),\n        \"autonomy_cap\": str(controls.get(\"autonomy_cap\") or \"auto\"),\n        \"daily_call_cap\": int(controls.get(\"daily_call_cap\") or 0),\n        \"guard_mode\": str(controls.get(\"guard_mode\") or \"standard\"),\n        \"effective_autonomy\": effective_autonomy(\n            str(settings.get(\"autonomy\") or \"\"), controls),\n    }\n    return jsonify({\"settings\": settings}), 200\n\n\n@bp.put(\"/brain/settings\")\ndef put_brain_settings():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    autonomy = payload.get(\"autonomy\")\n    tone = payload.get(\"tone\")\n    if autonomy not in AUTONOMY_LEVELS:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"autonomy must be one of off|suggest|auto.\",\n        }}), 400\n    if tone is not None and not isinstance(tone, str):\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"tone must be a string.\",\n        }}), 400\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            try:\n                import portal_snapshots\n\n                portal_snapshots.before_change(\n                    cur, client_id, \"brain\",\n                    str(principal.get(\"email\") or principal.get(\"user_id\") or \"\"))\n            except Exception:\n                pass\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(SETTINGS_TABLE) +\n                \" (client_id, autonomy, tone, updated_at)\"\n                \" VALUES (%s, %s, %s, NOW())\"\n                \" ON CONFLICT (client_id) DO UPDATE SET\"\n                \" autonomy = EXCLUDED.autonomy,\"\n                \" tone = EXCLUDED.tone, updated_at = NOW()\",\n                (client_id, autonomy, str(tone or \"\")[:200]),\n            )\n            portal_db.log_action(\n                cur, client_id, \"ai.settings\", \"human\",\n                None, None,\n                \"Brain autonomy set to \" + str(autonomy) + \".\",\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"settings\": {\"autonomy\": autonomy,\n                                 \"tone\": str(tone or \"\")}}), 200\n\n\n@bp.post(\"/brain/draft\")\ndef draft_brain_reply():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    try:\n        conversation_id = int(payload.get(\"conversation_id\") or 0)\n    except Exception:\n        conversation_id = 0\n    if conversation_id <= 0:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"conversation_id (positive integer) is required.\",\n        }}), 400\n    message_text = str(payload.get(\"message\") or \"\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"SELECT 1 FROM \" + portal_db._q(portal_db.CONV_TABLE) +\n                \" WHERE id = %s AND client_id = %s LIMIT 1\",\n                (conversation_id, client_id),\n            )\n            if not portal_db.rows(cur):\n                conn.rollback()\n                return jsonify({\"error\": {\n                    \"code\": \"not_found\",\n                    \"message\": \"No such conversation in this workspace.\",\n                }}), 404\n            result = draft_reply(cur, client_id, conversation_id,\n                                 message_text)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify(result), 200\n\n\n@bp.get(\"/brain/trace\")\ndef list_brain_traces():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    try:\n        conversation_id = int(request.args.get(\"conversation_id\") or 0)\n    except Exception:\n        conversation_id = 0\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            sql = (\"SELECT id, conversation_id, kind, decision, grounding,\"\n                   \" created_at FROM \" + portal_db._q(TRACES_TABLE) +\n                   \" WHERE client_id = %s\")\n            params: Tuple[Any, ...] = (client_id,)\n            if conversation_id > 0:\n                sql += \" AND conversation_id = %s\"\n                params = (client_id, conversation_id)\n            sql += \" ORDER BY id DESC LIMIT 10\"\n            cur.execute(sql, params)\n            rows = portal_db.rows(cur)\n        conn.commit()\n    finally:\n        conn.close()\n    out = [{\"id\": int(r.get(\"id\") or 0),\n            \"conversation_id\": r.get(\"conversation_id\"),\n            \"kind\": str(r.get(\"kind\") or \"\"),\n            \"decision\": str(r.get(\"decision\") or \"\"),\n            \"grounding\": r.get(\"grounding\"),\n            \"created_at\": str(r.get(\"created_at\") or \"\")}\n           for r in rows]\n    return jsonify({\"traces\": out}), 200\n\n\n# ---------------------------------------------------------------------------\n# v2: structured business context (facts) - owner CRUD\n# ---------------------------------------------------------------------------\n\ndef _shape_fact(row: Dict[str, Any]) -> Dict[str, Any]:\n    return {\"id\": int(row.get(\"id\") or 0),\n            \"kind\": str(row.get(\"kind\") or \"policy\"),\n            \"label\": str(row.get(\"label\") or \"\"),\n            \"content\": str(row.get(\"content\") or \"\"),\n            \"keywords\": str(row.get(\"keywords\") or \"\"),\n            \"is_active\": bool(row.get(\"is_active\")),\n            \"updated_at\": str(row.get(\"updated_at\") or \"\")}\n\n\n@bp.get(\"/brain/facts\")\ndef list_brain_facts():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"SELECT id, kind, label, content, keywords, is_active,\"\n                \" updated_at FROM \" + portal_db._q(FACTS_TABLE) +\n                \" WHERE client_id = %s\"\n                \" ORDER BY is_active DESC, id DESC LIMIT %s\",\n                (client_id, max(1, min(500, FACTS_LIMIT))),\n            )\n            rows = portal_db.rows(cur)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"facts\": [_shape_fact(r) for r in rows]}), 200\n\n\n@bp.post(\"/brain/facts\")\ndef save_brain_fact():\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    fact_id = 0\n    try:\n        fact_id = int(payload.get(\"id\") or 0)\n    except Exception:\n        fact_id = 0\n    kind = str(payload.get(\"kind\") or \"policy\")\n    label = str(payload.get(\"label\") or \"\").strip()\n    content = str(payload.get(\"content\") or \"\").strip()\n    keywords = str(payload.get(\"keywords\") or \"\").strip()\n    is_active = payload.get(\"is_active\", True)\n    if not isinstance(is_active, bool):\n        is_active = bool(is_active)\n    if kind not in FACT_KINDS:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"kind must be one of \" + \"|\".join(FACT_KINDS) + \".\",\n        }}), 400\n    if not label or len(label) > 120:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"label is required (max 120 characters).\",\n        }}), 400\n    if not content or len(content) > 2000:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"content is required (max 2000 characters).\",\n        }}), 400\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            try:\n                import portal_snapshots\n\n                portal_snapshots.before_change(\n                    cur, client_id, \"brain_facts\",\n                    str(principal.get(\"email\") or principal.get(\"user_id\") or \"\"))\n            except Exception:\n                pass\n            if fact_id > 0:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(FACTS_TABLE) +\n                    \" SET kind = %s, label = %s, content = %s,\"\n                    \" keywords = %s, is_active = %s, updated_at = NOW()\"\n                    \" WHERE id = %s AND client_id = %s RETURNING id\",\n                    (kind, label[:120], content[:2000], keywords[:200],\n                     is_active, fact_id, client_id),\n                )\n                rows = portal_db.rows(cur)\n                if not rows:\n                    conn.rollback()\n                    return jsonify({\"error\": {\n                        \"code\": \"not_found\",\n                        \"message\": \"No such fact in this workspace.\",\n                    }}), 404\n                action = \"updated\"\n            else:\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(FACTS_TABLE) +\n                    \" (client_id, kind, label, content, keywords,\"\n                    \" is_active, updated_at)\"\n                    \" VALUES (%s, %s, %s, %s, %s, %s, NOW())\"\n                    \" RETURNING id\",\n                    (client_id, kind, label[:120], content[:2000],\n                     keywords[:200], is_active),\n                )\n                rows = portal_db.rows(cur)\n                action = \"created\"\n            portal_db.log_action(\n                cur, client_id, \"brain.facts\", \"human\",\n                None, None,\n                \"Business fact \" + action + \": \" + label[:80] + \".\",\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"fact\": {\"id\": int(rows[0].get(\"id\") or 0),\n                             \"kind\": kind, \"label\": label,\n                             \"content\": content, \"keywords\": keywords,\n                             \"is_active\": is_active}}), 200\n\n\n@bp.delete(\"/brain/facts\")\ndef delete_brain_fact():\n    \"\"\"Soft delete (data-preserving): the row just goes inactive and the\n    owner can re-activate it from the same card.\"\"\"\n    principal, auth_error = _principal_or_error()\n    if auth_error:\n        return auth_error\n    client_id = int(principal.get(\"client_id\") or 0)\n    try:\n        fact_id = int(request.args.get(\"id\") or 0)\n    except Exception:\n        fact_id = 0\n    if fact_id <= 0:\n        return jsonify({\"error\": {\n            \"code\": \"bad_request\",\n            \"message\": \"id (positive integer) is required.\",\n        }}), 400\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            try:\n                import portal_snapshots\n\n                portal_snapshots.before_change(\n                    cur, client_id, \"brain_facts\",\n                    str(principal.get(\"email\") or principal.get(\"user_id\") or \"\"))\n            except Exception:\n                pass\n            cur.execute(\n                \"UPDATE \" + portal_db._q(FACTS_TABLE) +\n                \" SET is_active = FALSE, updated_at = NOW()\"\n                \" WHERE id = %s AND client_id = %s RETURNING id\",\n                (fact_id, client_id),\n            )\n            rows = portal_db.rows(cur)\n            if not rows:\n                conn.rollback()\n                return jsonify({\"error\": {\n                    \"code\": \"not_found\",\n                    \"message\": \"No such fact in this workspace.\",\n                }}), 404\n            portal_db.log_action(\n                cur, client_id, \"brain.facts\", \"human\",\n                None, None,\n                \"Business fact archived (id \" + str(fact_id) + \").\",\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True}), 200\n");
writeNewRepair("omniflow-backend-patch/portal_ai_audit.py", "# \u00a7241: rows written with an AI answer link to its trace", false,
    "\"\"\"Unified AI-action audit (MASTER-UPGRADE platform service).\n\nThe platform already audits everything into ONE table\n(``portal_action_log`` via ``portal_db.log_action``): brain answers and\ndrafts, registry actions (requested / executed / approved / blocked),\nworkflow runs and handoffs, rule firings, escalations, knowledge imports,\napprovals. What was missing is one place to READ the AI's activity as\nsuch, with categories a human understands, instead of grepping actions.\n\nThis module is that read model - no new write path, no second log:\n\n* ``timeline(cur, client_id, days, category, limit)`` - the AI/automation\n  rows of the audit log, each tagged with a category from ``CATEGORIES``;\n* ``overview(cur, client_id, days)`` - counts per category + actor kind,\n  pending approvals, the escalation queue and the AI usage/cost totals -\n  the numbers the Admin AI Control Center will render later.\n\nCategories are a registry of action prefixes (data, not code paths), so a\nnew engine only has to log actions with a known prefix to show up here.\nTenant-scoped; open to API keys (read-only).\n\"\"\"\n\nimport logging\nimport os\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import PortalAuthUnavailable, authenticate_portal_request\n\nlogger = logging.getLogger(\"omniflow.portal-ai-audit\")\n\nbp = Blueprint(\"portal_ai_audit\", __name__, url_prefix=\"/api/v1/portal\")\n\nLOG_TABLE = \"portal_action_log\"\nDEFAULT_DAYS = 7\nMAX_DAYS = int(os.environ.get(\"OF_AI_AUDIT_MAX_DAYS\", \"90\") or 90)\nLIST_LIMIT = int(os.environ.get(\"OF_AI_AUDIT_LIST_MAX\", \"200\") or 200)\n\n#: Actor kinds that mean \"the platform did this, not a person\".\nAI_ACTOR_KINDS: Tuple[str, ...] = (\"automation\", \"bot\", \"workflow\", \"system\", \"ai\")\n\n#: (key, label, action prefixes) - first match wins, in this order.\nCATEGORIES: Tuple[Tuple[str, str, Tuple[str, ...]], ...] = (\n    (\"handoffs\", \"Handoffs\", (\"escalation.\", \"bot.escalated\", \"workflow.handoff\")),\n    (\"approvals\", \"Approvals\", (\"approval.\",)),\n    (\"actions\", \"Actions\", (\"action.\",)),\n    (\"workflows\", \"Workflows\", (\"workflow.\",)),\n    (\"answers\", \"Answers\", (\"ai.answer\", \"kb.auto_reply\")),\n    (\"drafts\", \"Drafts\", (\"ai.draft\",)),\n    (\"rules\", \"Rules\", (\"rule_fired\", \"rule.\", \"listen.\", \"routing.\")),\n    (\"knowledge\", \"Knowledge\", (\"kb.\",)),\n    (\"memory\", \"Memory & identity\", (\"memory.\", \"identity.\")),\n    (\"notifications\", \"Notifications\", (\"notifications.\", \"alert.\")),\n    (\"settings\", \"AI settings\", (\"ai.settings\", \"agent.\", \"brain.\")),\n    (\"security\", \"Security\", (\"ai.guard\",)),\n)\nCATEGORY_KEYS = tuple(k for k, _l, _p in CATEGORIES)\n\n\ndef categorize(action: str, actor_kind: str = \"\") -> str:\n    action = str(action or \"\")\n    for key, _label, prefixes in CATEGORIES:\n        for prefix in prefixes:\n            if action.startswith(prefix):\n                return key\n    return \"other\"\n\n\ndef _patterns() -> List[str]:\n    out: List[str] = []\n    for _key, _label, prefixes in CATEGORIES:\n        for prefix in prefixes:\n            out.append(prefix + \"%\")\n    return out\n\n\ndef _days(value: Any) -> int:\n    try:\n        days = int(value or DEFAULT_DAYS)\n    except Exception:\n        days = DEFAULT_DAYS\n    return max(1, min(MAX_DAYS, days))\n\n\ndef _iso(value: Any) -> Optional[str]:\n    if value is None or value == \"\":\n        return None\n    return value.isoformat() if hasattr(value, \"isoformat\") else str(value)\n\n\ndef _guarded(cur, label: str, fn):\n    \"\"\"Run one optional block behind a SAVEPOINT so a missing table never\n    aborts the surrounding transaction; None on failure.\"\"\"\n    try:\n        cur.execute(\"SAVEPOINT of_ai_audit\")\n        value = fn()\n        cur.execute(\"RELEASE SAVEPOINT of_ai_audit\")\n        return value\n    except Exception as error:\n        logger.warning(\"overview %s failed: %s\", label, error)\n        try:\n            cur.execute(\"ROLLBACK TO SAVEPOINT of_ai_audit\")\n        except Exception:\n            pass\n        return None\n\n\ndef _select_rows(cur, client_id: int, days: int, limit: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT id, action, actor_kind, actor_user_id, conversation_id, note,\"\n        \" created_at FROM \" + portal_db._q(LOG_TABLE) +\n        \" WHERE client_id = %s\"\n        \" AND created_at > NOW() - make_interval(days => %s)\"\n        \" AND (actor_kind = ANY(%s) OR action LIKE ANY(%s))\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (client_id, days, list(AI_ACTOR_KINDS), _patterns(), limit),\n    )\n    return portal_db.rows(cur)\n\n\ndef timeline(cur, client_id: int, days: int = DEFAULT_DAYS,\n             category: str = \"\", limit: int = LIST_LIMIT) -> List[Dict[str, Any]]:\n    \"\"\"AI / automation audit rows, newest first, tagged with a category.\"\"\"\n    days = _days(days)\n    limit = max(1, min(LIST_LIMIT, int(limit or LIST_LIMIT)))\n    fetch = limit if not category else LIST_LIMIT\n    items: List[Dict[str, Any]] = []\n    for row in _select_rows(cur, client_id, days, fetch):\n        key = categorize(row.get(\"action\"), row.get(\"actor_kind\"))\n        if category and key != category:\n            continue\n        items.append({\n            \"id\": int(row.get(\"id\") or 0),\n            \"action\": str(row.get(\"action\") or \"\"),\n            \"category\": key,\n            \"actor_kind\": str(row.get(\"actor_kind\") or \"\"),\n            \"actor_user_id\": (int(row[\"actor_user_id\"])\n                              if row.get(\"actor_user_id\") else None),\n            \"conversation_id\": (int(row[\"conversation_id\"])\n                                if row.get(\"conversation_id\") else None),\n            \"note\": str(row.get(\"note\") or \"\"),\n            \"created_at\": _iso(row.get(\"created_at\")),\n        })\n        if len(items) >= limit:\n            break\n    return items\n\n\ndef overview(cur, client_id: int, days: int = DEFAULT_DAYS) -> Dict[str, Any]:\n    \"\"\"Counts per category / actor kind for the window + the live queues\n    (pending approvals, open escalations) + AI usage totals. Each block is\n    fail-soft so one missing table never blanks the card.\"\"\"\n    days = _days(days)\n    by_category = {key: 0 for key in CATEGORY_KEYS}\n    by_category[\"other\"] = 0\n    by_actor: Dict[str, int] = {}\n    total = 0\n    cur.execute(\n        \"SELECT action, actor_kind, COUNT(*) AS n FROM \" + portal_db._q(LOG_TABLE) +\n        \" WHERE client_id = %s\"\n        \" AND created_at > NOW() - make_interval(days => %s)\"\n        \" AND (actor_kind = ANY(%s) OR action LIKE ANY(%s))\"\n        \" GROUP BY action, actor_kind\",\n        (client_id, days, list(AI_ACTOR_KINDS), _patterns()),\n    )\n    for row in portal_db.rows(cur):\n        n = int(row.get(\"n\") or 0)\n        total += n\n        key = categorize(row.get(\"action\"), row.get(\"actor_kind\"))\n        by_category[key] = by_category.get(key, 0) + n\n        actor = str(row.get(\"actor_kind\") or \"unknown\")\n        by_actor[actor] = by_actor.get(actor, 0) + n\n    out: Dict[str, Any] = {\n        \"days\": days,\n        \"total\": total,\n        \"by_category\": [\n            {\"key\": key, \"label\": label, \"count\": by_category.get(key, 0)}\n            for key, label, _p in CATEGORIES\n        ] + [{\"key\": \"other\", \"label\": \"Other\", \"count\": by_category.get(\"other\", 0)}],\n        \"by_actor\": by_actor,\n        \"approvals_pending\": None,\n        \"escalations\": None,\n        \"usage\": None,\n    }\n    def _approvals():\n        import portal_approvals\n\n        cur.execute(\n            \"SELECT COUNT(*) AS n FROM \" + portal_db._q(portal_approvals.TABLE) +\n            \" WHERE client_id = %s AND status = 'pending'\",\n            (client_id,),\n        )\n        rows = portal_db.rows(cur)\n        return int((rows[0] if rows else {}).get(\"n\") or 0)\n\n    def _escalations():\n        import portal_escalation\n\n        portal_escalation._ensure_ddl(cur)\n        return portal_escalation.summary(cur, client_id)\n\n    def _usage():\n        import portal_ai_usage\n\n        portal_ai_usage._ensure_ddl(cur)\n        report = portal_ai_usage.usage_report(cur, client_id, days)\n        return {\"totals\": report[\"totals\"],\n                \"prices_configured\": report[\"prices_configured\"]}\n\n    out[\"approvals_pending\"] = _guarded(cur, \"approvals\", _approvals)\n    out[\"escalations\"] = _guarded(cur, \"escalations\", _escalations)\n    out[\"usage\"] = _guarded(cur, \"usage\", _usage)\n    return out\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\n@bp.get(\"/ai/audit\")\ndef get_audit():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    days = _days(request.args.get(\"days\"))\n    category = str(request.args.get(\"category\") or \"\").strip().lower()\n    if category and category not in CATEGORY_KEYS + (\"other\",):\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"Unknown category.\"}}), 400\n    try:\n        limit = int(request.args.get(\"limit\") or 100)\n    except Exception:\n        limit = 100\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            items = timeline(cur, client_id, days, category, limit)\n            try:\n                # \u00a7241: rows written with an AI answer link to its trace\n                # (agent, model); fail-soft - the plain rows always ship\n                import portal_ai_traces\n                import portal_txn\n\n                with portal_txn.savepoint(cur, conn, \"of_trace_link\"):\n                    items = portal_ai_traces.link_audit(cur, client_id, items)\n            except Exception as error:\n                logger.info(\"ai audit trace links skipped: %s\", error)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"days\": days, \"category\": category, \"items\": items,\n                    \"categories\": [{\"key\": k, \"label\": l}\n                                   for k, l, _p in CATEGORIES]}), 200\n\n\n@bp.get(\"/ai/overview\")\ndef get_overview():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    days = _days(request.args.get(\"days\"))\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            data = overview(cur, client_id, days)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify(data), 200\n");
